/* 平成23年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h23.committeeSessions.push(...[{"id":"h23-20110822-9","meetingId":"h23-cm08","date":"2011年8月22日","dateIso":"2011-08-22","committee":"文教委員会","time":"午後１時００分～午後２時１１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"そうすると、例えば３６人になると２クラスになるのかどうかお伺いしたいと思います。要するに、人数によって、学校によって、そうすると、先生一人一人の目が行き届くとか、また、学習面とか生活面でも、そういう面の格差が出るのかななんていうことを懸念するんですけれど、その辺を教えていただきたいなと思います。","respondent":"和氣学務課長","answer":"これはどう考えてもそういうことは必ず起きますので、２０何人ずつの学級であったりとか、もしくは、学校によっては単学級でそもそも１０何人とかの学級もありますし、その数に応じた指導をしていただくです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"吉田委員","kind":"質問","question":"人数的に、今お話のように、一番下に下限ということは、何人から２クラスというふうにお考えなんでしょうか。２学級ということで。要するに、下限の考え方。","respondent":"和氣学務課長","answer":"標準で１クラス３５人と決まっていますので、３５人を超えたら、３６人から２学級になります。１８人ずつになります。下限は定めてありませんので。","voiceIndex":7,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"基本的には、いきなり日野学園のところでわからなくなっちゃったんですけれども、大崎ブロックのところの８で、３学級で１０２人、この表だと３学級で９０人ですよね。４月の最初に。こういった学校が具体的に通学区域内の希望者が予測したよりも超えてしまうというような状況があるのかどうか、その辺を具体的にどこら辺の学校なのかというところが予測が立っているのかどうか、その辺を教えていただきたい。","respondent":"和氣学務課長","answer":"基本的に通学区域内の子どもたちの人数が増えればクラスを増やさなければいけませんが、今のところは何とかなるというふうに考えてあります。","voiceIndex":11,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"割り返してみると可能数が足りない場合、それをどうしていくのかということと、あともう１点は、転入で予定よりも数が増えてしまったとき、例えば荏原西ブロックの第二延山小学校だと、３クラス１１２人が３クラスで９０人、これ、お答えいただいてからなんですが、これが予定よりももっと転入した場合にどういうふうになるのかというあたりを教えていただきたい。","respondent":"和氣学務課長","answer":"第二延山小学校ですが、これ、例えば途中で増えても、クラスは一度４月で決めますと途中で増やすことはできません。教員が加配されませんのでということで、ぎりぎりまで入っていただくという形になります。","voiceIndex":13,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"そのぎりぎりまでというのがよくわからないんですが、もう一回、日野学園のところは、平成２４年度の受け入れが９０人、転入で１０５人ですよね。マックスでというか。転入生の場合は、それ以上にはならない、受け入れられないということになるわけですか。ここはもういっぱいなのでほかに行ってくださいということになるのか、その辺だけ教えてください。","respondent":"和氣学務課長","answer":"学区域であれば受け入れるしかないです。ですから、４１人になろうと、４２人になろうと受け入れるしかないということです。","voiceIndex":15,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"意見","question":"その辺がもし４月の抽選の段階で枠を超えたら、もうそれは学区域外のところで調節をしていかざるを得ないということですね。はい、わかりました。１カ所かありましたかね。その辺で、これからいろいろな部分で流動的に出てくると思うんですけれども、基準が３５人学級になった、中学校は４０人、その辺でこの基準というものを教育委員会がどう考えているのかというところも１点聞かせてください。","respondent":"和氣学務課長","answer":"今後については事前にわかりますので考えますけれども、ただ、３５人学級が標準にはなったんですが、これをどう扱うかについて、まだ国や都から運用について何の通知も来ていないんです。","voiceIndex":17,"id":"exchange-006"},{"speaker":"渡部委員","kind":"質問・要望","question":"今回また冊子になって学校の案内とかが出るときに、しっかりと１年生が３５人学級というのを明記していただいた上で告知をしっかりしていただきたいというのがまず１つ要望するんですが、今回、伊藤小学校と第二延山小学校は、結局クラスをばらさなかったんですよね。そのまま維持していますよね。というのは、それは４０人学級ですよね。そこのところを教えてください。","respondent":"和氣学務課長","answer":"このまま行ってしまいますと、２年生になったときは４０人に戻ってしまいますので、２つに分けたクラスをまた１つにしなければいけなくなりますが、これについては国がどういうふうにして考えるかという話になると思います。","voiceIndex":20,"id":"exchange-007"},{"speaker":"渡部委員","kind":"質問・要望","question":"ありがとうございました。両方ともわかりました。ですので、丁寧な説明とわかりやすい冊子にしていただいて、過度な競争と言ったらおかしいんですけれども、ないように努力をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-008"},{"speaker":"須藤委員","kind":"質問","question":"今度の新１年生でみんな公立へ入りますよというと、何人ぐらいの人数になるんですか。","respondent":"和氣学務課長","answer":"正確な数字は今すぐ出ませんけれども、１年生で２,３００人程度だというふうに考えております。","voiceIndex":23,"id":"exchange-009"},{"speaker":"須藤委員","kind":"意見","question":"みんな公立へ入るとして２,３００人、今、私学へ行っていますよというお子さんたちも年々増えてきていると思うんですよね。２０台、１０台、それからひとけた台、そういう学校のあり方というものは基本的にどういうふうにお考えになっているのかなと。","respondent":"和氣学務課長","answer":"それぞれの教育のよさがあると考えていいと思います。ただし、あまり小規模校ばかりになってしまうと、そういう中規模なり大規模を望む方たちが入ってこられませんので、その際については、学校の統廃合も含めまして検討する必要があるというふうに私どもは答申で受けてあります。","voiceIndex":25,"id":"exchange-010"},{"speaker":"須藤委員","kind":"意見","question":"いずれにしても、選択制ということで、ただ、小学生の場合は、ほとんど９割ぐらいがもとの学区内に行かれているということで、よく町が、我々もいろいろな話になったけれども、私は強くないと思って前にも言っていたんだけれども、ただ、ちょっと懸念しているのは、児童数が少なくなってきているときに、そういう傾向が非常に顕著になったときに。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":27,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この出版会社に決まったというそれぞれの理由がどこかで見ることができるのか、その辺の選択の理由のところも教えていただきたいのと、特にこのところ関心の高い社会の歴史と公民の分野のところなんですけれども、特にお伺いしたいのは、戦争の記述とか原発の問題とかが議論の中に入っていたかどうか、その辺もお聞かせください。","respondent":"冠木指導課長、齋藤庶務課長","answer":"幾つか質問がございましたので、１つ１つ答えてまいりますけれども、５回の委員会がございまして、それぞれ教科を分けておりまして、７月５日から８月２日まで、それぞれ教育委員会、３時間、４時間と時間をかけまして。日付が今日になっているということで今日、机上配付になっております。まことに申しわけございませんでした。","voiceIndex":32,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"議論の内容についてなんですが、先ほど、最後にお伺いした、このところ新聞でもかなり新しい歴史教科書をつくる会の扱いについていろいろな議論が出ていましたけれども、特に戦争に関する記述、戦争美化の記述が誤っているなどの意見も出ていましたので、その辺の記述に対してとか、あと、今の原発問題なんかで議論がされたのかどうか、その内容をお聞かせください。","respondent":"冠木指導課長","answer":"それぞれ今回の教科書採択については重要なテーマだと、それぞれの教育委員の皆様は認識されておりましたので、内容につきましては、ルールに従ってホームページ等で公開していくことになろうとは思いますけれども、十分に議論は尽くされたというふうに思ってあります。","voiceIndex":35,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"今の質問のところについては、ホームページを後で見ればわかるということでよろしいでしょうか。","respondent":"冠木指導課長","answer":"教科書の採択の事務につきましては、すべて、１つは静謐な環境で採択事務を行うという目的で、８月中は守秘義務、時限秘という形でやらせていただいておりますので、９月以降にそういった形で出すべきものは出してまいりたいというふうに思ってあります。","voiceIndex":37,"id":"exchange-014"},{"speaker":"渡辺副委員長","kind":"質問","question":"今、このスケジュールの中で、最終的な教育委員会の中での審議の日程がありました。前段で、情報ですとか、そういう審議内容を整理される場というんですか、検討会等、この審議の前の事務局の整理みたいな仕組みというか、その辺を教えていただければと思います。","respondent":"冠木指導課長","answer":"その下部組織としまして、教科書調査研究会というものを持ってあります。この２つの研究会、検討委員会で、事実に基づいて教科書の研究をしていただきまして、その資料をつくっていただくと。それは教育委員会の資料となります。","voiceIndex":40,"id":"exchange-015"},{"speaker":"渡辺副委員長","kind":"質問","question":"やはり４年前にもそれぞれ審議をされて決めたものに対して、またやるときに、そういう何か変わることがあるのか、実際変わっているのか、変わるに当たってその論点は何なのか、教えてもらいたい。","respondent":"冠木指導課長","answer":"教科書の記述内容につきましては、４年間のスパンの中で非常に中身も変わってまいりますし、切り口も変わってまいりますので、今回、結果を見ていただくとあれですけれども、かなり変わっております。ですから、もともと採択していたからどうのこうのという議論はございません。","voiceIndex":44,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"心待ちにしていた保育園の新設なので、１日も早く開設していただきたいなと思っているんですけれども、この４番目の事業開始日の、幼稚園は平成２４年１１月からで、保育園はここには無理だということですか。翌年の４月ということで、この辺のスパンが何なのかということと、少しでも埋まって早く受け入れができないのかどうかということが１点です。","respondent":"吉岡保育課長","answer":"保育内容ですけれども、保育内容については、基本的には、今、区内の区立幼稚園あるいは区立保育園でも、４歳児、５歳児につきましては、充実した幼児教育をということで、同等の幼児教育を提供したいという理念のもとに実施していますけれども。","voiceIndex":51,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問","question":"そこはわかりました。基本の料金に延長のところ。特に年齢区分型のところは、保育園で入ったけれども、四、五歳のところは幼稚園に変わるというあたりで幾つかの園で、その辺で親御さんが変わっていくことに対してのご意見とか、とまどいとか、何かその辺があるのかどうか、その辺をお伺いしたいと思います。","respondent":"吉岡保育課長","answer":"それからあと、今後の計画ですが、今、委員おっしゃられたように、この平塚と同じ時期、平成２５年４月に、今現在あります二葉すこやか園が豊葉の杜学園と施設的に一体になりましてリニューアルオープンするという予定になってございまして、それ以降につきましては。","voiceIndex":53,"id":"exchange-018"},{"speaker":"阿久津委員","kind":"質問・要望","question":"幼保一体のところでそれに関連してお聞きしたいんですが、国のほうで今、子ども・子育て新システムの平成２５年からの導入を目指しているということで、関係者の間では、最近、本当によく勉強をされていて、勉強会のお誘いとかも来るんですけれども、品川区においては、今どのような検討をされているのか、また、それがもし導入されることになって、品川区内の幼保施設がどのような変化をしていくのか。","respondent":"吉岡保育課長","answer":"そういう中で品川区といたしましては、国が幼保一体化の事業を進める以前の平成１４年度から二葉すこやか園という幼保一体施設をつくり、独自の展開、幼児教育の一体化、それから幼小の連携という取り組みをずっと続けてきてありますので、当面は現在の体制を維持しながら。","voiceIndex":55,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問","question":"今のこども園のことなんですけれども、まだ国のところがしっかり決まっていないわけですけれども、一括法の関係で、品川も条例はつくることになるんですか。合わせた基準などの条例をつくることになるのか、その辺の流れがどうなっているかよくわからないので教えてください。","respondent":"吉岡保育課長","answer":"条例化のお話ですけれども、当然、新しい法律に基づいた形の中で、新しい法律にのっとった施設をつくるということになれば、一定の条例制定も必要になってこようかと判断していますけれども、それが今現在の認可保育園あるいは認可の幼稚園、それと今。","voiceIndex":57,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"国のところもまだ決まっていないので、今後見極めてというのは当然だと思うんですけれども、この間、品川区は待機児の対策で、保育園、認可もつくってきているし、認証もかなり増えてきている、あと、地域には、認証にも入れなくて認可外の保育園もかなり増えていますし、現実にできているんですが、私はせひ品川区内の子どもたちが、どの施設に入っても等しく大事にされるようにというところにおいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後のところを伺うんですが、私も８月２１日の広報を見たらお知らせが載っていたんですが、お知らせが出る前に、ここ、前の店舗が空きになったんだけれども、ここ、何ができるんだろうという質問をちょっと前に受けたばっかりだったので、やっぱり保育園だと思って、保育園が足りないので、認証ができることは地域の方が喜ばれると思うんですが、これもそうなんです。","respondent":"伊崎待機児童対策担当課長","answer":"それと、給食につきましても、当然、東京都の認証の実施要綱で定めれられている内容がありますので、そちらに従いまして十分な献立を作成して、当然その中での手づくりで提供していきます。","voiceIndex":64,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"認証は都の制度なので都の基準に沿って認証が与えられるわけですけれども、品川区として認証保育園を受け入れていくに当たって、品川区での基準というか、何かここは大事にしてほしいというようなものがあって、あちらにお伝えをしている部分があるのかどうか、その品川基準と言えるかどうかわからないんですが、こだわりとかありましたらそこを教えていただきたいのと。","respondent":"吉岡保育課長、伊崎待機児童対策担当課長","answer":"品川基準ですけれども、明文化した基準という形では持ってございませんが、従来、認証保育所の開設に当たっては、経営の主体であります事業者の経営の確実さですとか、それからあと。そこで今年度から品川区では家賃補助ということで、坪１万２,０００円を超えて１万円までは、今後３年間補助をしていくという制度を設けまして、家賃が高くて認証保育所の開設がなかなか進んでこなかった地域でも、今。","voiceIndex":66,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区独自で何かお話を聞いたりとか、事前にというのがありましたよね。その辺をもう１回教えていただきたいのと、あと、地域性の問題なんですけれども、家賃補助ができて、五反田と大崎は効果があったんでしたっけ。その辺において、五反田・大崎の今後のことと、あと、これからの計画で、この間、あそこの二葉が１個、あそこは認証でしたよね、違ったっけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"認証の今後の計画がどうなっているのか教えてください。","respondent":"吉岡保育課長、伊崎待機児童対策担当課長","answer":"認証保育所に対する指導ですけれども、先ほど来も話に出ておりました認証保育所は、都が認証基準を定めて認証している保育所ですので、基本的には指導監督は都が実施しています。認証保育所の設置計画ですが、今年度予算では２カ所、年度内に開設を予定しております。は必要に応じて鋭意検討を進めているところです。","voiceIndex":70,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後になりますけれども、あと２カ所ということで、五反田・大崎地域がどうなっているのか、もう１回答えていただきたいのと、あと、認証の施設長の集まりも設けたということですけれども、これに当たっては、すべての認証の施設長が参加されていらっしゃるのかどうか、その辺を教えてください。","respondent":"伊崎待機児童対策担当課長、吉岡保育課長","answer":"五反田・大崎地域も含めまして、待機児童解消対策に一番有効なところをいま検討しています。その施設長の会議への出席の状況ですけれども、つい最近実施した第１回目では、１５施設のうち、たしか１３施設だったと記憶していますけれども。","voiceIndex":73,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ認証の保育園のところも施設長のご意見などもしっかり受けとめて、でき得る限りの改善をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4736#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":21395,"voices":81}},{"id":"h23-20110822-5","meetingId":"h23-cm08","date":"2011年8月22日","dateIso":"2011-08-22","committee":"総務委員会","time":"午後０時５９分～午後２時２５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の債権の放棄","agenda":"の債権の放棄","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"一応お伺いしておきたいんですが、この４号事由には、債務者が生活保護法の適用を受けると自動的に、あるいは普通は債権放棄になるということではなくて、今回の放棄の事由が困窮ということでという理解でよろしいでしょうか。","respondent":"福田会計管理者","answer":"１つは、債務者が著しい生活困窮状態にあるということ、もう１つは、後段になりますけれども、資力の回復が困難であると認められること。したがいまして、この要件に該当するかどうかにつきましては、債権１件ごとにこれからも判断をしていく必要があろうかと考えています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"確認","question":"学童保育料なんですけれども、大分前のことなので記憶が定かじゃないんですけれども、ちょっと確認したいんですけれども、学童保育料は生活保護を受けているときも支払い義務というのは世帯主のほうにあるんだったのでしょうか。その辺を確認したくて。","respondent":"福田会計管理者","answer":"ただ、先ほどもお答えしましたように、債権の放棄は１件ずつやっていくものですので、生活保護に該当するからといって直ちに機械的に債権が消滅するという関係ではございません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"確認","question":"その辺は承知しているつもりで質問したんですけれども、そもそものところの保育料が、生活保護受給者が保育料を支払わなくてはいけないという状況というのはどうだったのかなというのを確認したかったんですけれども、学童保育がなくなってすまいるになってもう何年にもなるので、ちょっと前なのであれなんですけれども、その辺だけ確認したかったので、もしわかれば。","respondent":"福田会計管理者","answer":"これは当時の条例ですが、使用料ですけれども、第４条第２項というのがございまして、区長が必要があると認めたときは使用料を減額し、または免除することができる、こういう規定があります。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"確認","question":"学童保育料の確認なんですけれども、保育料が滞っていった大きな理由というのは、放棄する以前の段階として、その辺を確認したいんですけれども。それから生活保護の弁償金ですけれども、この５件については、現在も生活保護を受けていらっしゃる方と判断してよろしいですか。","respondent":"福田会計管理者","answer":"そのほかの形につきましては、再三督促をしたりしているのでありますけれども、現在のところ、行方がよくわからないという方が大半です。それからもう１つ、生活保護のほうでありますが、今回ご報告させていただいている債権は、すべて生活保護受給中の方の債権です。","voiceIndex":11,"id":"exchange-004"}]},{"id":"topic-02","title":"の平成２３年度都区財政調整交付金当初算定の結果","agenda":"の平成２３年度都区財政調整交付金当初算定の結果","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"最後のところをもう１回確認したいんですけれども、品川区は算定結果は１３位で、昨年度は９位だったけれども、減ったと。減ったというか、普通交付金の額が減ったということですよね。その額が１１億円だということなんですけれども、そのあたりのことをちょっと確認したいのと、正確に聞かなかったので、申しわけありませんが、教えてください。","respondent":"榎本企画財政課長、伊藤委員長、久保田行財政改革担当課長","answer":"ただし先ほど申しましたように、特別区税につきましては、当初予算よりプラスで入って、プラス８億円ぐらいの見込みをしておりますので。ほかにないようですので、本件を終了いたします。評価の説明にもありますように、高齢者の生きがいづくりは区が行う同種の事業全体と調整・連携して進めること、これが１点です。","voiceIndex":17,"id":"exchange-005"}]},{"id":"topic-03","title":"の区民参加による行政評価の実施結果","agenda":"の区民参加による行政評価の実施結果","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"８つの事業の評価を行ったわけですけれども、結果として、総合評価としては、Ｂの継続もしくはＣの見直しということの２つになっているわけですが、この辺の評価を受けて、区としてのギャップというか、もともと区として持っていた評価とのギャップというか、ある種、想定していたとおりだったのか、その辺の評価をお聞きしたいんですけれども。","respondent":"久保田行財政改革担当課長","answer":"こちらについても、評価の説明にありますように、児童センターの担う役割というものは毎回見直す必要があるということと、コストについても十分に検証する必要があるのではないかといった意見が付されておりますので。","voiceIndex":23,"id":"exchange-006"},{"speaker":"塚本委員","kind":"質問","question":"やり方とかを変えるということで、事業そのものの目的とか、あるいは事業そのものの存在とかというのを見直すというところにはいっていないのかなという感じがしたんですけれども、そういう意味で言うと、今回の行政評価委員会そのものの評価というのは、今後ともまだやっていこうととらえているということでよろしいでしょうか。","respondent":"久保田行財政改革担当課長","answer":"ただ最終的には、委員会の合議という形で意見を取りまとめるといった方向で、評価結果としてはＢとＣを中心としたものとなっていますけれども、それを補完する中身として、評価の説明といったところを委員会の中で加えさせていただきまして、また。","voiceIndex":25,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"日曜日だし、雨も降っていたからもっといてもよかったのかなと思ったんですけれども、中高生の活用と、あるいは就学前の子どもさんの利用が児童センターの対象となってきている状況の中で、果たしてそれでいいのかなというのを、昨日行ってみた中で実感したので、改めてこのあたりのことを、児童センターの役割というところも含めて、品川区の今、置いているコンセプトを再確認したいなと思って質問しました。","respondent":"久保田行財政改革担当課長","answer":"予算編成の作業自体については、例年どおりの形で進めていくですけれども、今回の行政評価委員会には各所管の課長、また係長、職員の方も参加して、説明を受けて意見をいただいているところですので、そうした中で評価委員の方の生の声も聞いているわけですから。","voiceIndex":27,"id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"所管がちょっと違うということなんですけれども、評価結果の報告があったので、その範囲においてということでの質問をさせていただいているつもりなんですけれども、いろいろと社会状況の変化というのはあるかもしれないけれども、児童の健全育成という点での施設の役割というのは、これはどんな時代になっても変わらない、変わってはいけないものがあると思いますので、そういう意味で、もう少し別な場面で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"今回、区民参加による行政評価の実施ということなんですが、公募された一般区民の方、お一人お一人が区民の方ですよね。そういうところに対して、結局こうやって４つの評価で出されると、みんなこの形でオーケーというか、ほとんど委員の意見はこの形で固まったのかなというような見方もされてしまうと思うんですが、その辺について、内容について教えてください。","respondent":"久保田行財政改革担当課長","answer":"それから意見が割れたものについてですけれども、私どもも実施するにあたりまして、そこのところはいろいろと委員長とも運営を検討した中で苦慮したところでございまして、単純に総合評価でＡ、Ｂ、Ｃ、Ｄだけでまずやりますと。","voiceIndex":30,"id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"今回初めてですけれども、きちんといろいろやられているということがよくわかりました。ただこの中でＡ、Ｂ、Ｃ、Ｄの４段階ということなんですが、４段階というとかなり大ざっぱになると思うので、できたらＡの上のほうなのか、下のほうなのか、真ん中なのかということもあると思うんですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-011"},{"speaker":"阿部委員","kind":"質問・要望","question":"カリキュラム評価といいますか、やり方自体を評価して、今後の区民参加による行政評価の手法をより洗練させたものにぜひしていただきたいと思うんですが、お考えをお聞かせください。１つ気になったのが、６番の水辺の利活用の推進というかなり大きなテーマで、内容は水質浄化について見直しとあるんですけれども、これは水辺の利活用の推進そのものが見直しという評価を得たんでしょうか。","respondent":"久保田行財政改革担当課長","answer":"行政評価を実施した検証ですけれども、実は２日目の委員会が終わりましたのは、１２時半の終了予定が１時半まで延びました。","voiceIndex":33,"id":"exchange-012"},{"speaker":"阿部委員","kind":"質問・要望","question":"ぜひ次回に向けてよりよい形で改善していただきたいと思います。そういうのも確かにあるかもしれないんですけれども、似ている面を探すとついつい安心してしまうんですね。じゃなくて、やはりたとえ同じ評価であったとしても、区民の方から出された今まで区になかった部分というのを、探してでも受けとめる姿勢がぜひほしいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今回の評価委員会自体はなかなかよかったというお話を伺っているんですが、その上で資料をつくるのが担当としても大変な部分もあったと思うんですが、資料づくりという意味での、事前に区民委員の方には１回説明なさっているんですよね。その段階で確認をとっていないからわからないところが、行政側が区民委員の方に説明したときにどの辺まで説明しているのか。","respondent":"久保田行財政改革担当課長","answer":"今後の行政評価の考え方ですけれども、こちらについては今回は１回目ということで実施させていただいたところですので、基本的には継続して行っていきたいなとは考えているところですけれども、それをどういうサイクルで、どういうタイミングでやるかというのは。","voiceIndex":36,"id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その見直し等を考えたときに、ここだけに頼るのではなく、議員としての立場も考えていかなければいけないなというのも非常に意識して、この件を検討させていただきたいと思います。毎年がいいのかどうか、そこら辺も改めてご検討していただきたいなと思うので、よろしくお願いします。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"さっき言いそびれてしまったので、済みません。今、実施してみてどうだったかという、区の２回の評価委員会をなさった上で、これだけの結論が出たということについて、区はどうふうに考えているのかというのを改めて聞いてみたいと思います。ですから、そういう点でぜひ検討もしていただきたいと思っているんですけれども、改めてその件についての見解を伺っておきたいと思います。２点です。","respondent":"久保田行財政改革担当課長","answer":"事業の取り上げ方についてですが、これも前回ご説明しましたように、区民に身近で関心の高いものというものを、各分野から今回、８事業ということで選ばせていただいたものです。","voiceIndex":39,"id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"最後のところなんですけれども、区民アンケートとかそういうものを区がおとりになっている結果も見てみると、必ずしも今のご答弁のようなものではないと私は実感しているので、いろいろな多面的な意見を聞くということが今回の事業のコンセプトであれば、いろいろな部分での区民アンケートをとって出てきているような意見も斟酌していただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-017"}]},{"id":"topic-04","title":"の南大井五、六丁目付近下水道管改修工事請負契約","agenda":"の南大井五、六丁目付近下水道管改修工事請負契約","exchanges":[{"speaker":"阿部委員","kind":"質問・要望","question":"東京都の下水道工事を南大井五、六丁目付近で２件ということなんですけれども、これは都で進めている老朽化した下水道管取り替え工事全体の中での、たまたま今回２件ということだと思うんですけれども、ある程度全体像といいますか、どのくらいで大体完了するのかなど、そういうのがもしあれば教えていただきたいと思います。","respondent":"阿部経理課長","answer":"区のほうで受託をして工事を出すというのは今回、初めてです。今後の予定ですけれども、来年度以降も区が受託してやる予定とは聞いておりますけれども、どこをやるか、あるいはどの時期にやるか、それは今後の東京都との調整だと聞いております。","voiceIndex":48,"id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"工事そのものが、この地図で言うと、鹿島神社からおりてくる水神社のあたりだとか、桜新道はそんなにないんですけれども、小さな道路なので、そんなに大きな交通渋滞を招くような影響はないんだろうと思うんですけれども、工事そのものがどういう状況で行われるのかなというのがちょっと気になるところなので、その辺がわかれば教えていただきたいのと、それから、初めての受託なんだというんですけれども。","respondent":"阿部経理課長","answer":"下の管きょ工事、これはマンホールからやりますので、そういう意味では大きな交通の支障が出るというものではございません。２点目の工事なんですけれども、全体計画はどうなっているのかというのは、申しわけございませんが、把握してございません。","voiceIndex":50,"id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"全体計画を把握していないということなんですけれども、その辺はする必要がなくてしていないのか。要するにこの白であいているところですね。そういうところが現在どういう状況なのか、順次やっていくのかどうかというのは知っておきたいなと思っているんですけれども、その辺の状況というのは、東京都の下水道のほうに個別に問い合わせするしかないんでしょうか。","respondent":"阿部経理課長","answer":"先ほども申し上げましたけれども、来年度以降もやる予定とは聞いておりますけれども、具体的にどこをやるのか、どの時期にやるのか、それは所管と東京都下水道局との今後の調整だと考えております。","voiceIndex":52,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"これはぜひ東京都のほうに、下水道局のほうに危険な箇所とかあるようならば、情報を区のほうに出してくださいというような、おそらく品川区も要請はしていると思いますが、さらに一歩踏み込んでやっていただかないと大変な事態に、地震等がこれから起きると困ると思いますので、その辺、強く要望して、区民の日常生活に支障のないように、区のほうでも努力していただきたいと思います。要望だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-021"},{"speaker":"阿部委員","kind":"質問","question":"この下水道管の改修は耐震機能もつけるのか、もしおわかりだったら教えてください。","respondent":"阿部経理課長","answer":"耐震機能をつけるかどうかは、申しわけございません、そこまでは把握しておりません。","voiceIndex":55,"id":"exchange-022"}]},{"id":"topic-05","title":"の南品川五、六丁目付近下水道管改修工事請負契約","agenda":"の南品川五、六丁目付近下水道管改修工事請負契約","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"当たり前のことなのかもしれないんですけれども、ちょっと私、知らないことなので、教えていただきたいと思います。両方の工事とも南大井、南品川とも同じ会社、所在は品川となっていますけれども、東京支店ということで、入札に参加したのが同じ会社になっていますけれども、これは東京都の受託事業ということで、ある程度指定業者が決められるんでしょうか。","respondent":"阿部経理課長","answer":"その前に区内業者として８社あります。８社の中で全く実績のないのが２社、ですから残りは６社になるわけですね。その６社は今回の申し込みはできるんですけれども、実質的にやったのは両方とも４社です。","voiceIndex":61,"id":"exchange-023"},{"speaker":"原委員","kind":"質問","question":"たまたま入札についての話が出たので、詳しい事情を教えてください。当然それは区のほうでも入札に関しての業者の調べというのはどういう形でやっていらっしゃるんですか。それが１点です。","respondent":"阿部経理課長","answer":"先ほど申しましたけれども、制限付き一般競争入札というのは、公告というのを行います。こういう工事をこの金額でやりますということで皆さんにお知らせをする。皆さんというか、公告をするということになります。","voiceIndex":63,"id":"exchange-024"},{"speaker":"原委員","kind":"意見","question":"ちょっと聞き方がおかしかったんですけれども、実際にここ数年来で目黒区は若干数社、世田谷区においてなんかはかなりの件数のところが、受注だけ取って、実際には、こういう表現をしていいのかわからないけれども、法人体としてはつぶれてしまう、そういうことがあるので、そういったケースになってきてしまうと、下請け、孫請けまで全部に被害がかかると思うので。","respondent":"阿部経理課長","answer":"ご心配しているような事態は、今回についても、当然のことながら今までもそういう経験はございませんけれども、ならないと思ってあります。そういう意味で、各事業者の経営状況は絶えず把握しております。","voiceIndex":65,"id":"exchange-025"},{"speaker":"原委員","kind":"質問・要望","question":"基本的なところは当然調べられていると思うので話をしておりますけれども、あとは契約案件、総務委員会なので、これはお願いだけしておきたいんですけれども、道路上の先ほどの開削ですね。そういった意味合いで、工事としては結構大変な工事だと思うんですが、その辺の安全性を特に注意していただきたい、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-026"},{"speaker":"金野副委員長","kind":"質問","question":"基本的な仕組みだけをお聞きしたいんですが、都の受託事業だということですが、そうなると、あらかじめここの工事をしますという形で大体の都としての委託費用があって、工事の区としての予定価格があって、そこら辺の整合性というんでしょうか、受託費、それはどういう仕組みでこういうふうになるんでしょうか。","respondent":"榎本企画財政課長","answer":"ただし、例えば東京都の場合、都の受注でもって何らかの事業の進捗が変わった場合については、区のほうには受託がある程度絞られたり、逆にもう少し多くやってもらいたいということであればやる場合もありますけれども、それも年度当初予算の中で調整した上で。","voiceIndex":68,"id":"exchange-027"},{"speaker":"金野副委員長","kind":"質問","question":"そうすると、先ほどご説明の中に今回が初めてということで、なぜ初めてこれをしようとされたのか、そこら辺をお聞きしたいと思います。","respondent":"日下部企画部長","answer":"それに対しまして、区のほうといたしましては、品川区管内のこういう下水道管については、いろいろな治水対策の関係とか、いろいろそういうところもありますけれども、老朽化したものについては区が受託をすることによって早く事業を進めることができますので。","voiceIndex":70,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1890#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":27857,"voices":77}},{"id":"h23-20110823-14","meetingId":"h23-cm08","date":"2011年8月23日","dateIso":"2011-08-23","committee":"行財政改革特別委員会","time":"午後０時５９分～午後３時２５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、特定事件調査","agenda":"の１、特定事件調査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今日の関連団体についてどうあるべきなのか、まず現状の状況等、品川区の考え方について、今日、じっくり伺いたいと思うんですけれども、幾つかあるので、品川区国際友好協会に絞って伺います。裏を返せば、なぜ品川区が直接ではないのか。設立の経過も含めて、ご説明いただきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"区は区として、自治体としての責任において国際化に向けた事業を展開しておりまして、品川区国際友好協会については、やはり地域に根ざした形の草の根の国際事業等を展開して、区民の間に国際化なり、そういった姉妹都市等の親善のところが広く啓発、また普及していくような形で。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"今、役割分担のお話がありましたけれども、なぜ外郭団体でなければできないのか、直接ではない理由は何なのか、そこを伺いたいと思います。あわせて、品川区国際友好協会の体制について伺いたいんですけれども、資料には職員８名とありますけれども、この中に品川区の職員ＯＢ、退職者は何人いるのか。体制では理事は１２名、監事が２名と伺っていますけれども、その中で品川区の職員ＯＢは何人なのか。","respondent":"久保田行財政改革担当課長","answer":"品川区国際友好協会の体制ですけれども、区の職員のＯＢにつきましては現在３名です。役職の関係ですけれども、理事に副区長、教育長がいるといったような構成です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜこの形でなければできないのかということを伺いたいんです。わざわざつくって進めているわけですから、そこをご説明いただきたいと思います。実際の体制を見ましてもＯＢの方が３名、あと現職という言い方なんでしょうか、副区長と教育長がそれぞれ入っているわけですけれども、民間の自発的な活動と言いながら、体制の中心は区のＯＢだったり、現職の幹部職員だったりするわけですね。","respondent":"久保田行財政改革担当課長","answer":"１点目のご質問ですけれども、協会をわざわざつくったということではございませんで、先ほどもご説明いたしましたように、民間でやっておりました協会といったものを、財団法人のほうに移行したといったところです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"それで民間でやるというその説明が、どうも筋が通らずわからない。そこを説明していただきたいのと、あと品川区国際友好協会で言えば理事が１０名、評議員が２０名いるけれども、区と関係の強い外郭団体、第三セクター、その中でかけ持ちしている人たちが何人いらっしゃるのか伺いたいんです。こういう要するにかけ持ちがどれぐらいあるのか、こういう状況をどうお考えなのか、それを伺いたいと思います。","respondent":"日下部企画部長","answer":"関連団体の役員なんですが、私もちょっとその辺はよく承知していないところがありますが、今、ご指摘のあった方につきましては、例えば品川文化振興事業団ということであれば、やはり区の文化行政というだけではなくて。","voiceIndex":11,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区国際友好協会に絞っていろいろ伺いましたけれども、ほかの社会福祉法人を見ても、今年３月３１日に退職した課長、部長が４月１日からそれぞれの社会福祉法人の理事長だったり、役員にほぼ毎年のように入っているわけですね。裏を返せば区ではないのか。これはちょっと率直によくわからない部分があるので、公益財団法人との関係ではどう変わるのか、そこも説明していただけますか。","respondent":"日下部企画部長","answer":"特に社会福祉法人の場合は、第三セクターといってもちょっと性格が違いますけれども、例えば社会福祉法の規定の中でよく出てまいりますように、公共性、それから非営利性、それから事業の継続性という大体３点セットで言われますけれども、いずれにしましても、法律・制度の中で。","voiceIndex":13,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"やはりこのご説明を聞いていても、なぜ別団体、具体的に言えば品川区国際友好協会から品川区シルバー人材センターから社会福祉法人、いろいろ種類はありますけれども、別団体をつくらなければ事業ができないのか、それが今の説明でも私にはよくわかりませんでした。同じ答えになるのかもしれませんけれども、その点について最後もう一度、どんなふうにお考えなのか伺いたいと思います。","respondent":"日下部企画部長","answer":"区としても、ですからそういう公共性をしっかり担保しながら、民間の柔軟な組織運営、事業運営のよさというものをうまくミックスしながら、区民の皆さん方の期待にこたえて、サービスの向上を図っていくという基本的な姿勢で進めておりますので。","voiceIndex":15,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"この表を見せていただいてよくわからないところがあって、区分というところもまず教えていただきたいんですが、品川区国際友好協会のところに「基本財産等」というのがあって、次に「区出捐金等」というのがあって、さらに「助成金」というところもあるんですけれども、この関係性がちょっとわからないんです。そこから教えていただきたいと。","respondent":"榎本企画財政課長","answer":"それぞれ区としてお願いをしてやってもらうもろもろの事業の内容が入っているということであります。それから業務委託の経費につきましては、区がこの委託事業等に対して支出を予定している金額ととらえていただいて結構です。","voiceIndex":17,"id":"exchange-007"},{"speaker":"西本委員","kind":"意見","question":"そうすると、経費、それから助成金なんですが、これはトータルで出ていないところもあるので、ちょっと計算が正しいかどうかわからないんですが、経費があまりかからないのに、かなり大きな助成をされているというところがあるんですね。それと、例えば三徳会なんかは助成金０円なんですね。ランニングコスト等々というのは何かの考えがあって出されていると思うんですが、その考え方は。","respondent":"久保田行財政改革担当課長","answer":"一方で福栄会等につきましては、運営費助成といったものの内訳としましては、例えばかもめ第３工房の運営費助成とか、第一しいのき学園の送迎の助成といったようなものの経費ということで、改修工事等の助成がなかったというところで。","voiceIndex":19,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"多分いろいろな経費、それだけではなくてたくさんいろいろされているので、その他の金額はこれだけではわからないだろうと思うんです。そういったときに、そこの今までの関係の深いところの、そういう人たちとの新しい事業とか考え方も含めて、その整合性というのはどうしているのかなということがちょっと不明瞭だなとも思っているんですけれども、その辺はいかがでしょうか。","respondent":"久保田行財政改革担当課長","answer":"そういった意味では、やはりその専門性というものを十分に引き出していくといったところ、また中ではやはり行政としてのかかわり方というものもありますので、今の運営形態というものをとっているところもございまして。","voiceIndex":21,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"連続性というのは非常にわからないではない話だと思うんです。この社会福祉法人にいろいろお願いしている。そうすると、やはり新しい人を入れていくとか、何か考え方として、今の行政に合わせた形で柔軟に発展できるような仕組みというのをつくりづらくなってはいないかということが、非常に心配だということなんですが、その点をお聞きしたいと思います。","respondent":"日下部企画部長","answer":"第三セクターというある意味で別立ての組織をつくって、区民ニーズにいろいろな形で幅広くこたえていこうというのが本来の趣旨ですから、そういった意味では、今、ご指摘がありました、そういう運営に携わる人材をどう配置するかとか。","voiceIndex":23,"id":"exchange-010"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"品川区国際友好協会の区ＯＢの人数は先ほど出たんですが、その他の団体の区ＯＢの人数を教えていただきたいのと、運用基金助成というのがあるんですが、これはどのような目的で、またどのような基準で算出されているのか、教えてください。","respondent":"久保田行財政改革担当課長、榎本企画財政課長","answer":"ＯＢの数ですけれども、品川区国際友好協会３人です。品川区シルバー人材センターは１名。品川区社会福祉協議会は３名、品川総合福祉センターが１名、三徳会が１名で、福栄会が３名、さくら会、春光福祉会がそれぞれ１名です。これは社会福祉法人を設立するときに、基本財産的なものとして持たなくてはいけないということで、そういうものがないと社会福祉法人としての設立ができないというもので、それを区が助成をしているというものです。","voiceIndex":25,"id":"exchange-011"},{"speaker":"石田（慎）委員","kind":"意見","question":"その他も例えば日本語教室なども、業務委託などもしながら十分区で対応ができると思うんですが、なぜこの品川区国際友好協会、これだけ区が出資をして、ほとんどが区の出資でやられているものだと思うんですが、今ひとつ先ほどのお答えでも僕はぴんとこないなと思うんですが、この自主事業を見ても、どうしてもここでやらなくてはいけないというのが理解できないんですが。","respondent":"榎本企画財政課長","answer":"そのいろいろな事業の中で、ここのところはやはり海外とのやりとりというよりかは、地域に国際化をどう根ざすかというところを主だった形で区としても進めていますので、このような自主事業の展開もあわせて協力をしてもらっているというようなことです。","voiceIndex":28,"id":"exchange-012"},{"speaker":"石田（慎）委員","kind":"質問","question":"それと草の根の地域に根づいた活動というふうに言われていますが、品川区内にも幾つかそういった国際的な団体というのが存在をしていて、そことのそれこそ協働という観点で事業を進めれば、十分この自主事業は行っていけるのではないかと思うんですが、その辺の点を改めて伺いたい。","respondent":"久保田行財政改革担当課長","answer":"先ほど来ご説明しておりますけれども、市民、区民の草の根交流といったものを展開するというところであれば、大使館等との交流を主に置いているものではございませんので、場所としては五反田地域になければならないというふうには私どもとしては考えておりません。","voiceIndex":30,"id":"exchange-013"},{"speaker":"石田（慎）委員","kind":"質問","question":"先ほど区のＯＢの人数が３名というのを聞いたんですが、この８名の職員の方たちは、基本的にどのような専門性を持った方がやられているのかなという疑問なんですが、どのような方が職員としてこの国際友好という事業を行っているのか、これも教えていただければと思います。","respondent":"榎本企画財政課長","answer":"３人はＯＢということで、残り５人につきましては、事務職兼英語の通訳ができる人ということで、英語の専門性を持ったということと、従来からのいろいろな姉妹都市の友好関係を取り持ってきているメンバーです。","voiceIndex":32,"id":"exchange-014"},{"speaker":"渡辺委員","kind":"質問・要望","question":"今後、やはり今の企画部長の話にあったように、民間へのサービス提供を活用していくという点でも、これだけ違うよという算定での根拠的なものはどこかで出したほうがいいのかなと思っているんですが、現在どのようになっているのか、あるいは今後そういう考え方があるのかを伺いたいのと、あと項目で言うと、今、品川区国際友好協会が大分議論になっている中で。","respondent":"久保田行財政改革担当課長","answer":"そういった中で、やはり私どものほうとしましても、そういったものについては注視をして、今後もそういったことを確認しながら、効率的な区政運営を進めていかなければならないと考えておるところです。","voiceIndex":38,"id":"exchange-015"},{"speaker":"渡辺委員","kind":"質問","question":"これからもっと、こういう直営ではないという形というのも必要性は出てくるという中では、何かで広く表現をする必要があるのかなと。そのコスト差だとか。例えば業務委託を例にとると、あるいは指定管理でもいいんですが、委託をする責任というのはどこまで把握をして、どこまで直通の緊張感を持たせられるかというのが課題かと思うんですが、その点どのようにお考えでしょうか。","respondent":"久保田行財政改革担当課長","answer":"指定管理についても同様の考えでございまして、こちらにつきましてはモニタリング・評価といったシステムの中で毎年毎年きちんと評価をしていきますし、例えば３年目の節目のとき、また事業期間が満了する間際に総括的な評価もしていって。","voiceIndex":40,"id":"exchange-016"},{"speaker":"渡辺委員","kind":"質問","question":"最後にこの助成金のやりとりの中で、今、品川区国際友好協会をちょっと例にとります。右の自主事業のところというのは、ここは先ほど意見でも出ていましたが、品川区がやるべきことというか、趣旨に沿うような形、ある程度王道というか、表現はあれですが固い事業というんですか。","respondent":"久保田行財政改革担当課長","answer":"大胆かどうかというとちょっと評価が分かれると思いますけれども、例えば国際化ということで長期基本計画でうたっていますが、地域の国際化が必要だろうというところで、区民祭りとかそういった地域との交流といったものを積極的に進めていきたいということで。","voiceIndex":42,"id":"exchange-017"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"だからそこら辺の部分をもっとアピールするべきだと思っていて、私は品川区の場合は非常に在宅介護支援センターから含めて、まさに護送船団方式で来ているんだろうと思っているんだけれども、それはそれで私はいいと思っているんだけれども、それで行くなら行くで、ちゃんとしっかりそういうメリットがあるんだということをもっと言えばいいと思っていて。","respondent":"久保田行財政改革担当課長","answer":"それ以上に、そういった意味では品川区内の状況、また区民の方が置かれている現状というものをやはり区内の法人というのはよく把握しているということもありますので、こういった形でそれぞれ業務の種類によってお願いをしているところでございまして。","voiceIndex":44,"id":"exchange-018"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"区が把握をするべきじゃないのかなとちょっと思っているんだけれどもいかがでしょうか。それから、品川区社会福祉協議会のほうはあまり突っ込まないですから、ただ、品川区社会福祉協議会が本当によくやっているということは、もっとぜひ、２３区でも一番ぐらいやっているというのは、もっと私は売り出したほうがいいと思っていて、ぜひ売り出してほしいなと思います。大起なんかも入った。","respondent":"日下部企画部長","answer":"ただ、品川区の場合は、先ほどもちょっと触れられましたけれども、１つの特色としては、区内のもともとは例えば家政婦さんの派遣業、ヘルパーの派遣をしていたような小さなそういう事業所がケア協議会というのを組織して。","voiceIndex":46,"id":"exchange-019"},{"speaker":"石田（秀）副委員長","kind":"提案","question":"最後に１点だけ。例えばこの前、杜松小学校の跡地の話が出たんだけれども、特別養護老人ホームもあれぐらいの小規模とか、いろいろ併設をしていくんだけれども、あれをよくよく考えるとこの５団体しか受けられない。いろいろな事情はあるんだろうけれども、やはりそういうことを逆算して考えていくというほうが、私はいろいろな民間の提案も出てくると思うので、そこら辺もぜひ考えていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5908#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":27805,"voices":53}},{"id":"h23-20110824-17","meetingId":"h23-cm08","date":"2011年8月24日","dateIso":"2011-08-24","committee":"震災対策特別委員会","time":"午後０時５９分～午後３時３３分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6394#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":1678,"voices":6}},{"id":"h23-20110922-4","meetingId":"h23-c-settlement","date":"2011年9月22日","dateIso":"2011-09-22","committee":"決算特別委員会","time":"午後３時４４分～午後３時５０分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1338#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":2010,"voices":17}},{"id":"h23-20110926-6","meetingId":"h23-cm09","date":"2011年9月26日","dateIso":"2011-09-26","committee":"区民委員会","time":"午前９時５９分～午後０時０５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"もう１点は、課長がこの課に来る前からも毎回いろいろ出ているんですけれど、いわゆる維持費といいますかランニングコストの問題で、設置の助成はするけれども、その後の電気代等、修理等は保証とかがあると思うんですけれども、ランニングコストのことはいつも答弁では「考えます」という形なんですけれども、今、新しく課長になられて。","respondent":"川崎生活安全担当課長、米田商業・観光課長、福島ものづくり・経営支援課長","answer":"今後、東京都の動きを見ながら、それに倣って今後の課題として検討するというふうに考えております。前回やってからもう１０年ほど経過して、そろそろやりたいというご意向はあったんですけれども、今回当初予算の実態調査においては、経費的にも。今回こういう結果で２０件という応募がありましたし、開発案件等のやり方あるいは経費の使い方等わかってまいりましたので。","voiceIndex":7,"id":"exchange-001"},{"speaker":"藤原委員","kind":"質問・要望","question":"それとその電気代等のランニングコストなんですけれど、課長は警視庁から来ていらっしゃるから、東京都があれしていないからというのはわかるんですけれども、うちは品川区ですから、区の独自の施策として電気代等を助成しますよとなれば、また各新聞の東京版とかにバンと出るような先駆的なあれになると思うので、東京都がやっていないからということではなくして、やはり地域の安全を守るという意味では。","respondent":"川崎生活安全担当課長、米田商業・観光課長、中川原地域振興事業部長","answer":"ランニングコストの件ですが、今後区のほうでつけられるものであれば、前向きに検討して、つけられるようにしたいと考えます。委員会報告に関してですが、先に行います商店街振興のための実態調査と合わせて、調査の全容がまとまりました段階で必要に応じて。それから商店街の調査も、先ほどから課長が説明していますが、年度当初についている予算というのは。","voiceIndex":11,"id":"exchange-002"},{"speaker":"本多委員","kind":"質問・要望","question":"防犯カメラのことを私も質問します。防犯カメラの設置をすることはいいことというか、特に問題ないと思うんですけれども、設置をするに当たって、年間計画といいますか、年度計画といいますか、今まで要望がなかったから必要に応じて補正でやるんだよということで、それはわかるんですけれど、日常の年度計画において、投げかけみたいなことはしないのか、常に受け身なのか。","respondent":"川崎生活安全担当課長","answer":"年度計画についてのご質問ですが、町会の主体性を生かしてこれまでやってきております。したがいまして、今後とも町会からの要望があった際に設置をしていきたいと考えております。","voiceIndex":15,"id":"exchange-003"},{"speaker":"本多委員","kind":"質問","question":"最初のほうの質問ですけれど、いつでも年間、必要に応じて受け入れ体制はありますよということで、それはそれで懐が広いんだなと思いますけれど、ただ年度の予算の見積もりはそれでいいのかなと。ほかはあまりないと思うのですけれど。懐が広いんだなという思いを、ちょっと感想を述べて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ソフトウェアのほうですけれども、２０社の応募があって、大体どういう内容で、決定した２社と次点の３社はどういう内容だったのか、せっかくですから教えていただければと思います。","respondent":"川崎生活安全担当課長、米田商業・観光課長、福島ものづくり・経営支援課長","answer":"１点目のご質問でありますが、前年度の要望を受けて、東京都の助成制度と関連して予算要求していくという方法をとっております。そのために、先ほども申し上げましたように店の紹介等もなかなかできない、店も本当に１年、２年たつと変わっていきますので。もう１つは医療関係ですけれども、医薬品のデータベースと病院で使っている専門システムを結びつける連携プログラムを開発するということで。","voiceIndex":18,"id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問","question":"特に商店街がどうなっているかというのは、まちづくりの一番の基本のところだと思うんですよね。今でも商店というのは生活していく上で生活物資を供給する場所ですから、そこがどういうふうになっているかというのはやはり、まちづくりを今後どういうふうに考えていくか、一番のポイントだと思うんです。","respondent":"米田商業・観光課長","answer":"その上で今回、緊急雇用対策事業ということで区のほうで実施することになりましたので、一つの契機として今後についても、このメンテナンスのあり方等について、また商店街連合会と話し合いを継続しながら進めてまいりたいと考えているところです。","voiceIndex":22,"id":"exchange-006"},{"speaker":"山元委員","kind":"質問・要望","question":"防犯カメラの設置なんですけれども、平成１７年度からずっと見ると、商店街が中心というか多いのかなということがあるんですが、実際は住宅といいますか、そういうところの申し込みというか状況はどうなのか教えていただきたいということと、今は本当にマンションが多くなっているんですが、そのマンションの例えば自治会等の申し込みがあった場合、このような条件で助成していただけるのかどうか。","respondent":"川崎生活安全担当課長、米田商業・観光課長","answer":"１点目の住宅地からの要請についてですが、既に設置されているところもあります。例を挙げると池田山町会とか相生会地区などは、住宅地からの要求によってつけているものであります。ＧＩＳ、地理情報システムにつきましては、細かくいいますと北緯何度、東経何度にあるという細かい点を導きまして、より視覚的に店舗の位置情報等がつかめるということで、利点があると考えています。","voiceIndex":24,"id":"exchange-007"},{"speaker":"山元委員","kind":"質問","question":"ＧＩＳのほうですが、お話を聞いていると、どちらかというと商店街側から立ったいろいろな情報を植えつけていくというか、やるイメージがあるんですが、逆に利用する側、どこそこの商店に行きたいとか、お店に行きたいといった場合、ちょっと現実的な話ですが、自転車で行こうとか思った場合、お店ももちろんなんですが、例えばその地図の上でここに自転車置き場があるとか。","respondent":"米田商業・観光課長","answer":"ただ、おそらく想定できる難点としては、自転車等で行く場合、それが高いところにあるのか、低いところにあるのか、坂道を上っていくようなところかまではなかなかつかみにくいだろうとは考えておりますが、なるべくいろいろ利便性の高い情報については。","voiceIndex":27,"id":"exchange-008"},{"speaker":"沢田委員","kind":"質問・要望","question":"ソフトウェア開発費助成のことでお伺いしたいんですけれども、まずこの上限１００万円ということで、先ほど細かい内容をお伺いしたんですけれども、上限の１００万円満額ということみたいですけれども、大体この事業に会社がどれぐらい使われているのかというのが知りたいのと、こういう事業は大体どれぐらいかかるのかよくわからないので、その辺をちょっと教えていただきたいのと。","respondent":"福島ものづくり・経営支援課長","answer":"１００万円をどのぐらい開発費にですが、総経費は最低で１５０万円という申請がございました。一番高いのですと５５０万円程度ということで、大体２００万から３００万円台の開発経費という形でありました。","voiceIndex":29,"id":"exchange-009"},{"speaker":"沢田委員","kind":"質問","question":"そうだとすると、これからこの助成対象となった企業が、区内のいろいろな産業に今後、波及効果があるように周知していく、こういう技術がありますよということは、区としても今回助成した以上、今後ほかの企業にも紹介していったり、こういうソフトウェアが使えるということを企業に紹介するとか、そういうことは区としてやっていくのでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"実は製造業におきましてはクラスターフェア２０１１というのを２月ごろ大崎で開きまして、新製品開発であったものを広く公開することを行っているんですけれども、このソフトウェア部門をどういう形で紹介するのがいいのか、今ひとつわからないところもありましたので。","voiceIndex":31,"id":"exchange-010"},{"speaker":"宮崎委員","kind":"意見","question":"ソフトウェア開発ですけれども、ものづくりもそうなんですけれども、審査の体制というのはどういう体制なのか。今回は２件分の予算で、３件分は補正が成立したら助成するということですけれども、件数の考え方というのは、まず枠があることが前提となっているのか、それともいいものがあれば枠を越えてやっていくという内容で助成を考えていくのか、そこのところはどうなのか。","respondent":"福島ものづくり・経営支援課長","answer":"今回につきましては２０件のうち５件はぜひ助成したいと、それだけいいものが出たということもありまして、特に補正をお願いしてございまして、来年度以降は決められた枠の中で調整をしたいというふうに考えてあります。","voiceIndex":33,"id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今の説明ですけれど、私はやはり初めに予算ありきとなると、有望なところがあってもちょっとの差で外されるとか、そういうことにもなってしまうんだろうなと思って、今回は補正で出てきたんですけれども、やはり最初の枠は限られているので、そういう意味ではもうちょっと審査の考え方というのは、いいところを支援するという考え方にシフトしていくというか、そういうことも必要ではないかと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-012"},{"speaker":"石田副委員長","kind":"質問","question":"１０年に１度だと同じような金額がかかってしまうわけですから、せっかくこういう調査をしてデータベースをつくるのであれば、やはり毎年更新というのが望ましいですし、それを区としてやるのか、今回この調査は区でやりますから、今後は商店街にお願いをしていきたいという、ある程度条件つきではないですけれど、そういったことを促していくのか。","respondent":"川崎生活安全担当課長、米田商業・観光課長","answer":"１点目の設置のあり方や今後の方向性についてでありますが、カメラを設置するにはお金がかかりますので、町会のお金の中からも自己負担金がかなり出ます。データのメンテナンスに関する件ですが、本来商店街からの報告に基づいて商店街連合会がまとめていくことが定期的にできていれば、５年、１０年ということでデータが古くならないということはあるかと思います。","voiceIndex":36,"id":"exchange-013"},{"speaker":"石田副委員長","kind":"質問・要望","question":"それぞれありがとうございました。防犯カメラのほうですが、どういった事件があったかとかではなくて、例えば防犯カメラをつけた後と前と、事件件数がどのように推移をしているのかというデータというのは警察が持っていると思うので、そういった共有をされているのかどうかをお聞きしたので、そこをお答えください。","respondent":"川崎生活安全担当課長、米田商業・観光課長","answer":"今年は８月末現在で１６件と、街頭犯罪は非常に減っております。したがいまして、警察のほうと連携しておりますが、防犯カメラを設置したことによってその町の街頭犯罪は減ってきていると認識しております。データの更新につきましては委員ご指摘のとおり、片方だけのデータが陳腐化することがないように、データ作成自体がこれからの話ですけれども、相互の連携を深めながら更新をしてまいりたいと考えています。","voiceIndex":39,"id":"exchange-014"},{"speaker":"藤原委員","kind":"質問・要望","question":"品川荘、しながわ光林荘ですけれど、３の(1)で「区の管理運営経費を大きく抑制」とありますが、具体的にどういうふうになるのか教えていただきたいんですけれど、具体的に数字的なものがわかれば教えていただきたい。ここで事業開始から５年経過していて、導入目的の役割を果たしたというんですけれども、まず導入目的を改めてお伺いするのと、なぜ今回役割を果たしたと判断したのか教えていただけますか。","respondent":"武内地域活動課長","answer":"ですから実際に利用するときは区民の方と区外の方と、中身的にサービス内容は同じですけれども、予約については３カ月先にとれるということと、先ほど言った料金体制も、それは今後の検討ですけれども、区民については補助金制度も実施していくことも視野に入れておりますので。","voiceIndex":53,"id":"exchange-015"},{"speaker":"藤原委員","kind":"意見","question":"例えば品川荘も、これから何年かしたら６割以上とかの数字が出てくると思うけれども、区民保養施設という施策自体、もう区としては、品川荘とかに関しても７割、８割行っていなければ、もう区民の保養施設に対する助成とか補助とか施策というのは、どんどん行革という名においてやめていこうという方針に持っていくのか。","respondent":"武内地域活動課長、中川原地域振興事業部長","answer":"やはり民間企業のノウハウといいますか、現状ですと品川区民に対しての利用のＰＲがほとんどなわけですけれども、ホテル経営のノウハウがあるところの６区の実情を見ますと、かなり実績もありますので。区民保養施設の考え方ですが、課長が今まで説明してきたのはちょっと違いがあるんですね。区が持っている直営の区民保養施設というのは、区が建てて持っているんですね。","voiceIndex":55,"id":"exchange-016"},{"speaker":"本多委員","kind":"質問","question":"やはりコストを下げるとか、世論のニーズが変わりつつあったり、民間で今おっしゃったように５,０００円、６,０００円、７,０００円で１泊２食とか、時代の流れでこういう方向だというのは理解できます。で、質問したいのは、この新しい民間貸付方式について、貸し付けの期間はどのぐらいで考えているのか。その辺をまず教えてください。","respondent":"武内地域活動課長","answer":"これもやはり施設全体を民間事業者に貸し付けるわけですので、あまり短い期間でやりますと契約の関係等ありますので、とりあえず他区の例もかんがみながら、５年を目途にという考えでおります。","voiceIndex":58,"id":"exchange-017"},{"speaker":"本多委員","kind":"質問・要望","question":"それとちょっと参考までに教えていただきたいんですが、しながわ光林荘が去年の１０月から浴室の修繕工事をされましたけれども、この概要を教えていただきたいんですが。","respondent":"武内地域活動課長","answer":"アスファルトの補修で１,２００万円ほど、浴室ろ過装置の交換で２,６８０万円ほどというのが主なもので、それとあと設計管理委託ということで２５０万円という金額です。","voiceIndex":60,"id":"exchange-018"},{"speaker":"本多委員","kind":"意見","question":"もう１点ですが、品川荘もしながわ光林荘も、新しい事業者がいろいろな運営を考えられるので、料金設定もこれから変わる可能性があると思うんですけれども、そのときにしながわ光林荘は、文教委員会の所管にまたいで、答えられなかったら結構ですが、移動教室で子どもたちが使うときに、同じように上がってしまってはどうなのかなと思うんですが、その点を参考までに聞かせてください。","respondent":"武内地域活動課長","answer":"あり方検討の中では、この辺の費用については従来どおりの金額で、学務課のほうでまた予算計上するということで調整をしています。","voiceIndex":62,"id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問・要望","question":"品川荘としながわ光林荘を新たな手法で貸すということですけれども、内容を見るといわゆる指定管理者制度みたいな感じなのかなと思ったんですけれど、その辺の説明をしていただきたいと思います。実際に貸付先の見通しはあるのかどうなのかと、その条件ですね。例えば事業者の責任の範囲の問題とかいうのもあるかと思うんですけれども、そこら辺の考え方も伺いたいと思います。","respondent":"武内地域活動課長","answer":"条件等については今お話ししたとおり、区のほうでの経費持ち出しについては大規模修繕の部分と固定資産の部分になりますけれど、あとは民間事業者の創意工夫の中でやっていただくということで、利用料金については。","voiceIndex":64,"id":"exchange-020"},{"speaker":"宮崎委員","kind":"質問・要望","question":"要するに、やりようによっては９割まで伸びるというのであったら、結局大変なところは区のほうが持って、うまいところは持っていかれちゃうとか、そういうふうに思うんですけれど、そうならないような仕組みというのがあれば、ちょっと説明いただきたいと。さっき品川荘としながわ光林荘の、「品川」という名前が残るんですかというお話だったんですけれど、どうでしょうか。","respondent":"武内地域活動課長","answer":"それと民間事業者に貸し付けるわけですから、品川荘という名称で全国的な皆さんにおいでいただけるのかという部分については、名称を変えていくという方法も他区ではやっていましたので、その辺はその事業者との今後の相談というか検討の中で。","voiceIndex":66,"id":"exchange-021"},{"speaker":"宮崎委員","kind":"意見","question":"まだわからないところがあるんですけれども、先ほどの建物管理をどうしていくのかというところは、今の説明だと本当に不十分かなと思います。ということになると、本当に施設そのものがしっかり使われていくのかどうか、非常に不安が残ると思います。ここのところはこれからいろいろ事業者と詰める話だと思うんですけれども、工夫していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-022"},{"speaker":"山元委員","kind":"質問・要望","question":"平成２３年度をもって廃止の方向というか、老朽化しているということですけれども、実際は、建物が古くなったと言いながらも、４８％の施設を利用しているということで、その方たちがだんだん利用しづらくなっていくわけですけれども、廃止後は売却の方向で引き続き検討を進めるということは、いろいろなことを考えていらっしゃるのかなと思うんですが、一応区としてはどのように、売却は最終的としても。","respondent":"武内地域活動課長","answer":"個人が使う分にはもちろんいいんですけれど、例えば区民を対象にしたオートキャンプ場だとか、何とか農園とか、そういうものはできないという覚書がありますので、今後売却するに当たっても。","voiceIndex":69,"id":"exchange-023"},{"speaker":"山元委員","kind":"質問","question":"今、ここは公共的なものでないといけないとおっしゃったんですが、それこそ品川区は今、特別養護老人ホームがどうのこうのというふうにいろいろお話が出ているんですが、そういうことというのは、さっき１０億円というお話がありましたが、例えばそういうものを建てたとしたらどうなのかなと、採算が合わないのかなとかいろいろ、その辺のお考えはなかったんでしょうか。","respondent":"武内地域活動課長","answer":"いわゆる住居以外、特別養護老人ホームについては建設できないという当初から契約がありますので、なかなか縛りがかかっているということであります。ですから売る際もかなりその辺、厳しい部分があるのかなと考えております。","voiceIndex":71,"id":"exchange-024"},{"speaker":"大倉委員","kind":"質問・要望","question":"ちょっとお聞かせいただきたいんですが、おおむね品川荘の年間の運営費と、利用者はどういった方が、高齢者がほとんどだと思うんですが、どういった方が利用されているのか、わかれば教えていただきたいと思います。","respondent":"武内地域活動課長","answer":"障害者の方については減額制度もありますので、そういうところから数字が出てくるんですけれども３３６人、またそれに伴う介護者の方が９７人、小学生の方が２８７人というような利用状況ですので、比較的高齢者の方が多いという数字は出てきているところです。","voiceIndex":73,"id":"exchange-025"},{"speaker":"大倉委員","kind":"質問","question":"品川荘を民間貸付方式にして、例えば助成が２,０００円とか４,０００円という中で増えた場合、それがすごい額になったりすると、今までの運営費分を賄えたりすることにはならないんですか。","respondent":"武内地域活動課長","answer":"インターネットでやる場合については、今後、高齢者の方の優先枠みたいな方法も検討していかなければいけないのかなと考えております。","voiceIndex":75,"id":"exchange-026"},{"speaker":"石田副委員長","kind":"質問・要望","question":"私たち会派でも区民保養所についてはいろいろ議論をしていた中での、今回のこの報告であります。廃止になるわけですから、やはり思い出がある人がもう一回最後に行きたいなとか、そういう思いを持たれる方もいると思いますので、そういった施設がなくなっていくということは周知をしっかりしていただきたいと思うんですが、その辺の考え方を教えてください。その辺の考え方を改めて教えてください。","respondent":"武内地域活動課長","answer":"ただやはり利用率を高める、区民の方が行きたいときに早目にとるという部分については、予約が決まっている方については６カ月前から早目に施設のほうにということが他区の民間貸付では行われておりますので、それをもとにしまして、また先ほどもありましたとおり。","voiceIndex":77,"id":"exchange-027"},{"speaker":"石田副委員長","kind":"質問・要望","question":"予約もそうですし、こういった施設があるよという周知方法も課題の一つだったのかなと思います。今までにあった課題、新たな方式の上ではありますが、課題というのは似たり寄ったりする部分があるのかなと。そういった部分で、今まであった課題は新しい方式になって解決していただいて、民間に貸し付ける中でも区の施設ですから、できる限りの協力体制で行っていただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2616#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":36176,"voices":91}},{"id":"h23-20110926-7","meetingId":"h23-cm09","date":"2011年9月26日","dateIso":"2011-09-26","committee":"厚生委員会","time":"午前１０時００分～午後２時１０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を55件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"資料３ページで、サービス付き高齢者住宅ということなんですけれども、高齢者円滑入居賃貸住宅とか、高齢者専用賃貸住宅とか、高齢者向け優良賃貸住宅がなくなって、サービス付き高齢者住宅に一本化されたということを、ちょっと見たんですけれども、サービス付き高齢者住宅になることに関して、何が変わるのか、違いはあるのか、教えていただきたいんです。","respondent":"間部高齢者いきがい課長","answer":"これにつきましては、高齢者住まい法に定められているように、先ほどもご説明いたしましたとおり、状況把握サービスおよび生活相談サービスということで、多少介護が必要になった状況においても、住み続けられるような形ということでできた制度です。","voiceIndex":10,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"今までの制度と、今回の制度との違いを教えてください。","respondent":"間部高齢者いきがい課長","answer":"これは、国の流れでも同様なんですが、かつては、住宅施設につきましては国土交通省、また福祉施策につきましては厚生労働省と所管が違ったわけですが、今後、２０２５年に向け、団塊の世代が後期高齢者に入っていくなかで、国としてどのように対応するかということで。","voiceIndex":12,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"介護が必要になってもいられるということで、要介護度がいくつまでという話もありましたが、大体どのぐらいまでいられるのか、想定はあるのでしょうか。","respondent":"間部高齢者いきがい課長","answer":"介護度どのぐらいまで住み続けられるかというご質問ですが、既存の高齢者住宅におきましても、大体、要介護２ぐらいまでの方につきましては、十分に生活をされているという現状からいたしますと、要介護３、４までは十分に対応できるのではないかと想定しています。","voiceIndex":14,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"住宅の１戸ごとの平米数はどのぐらいになっているのか、タイプ別で教えてください。","respondent":"間部高齢者いきがい課長","answer":"高齢者住宅の専有面積ですが、ふろなし、ふろ付きの単身向けと、世帯向けがあります。ふろなしにつきましては２５m2、ふろ付きについては２７m2、世帯向けについては、おおむね５０m2となっています。","voiceIndex":16,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"ふろなしは、どうして設けたのか、ちょっとお聞きしたいんです。","respondent":"間部高齢者いきがい課長","answer":"なぜ設けたかですが、やはり、本件につきましては、使用者の主な要件ということで、６５歳以上の自立した住宅に困窮している方を想定しているわけですが、中には、申請時に要支援、要介護１、２の方もおられるということから、当初から介護が必要な方については。","voiceIndex":18,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"入浴に関してなんですが、４ページの白抜きの星印のところに、入居者の希望に応じて、食事サービス、入浴サービスを提供するということなんですが、入浴サービスは、だれを対象に、だれが付き添うのか、教えてください。","respondent":"間部高齢者いきがい課長","answer":"当初、自立ということを念頭に置いておりますので、ご自身で入っていただくことが通常の使用の方法です。ただ、要介護になって、ヘルパー等に付き添っていただいて利用するという形態も含めて対応ができるものになっています。","voiceIndex":20,"id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"今のところで、食事サービスも聞きたいんですが、大体１食いくらぐらいで、もし３食全部利用した場合に、月いくらぐらいかかるのか。この図面を見ると、調理室がちょっと小さいような感じがしたんですけれども、もしたくさんのサービス利用があったときに対応できるのかと、単純に思ってしまったのですが、教えてください。","respondent":"間部高齢者いきがい課長","answer":"ただ、当然、お一人でもいれば、対応していくわけですが、少ない方について、どのように対応するかということについては、指定管理予定者のさくら会と、十分に情報交換をしながら対応していきたいと考えております。","voiceIndex":22,"id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問","question":"次の質問で、応募者が多数でオーバーした場合は、優先順位とか、どういった方を優先的に入れていくのかとか、そういうことはあるのでしょうか。","respondent":"間部高齢者いきがい課長","answer":"定員を超えるお申し込みがあった場合、です。本件につきましては、考え方としましては、今回、高齢者住宅として募集するのは７０戸になります。そして、住みかえが２０戸あります。","voiceIndex":24,"id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問","question":"職員体制をお聞きしたいのですが、専門職員はどのぐらいで、福祉士とかヘルパーとかがどのぐらいいて、何人ぐらいの配置になるのか、最初のところをお聞かせください。","respondent":"間部高齢者いきがい課長","answer":"スタートについては、管理者、事務員、プラス生活支援員ということであれば、３名ぐらいかなと考えています。","voiceIndex":26,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"幾つか教えてください。ここら辺はどう考えているのか、教えていただきたい。ここで聞いていいのかどうかわからないんですけれども、東京ルールというのがあるわけですから、それにのっとって、それはやるべきなのかと、私はちょっと思っているんです。それから、これも教えてほしいんですけれども、小規模多機能型居宅介護のほうなんですけれども、和室は、多分６畳、６畳にしたんですよね。","respondent":"間部高齢者いきがい課長、原高齢者福祉課長","answer":"判例も踏まえて、利用者が負担すべきものについては、当然負担していただくような考えになろうかと思いますので、そういうような対応をしてまいりたいと考えています。こちらにつきましては、利用者がどのぐらいの要介護度か、あるいは、そういった状況のなかで、やむを得なく横になる必要があったりした場合については、臨機応変な対応が必要と考えています。","voiceIndex":28,"id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"抽選をするんだと。それをもう一度教えていただきたい。いただくものはいただく、ちゃんと利用者のご理解のもとに、普通は、先ほど言った、東京ルールもあって、今、動いているわけですけれども、私の知識のなさかもしれないのですけれども、法的に大丈夫というのかもしれないのですけれども、第１２条を読むと、これを素直に読むと、どうもそういうふうには取れないんですよ。前の二つは、教えてください。","respondent":"間部高齢者いきがい課長、木下健康福祉事業部長","answer":"我々が今考えておりますのは、その中で１０戸埋まると、あと１０戸があると。この１０戸について、当然、政策的に二つ、三つは残しておくということであれば、引いたあとの七、八戸については、高齢者住宅の募集になる。住みかえの部分が２０戸ありますけれども、基本的には所管が別で、言ってみれば、一つの高齢者の住みかえ、八潮団地における住みかえと、住宅密集地における住みかえという新たな政策課題について。","voiceIndex":31,"id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"要望だけしておきます。密集市街地も、さっき、都市計画課とおっしゃったんですけれども、責めをしないと、それは両方あるわけですけれども、やっぱり健康福祉事業部長のほうから少しプレッシャーをかけるというか、はたから見れば、品川区は一つなわけなので、ぜひ、そこら辺のところを強くやっていただいて、住みかえがもっと多く進むようにしていただきたい、これはお願いだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"高齢者住宅ですので、多分、年１回の募集で、順番待ちというのか、ストックがされて、空きが出れば入るという仕組みになるのかなと思っているんですが、そうすると、１ヶ月前に出ますという申請で、引っ越される方はあれですけれども、どうしても亡くなられる方はいらっしゃると思うんですけれども、この１４日前というのは、もうちょっと長くしたほうが、一般的に空室をなるべく少なくするということで。","respondent":"原高齢者福祉課長、間部高齢者いきがい課長","answer":"そういった意味では、機械浴をなるべく使わないで介護をする、本人ができることはなるべくしていただく、そういうことを基本に置きつつ、そうは言っても、なかなかそこが難しい方もいらっしゃいますので、そちらについては。ただ、どうしてもいろいろな事情がありまして、遅れる、早まるということはあるわけでございまして、そのあたりは、運用で対応してまいりたいと考えています。","voiceIndex":35,"id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"この施設の中での、こういった高齢者の方々の交流の部分。比較的中規模な公園もあるということで、地域の方、小規模多機能型居宅介護を含めて、決して閉じた空間にならないように、中、また外との異世代の交流等に、これからまたしっかりとご尽力をして、計画を立てていただきたいと思いますけれども、見通しをお願いいたします。","respondent":"間部高齢者いきがい課長","answer":"そういった点では、大変に恵まれているのかなというふうにも考えてあります。立会小学校、その他、近隣との世代交流につきましては、こちらも、指定管理者とよく相談しまして、できる限り対応してまいりたいと考えています。","voiceIndex":38,"id":"exchange-014"},{"speaker":"鶴委員","kind":"質問","question":"ちょっと聞き漏らしているのかもしれませんけれども、条例のほうの、第１３条の電気・ガスおよび上下水道の使用に要する費用というところに関係するのですが、先ほど、建物の施設に関して、ふろなしの方は、２階の浴室で、極力ご自分で、というお話もありましたけれども、それぞれの部屋にある方は、当然、水道料とかがわかると思うんですけれども、２階のおふろを使われるふろなしの方の１回のおふろ代は。","respondent":"間部高齢者いきがい課長","answer":"第１３条、費用負担に係わるご質問です。ふろなし、ふろ付きということで、先ほど、私は説明のなかで、単身用７万５,０００円というご説明をさせていただきました。ちょっと説明が漏れていたかもしれませんが、単身のふろなしにつきましては、家賃想定が７万円となっております。","voiceIndex":40,"id":"exchange-015"},{"speaker":"向委員","kind":"意見","question":"ある程度、要介護の状態になっても住めるということと、高齢者という理由で、なかなか部屋が借りられないとか、さまざまなご事情がある方がいらっしゃるかもしれないんですが、このあたりを考えると、使用料の助成制度は、しっかり条例のなかに入っていますけれども、初期費用の貸付ではないんですが、そのあたりのちょっとした支援とか、どのようにお考えなのかというところを、お教えいただけますか。","respondent":"間部高齢者いきがい課長","answer":"その次には、住宅の劣悪度ということで、いわゆる木造モルタルで、少しすき間風が入ってくるとか、日照の問題だとか、あとはおふろがないとか、そういう方がその次にランクされていくというような形で、今まで、対応してまいりました。","voiceIndex":42,"id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"大井林町高齢者住宅なんですが、スケジュールのところを、先ほど、高齢者いきがい課長からご報告いただいたんですけれども、ちょっとメモができなかったので、もう一度教えていただけないでしょうか。そして、指定管理者の決定の時期とかも含めて、ちょっとお願いします。","respondent":"間部高齢者いきがい課長","answer":"受付期間については、既存の高齢者住宅と一緒でして、１２月１日から１４日となっています。それに先立ちまして、１１月５日と１２日の土曜日、午前中になるのですが、それぞれ講堂および荏原文化センターにおいて説明会を実施していこうと考えています。","voiceIndex":44,"id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は、今のスケジュールは、ぜひ資料の中に書いて、わかるような形にしていただきたいと思いますので、これは要望させていただきたいと思います。ここら辺のところでは、はじめから全くの自立の方だけではなくて、要介護１、２ぐらいまでの方は対象になると、応募できると考えていいのでしょうか。","respondent":"間部高齢者いきがい課長","answer":"ただ、要介護１、２の方につきましてはなかなか難しく、先ほど、説明がよくなかったと思いますけれども、これにつきましては、入居して、加齢に伴って進んだ方というようなイメージです。訂正をします。","voiceIndex":46,"id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、応募できる方は、要支援１までということですか。介護認定を受けていてもいいのか、どうか。","respondent":"間部高齢者いきがい課長","answer":"介護認定を受けていても応募できるかということですが、実際に、応募のなかで要支援の方はおります。それでも、自立して生活ができるという約束をしていただくという条件になってあります。","voiceIndex":48,"id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"先ほどの説明だと、要介護３から４ぐらいまでの方は住み続けられる施設だというご説明がありましたけれども、ということは、今までの安心の住まいの考え方というのは、そこで、ある程度の介護サービスを受けながらも、もっと進んでしまって寝たきりのような状況になったときには、ケアホームですとか、特別養護老人ホームとかに移っていくと考えられていると思うんですが、それとは違って。","respondent":"木下健康福祉事業部長","answer":"お年寄りが集まって住むことによって、外部サービスが非常に効率的に提供できるというような考え方も踏まえた新しいタイプの住宅ですので、今後、運営していくなかで、お年寄りの心身レベルが徐々に低下していくなかで、体制をどうしていくかということを、これは探りながら。","voiceIndex":50,"id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、ほんとうに高齢の方が入られることになりますので、ゆくゆくは介護が必要な方というのがどんどん増えてくることになると思うんです。そのときに、今の高齢者住宅などでしたら、ほかのところにということになっていくのが、ここにかなりのところまでいられると。だけれども、ここの施設そのものが、特定施設の網がかかることは想定されていないのでしょうか。ゆくゆく、何年か先というところで。","respondent":"木下健康福祉事業部長","answer":"ハード面では、それは満たされておりますから。そういうことも一応視野に入れながら運営し、区と指定管理者が協議しながら、何年も先になると思いますけれども、その辺については、そういうことも検討していく時期が来る可能性は十分にあると思っています。","voiceIndex":52,"id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"特定施設となるト、１３万円では済まないのではないのかなという気がしまして、家賃に食費に、特定施設の１割に、多分もっとサービス利用料も加算されるのかなと思うんです。そういうことから考えると、今回、入居される方の収入は、どこら辺を想定しているというのはあるのでしょうか。","respondent":"木下健康福祉事業部長","answer":"特定施設が先にありきではなく、まず外部サービス利用型のなかで、基本的には運営をしていく。ただ、先々、そういうことも検討しなければいけないときがくるかもしれないということだと思います。","voiceIndex":54,"id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ほんとうにお金がないために出なければいけないということがないように、ぜひ、よろしくお願いしたいと思います。それから、２万５,６００円が上限ということだと、全員が２万５,６００円受けられるということではなくて、収入によっては受けられる額が違うということもあるのか、そこのところを教えていただきたいと思います。","respondent":"間部高齢者いきがい課長","answer":"どの範囲の方が受けられるかですが、年金収入の方ですと、ほぼ受けられるような形になりますが、所得の区分がございまして、例えば２万５,６００円満額をいただける方については、所得による区分が１２万３,０００円から１３万９,０００円程度の方ということで、ほぼ。","voiceIndex":56,"id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もう一つ、お聞きしたいのが、総工事費は１３億７,３００万円と書いてあって、特定財源が４億８,９００万円で、特定財源の意味がよくわからなくて、補助金ということになるのか、国と東京都からの補助金がどのぐらい出ているのかということを、教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"東京都のほうで住宅に係わる部分が２,４００万円、それから、小規模多機能型居宅介護の関係で４,５００万円ということで、６,９００万円があります。それを合わせて４億８,９００万円が特定財源という形で表示させていただいています。","voiceIndex":58,"id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"小規模多機能型居宅介護についても、ちょっと教えていただきたいのですが、今回が４カ所目ということなんですけれども、今、どういう状況になっているのか、私は把握していないので、教えていただきたいのです。それから、現在、小山と都南病院跡地と２カ所、区のほうでやっていますけれども、その利用状況と、待機者の状況、そこら辺の利用状況について、ちょっと教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"このサービスは、在宅を進めるうえで、デイサービスに行っても、あるいは泊まりのときにも、あるいは、訪問介護というところのなかで、顔なじみのスタッフがやってくれるということで、ほかのサービスは、ヘルパーはヘルパー、デイサービスはデイサービス。","voiceIndex":60,"id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"今回の大井林町の小規模多機能型居宅介護は、対象地域は、どこら辺までという限定はあるのか、区内中ということになるのか。それからもう一つは、どういう職員体制で行われるのかについても、お聞かせください。","respondent":"原高齢者福祉課長","answer":"地域ですけれども、こちらは地域密着型サービスという形になっておりますので、一定程度、周辺地域ということで考えているところです。","voiceIndex":62,"id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"最後にもう一度高齢者住宅に戻って一つお聞きしたいのが、高齢者住宅の職員体制なんですが、生活支援員というのは、多分専門職ということで規定されているのではないかと思うんですけれども、どういう専門職が配置されるのかということ。それから、夜間の職員の体制はどうなるのかも、お聞かせいただきたいと思います。","respondent":"間部高齢者いきがい課長","answer":"ですから、今、考えられるのは、事務員でも対応ができれば、対応できますし、さくら会が指定管理予定者となっていますので、当然、同じフロアに小規模多機能型居宅介護の職員もいれば、在宅支援センターの職員もいますから、そういう応援も考えられるということで。","voiceIndex":64,"id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"夜間は夜勤者ということですけれども、毎日配置されて、ローテーションで夜勤をされていくことになっていくと、施設長、事務員、生活支援員、夜勤者ということで、トータルの職員は、何人ぐらいの体制でやられるようになるのでしょうか。","respondent":"間部高齢者いきがい課長","answer":"夜勤につきましても、現在、指定管理者と相談中ですが、非常勤職員を充てるというような考え方ですので、常勤ではございません。それから、先ほど来、申し上げていますように、管理者、事務員、生活支援員というような３名については、確保できるだろうです。","voiceIndex":66,"id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"確認","question":"１点だけ確認させてください。そうすると、だれが、どうやってその方を小規模多機能型居宅介護に登録するのか。多分、要介護２.６で２０人ぐらいになったら、それでもうかつかつだろう。要介護２.６の平均で来なくてはならないとなると、そこら辺のところは、機械浴というのはどういうふうに思っているのか、考えてほしいと思うんです。そこら辺の確認だけ、教えてください。","respondent":"原高齢者福祉課長","answer":"そういった意味では、今言ったような連携のなかで、機械浴の関係でいけば、先ほどの機能の問題もありますので、なるべく機械浴ではないと困るという方を想定をしていくと考えております。","voiceIndex":68,"id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だけれども、ある程度、採算もあるわけですよね。ぜひ、そこら辺は、ほんとうに在宅で頑張っていらっしゃる方の支援のためにあるわけですから、近隣の地域密着であるのであれば、要介護２.６ぐらいのところをクリアしないと、多分、採算は合わないので、そこら辺だけは、ぜひ考えてやっていっていただきたいと、私は思うので、ぜひお考えをお願いします。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-030"}]},{"id":"topic-02","title":"第４６号議案、平成２３年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第４６号議案、平成２３年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"介護者支援検討委託のところで、これはいつごろやられて、対象は何人ぐらいなのか、教えてください。","respondent":"原高齢者福祉課長","answer":"対象者につきましては、基本的には訪問介護員ということで、区内に約５０の事業所がございまして、そういったところにもお声がけをして、いろいろな意見を吸い上げていくような形で検討しています。","voiceIndex":85,"id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ちょっと教えてください。それで、東京都が１００万円を出すと言ったから、増やそうとしたのか、逆に最初からやろうと思えば、第５期に向けて、今もう準備をされているのでしょうから、それは十分に予算を取っているはず。それから、これも教えていただきたいのですが、一番最後の自立支援サービス追加分なんですけれども、３月２２日に認定を受けたというと、時間の都合上、どうしても今になるのか。","respondent":"原高齢者福祉課長、永尾障害者福祉課長","answer":"そういった意味では、今回、東京都のほうでも１０分の１０の補助で、それを補完する形で、私どももこういったところからニーズをまた一つ吸い上げて、どのようにしていったらいいかという検討の俎上のなかで。なぜ９月補正にしたかですけれども、４月以降になって申請をいたしまして、金額の確定した時期を考えますと、９月補正ということになりました。","voiceIndex":87,"id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"意見","question":"私の聞き方が悪かったのか、私の認識、理解度が悪いのかもしれないのですが、介護者のところは、もともと第５期に向けてしっかりやられていると、私は理解していて、しっかりやられているんだけれども、こういうものが東京都にあって、では、これもお金をもらってしまおうと手を挙げたとなると、やってきたことは変わらないんだと。ただ、財源的に、そこの部分が手を挙げて取れたという理解なのか。","respondent":"原高齢者福祉課長","answer":"今までも、高齢者の一般調査でありますとか、あるいは、サービス事業者であるとか、いろいろな形でご意見をいただいて、第５期に向けて検討しています。","voiceIndex":90,"id":"exchange-033"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"第５期に間に合うようにということであれば、多分１０月ごろには骨子案をまとめていくことになると思うんですけれども、早急にアンケート調査をして、それをまとめるという日程でされるのか、そこら辺のところもあわせてお聞かせいただきたいと思います。","respondent":"原高齢者福祉課長","answer":"どのぐらいの対象かですけれども、各事業者には、そういった形でお声かけをして、情報を収集していきたいと考えているところです。","voiceIndex":92,"id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"何かすっきりとわかりにくいのですけれども、これは結局、品川ケア協議会に参加をされている１１事業所に委託して、そこが、それぞれヘルパーステーションに調査をして、どういう要求があるかということを、ヘルパーステーションから聴取するということで、介護者自身から聴取するということではなくて、介護者がどういう要求を持っているかということを。","respondent":"原高齢者福祉課長","answer":"今のところ、詳細について、どのぐらいの規模までできるかというのは、今、業者のほうと検討をしている最中ですので、どの範囲までというのは、これからになるかと考えています。","voiceIndex":94,"id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ということは、その品川ケア協議会の１１事業者のところでは、利用者の家族の介護者に直接聞くと。そして、また、品川ケア協議会を通して、４０社のヘルパーステーションのほうにも聴取をして、把握すると。それを品川ケア協議会が、一定のどんな要望があったかということをまとめて、区のほうに提示をすると、そういう形になるということでしょうか。","respondent":"原高齢者福祉課長","answer":"委員ご指摘のとおりです。","voiceIndex":96,"id":"exchange-036"}]},{"id":"topic-03","title":"平成２３年請願第１９号 八潮・杜松小跡につづく特養ホームの増設を求める請願","agenda":"平成２３年請願第１９号 八潮・杜松小跡につづく特養ホームの増設を求める請願","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ここにも書いてありますように、６月議会で、この質問をしたのは私でありまして、まさに、特別養護老人ホームも計画的に進めていただきたい、老人保健施設も増設していただきたいという質問をさせていただいて、こういう答弁であったということです。そういう形のなかで、私も、平成２３年２月１７日に出された平成２３年請願第４号で、同趣旨の請願があります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-037"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、積極的に行っているということを、実態と状況を踏まえて、見せていただきたいと思うんです。情報収集など、民間の土地も買い取っていくということで、この間、６月から９月ですので、ちょっと短いですけれども、積極的に行ったことで何か具体的なものがあれば、教えていただきたいのですが。","respondent":"原高齢者福祉課長","answer":"残念ながら、今日の段階では、結びついている情報ではないわけですけれども、そういった意味で、私どももただ待っているわけではなくて、それぞれのある情報のなかに、私たちの施策を織りまぜることができないだろうかというようなことも踏まえて、議論をしています。","voiceIndex":126,"id":"exchange-038"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"積極的なというところでも、なかなか見つからないのはわかるんですけれども、区として、見つけたら、そこはすぐに特別養護老人ホームしていくと、積極的にというのは、そういうことではないかと思うんです。そういう立場で探されているのか、見つかったら、そこは特別養護老人ホームにしていこうという思いなのか、立場をお聞かせいただきたい。","respondent":"原高齢者福祉課長","answer":"ただ、土地ですので、トータル的な中で、行政としてまずは判断をする形のなかで、どういう使い方がいいのかというなかに、当然のことながら、特別養護老人ホームも入ってくるという認識でおります。","voiceIndex":128,"id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"意見","question":"それはもう十分にご承知のことだと思うんですけれども、積極的につくっていくんだという立場であれば、土地の規模が大きかろうか、小さかろうが、見つけたら、ある程度の土地の面積が確保できるのであれば、そこは特別養護老人ホームにしていくんだという立場がどうかということを、お聞かせください。","respondent":"原高齢者福祉課長","answer":"そういった意味では、運営をしていくことも一つの大きな要件ですし、そういったなかで、区としては、適地を探しているという視点には変わりはございません。","voiceIndex":130,"id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"積極的にということに、私たちもほんとうに期待を込めていますので、増設を一日も早くという思いは、わかっていただけると思うんです。それが今日か、明日かという問題ではなくて、かといって、それが１０年後、２０年後と言われるとは、それはそれでほんとうに困ってくるわけです。ですので、一日も早くという思いをぜひくんでいただいて、これは強く求めていきたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-041"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"だから、そういう点では、区としても、そういう状況はつかまれていると思うんですけれども、そういうところをベースにして、できる限り早く建設をする、土地が見つかれば、一日も早く建設をしたいんだと、そういう思いであるということを、ひとつ確認をさせていただきたいんですが、いかがでしょうか。","respondent":"原高齢者福祉課長","answer":"そういうなかで、特別養護老人ホームの話も、建設ということもあります。６月議会で健康福祉事業部長から申し上げましたように、積極的に、ということで、私どもも認識をしています。","voiceIndex":133,"id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私がお伺いしたいのは、今、一生懸命土地を探しているということですけれども、土地が見つかれば、一日も早く建設をしたい、できる限り早く建設をしたいんだという思いで探しているのか、どうか。土地が見つかり次第、一日も早く建設したいという思いなのかということを確認させていただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-043"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"改めて、ここの中にもありますけれども、２月締切、３月入所調整会議にかかった方は６０９名でしたけれども、今回の８月締切、９月入所調整会議はもう済んだのでしょうか、それにかかった方が、たしか５９１人でしたか、その人数と、要介護度別の人数、それからあとは在宅と、施設からの申し込みの人数を、それぞれ、９月の時点での人数を教えていただけますでしょうか。","respondent":"原高齢者福祉課長","answer":"申し込みいただいたのは５９１名でございまして、要介護別ですと、１から順番にお話しします。要介護１の方が７６人、要介護２が８８人、要介護３が１７８人、要介護４が１５７人、要介護５が９２人です。在宅と施設のところですけれども、在宅が２５４人、施設が３３７人です。","voiceIndex":140,"id":"exchange-044"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今回のではないのですけれども、今までで、おおよそ半年間で入れている人数を、平成２２年度の前半、後半、また、平成２３年度で、今まででどのぐらい入れているかの人数も教えてください。","respondent":"原高齢者福祉課長","answer":"今までのおおよその推計というのですか、実績からいきますと、半年で約６０名、それから、１年で１２０名です。平成２２年度はもう少し人数が多い状況で入所が行われたです。","voiceIndex":142,"id":"exchange-045"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"改めて、半年で６０名というと、要介護４と５の数を合わせても２５０名ぐらいになって、要介護３まで合わせると、三百数十名ということになると思うんですけれども、そのなかで、６０名しか入れないというところでは、ほんとうに切実な方が入れていないという実態があると思うんですけれども、その点についての認識を、改めて、お伺いしたいと思います。","respondent":"原高齢者福祉課長","answer":"そういった意味では、区民の皆様が感じているところは、私どもも認識をしています。そういったなかで、特別養護老人ホームの建設についても積極的にという話のなかで考えていくということで、この間、申し上げさせていただいているところです。","voiceIndex":144,"id":"exchange-046"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"積極的に建設をしていくという明確なご答弁をいただきましたので、ぜひ、ほんとうにこれに沿ってやっていただきたいと思うんです。用地取得のために積極的に情報を収集していくというのは、具体的にどういうことで、これがどういうふうに結果に結びついていくのか、そこら辺のところを、ちょっとお聞かせいただきたいと思います。","respondent":"木下健康福祉事業部長","answer":"前回答弁で申し上げたことの背景ということになるわけですけれども、この間は、まず、特別養護老人ホームを整備する方針というのは、平成２０年に変わったわけでありますが、基本的には、学校の跡施設を利用するということを基本に、この間、進めてきたわけであります。","voiceIndex":146,"id":"exchange-047"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"民間の土地情報も積極的に収集していくということなので、ぜひ、そこら辺のところは積極的にしていただきたいということと、それから、ちょっと具体的にお聞きしたいのが、今、ＪＴの跡地がどうなっているのかということがわかったら、教えていただきたい。","respondent":"原高齢者福祉課長","answer":"そういった意味では、声がかかっておりませんので、その後の進展は全くないです。それから、区内の国有地等々の情報ですけれども、それにつきましても、用地情報のなかの一つかと思いまして、そういった意味では、現段階ではきていないと認識をしています。","voiceIndex":148,"id":"exchange-048"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ＪＴについては、ぜひとも。都南病院の跡地のときなんかも、品川区としても、いろいろ積極的に交渉したという経過があったと思うんですけれども、ＪＴに対しても、そういうふうに積極的に、品川区としても土地を取得するということで働きかけるということは、今はされていないのでしょうか。する考えはどうなのか、そこら辺のところも、あわせてお聞かせください。","respondent":"原高齢者福祉課長","answer":"ＪＴの跡地の問題につきましては、相手のあることですので、相手のことを一定程度踏まえるということも、これは大事なことかと考えています。そういった意味では、今は、待ちの状態ということでやっておりますので、そういったところでご理解をいただければと考えています。","voiceIndex":150,"id":"exchange-049"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もう一つ、第５期には、そういう土地の情報が明確になっていないところでは、計画には入れられない、明記できないということでしたけれども、第５期にほんとうに入ったばかりに、例えば土地があったとかということになれば、計画のなかには入っていなかったとしても、第５期のなかで建設していくということで、そこは確認させていただけるのかどうか、お願いします。","respondent":"原高齢者福祉課長","answer":"それから２点目の、計画に入っていなくて、土地が出てきたら、計画に入っていないからつくらないのかというようなご質問かと思いますけれども、先ほどの条件が整えば、第５期の計画に入っていないからつくらないということではございませんで、その辺については。","voiceIndex":152,"id":"exchange-050"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"整備率にしても、２カ所できたとしても、まだまだ２３区のなかでも決して高いほうではなくて、低いほうだという状況は変わりませんので、そういう点では、ぜひ特別養護老人ホーム、一日も早く増設をしていただけるようにお願いして、要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":154,"id":"exchange-051"},{"speaker":"石田（秀）委員","kind":"質問","question":"先ほども言いましたけれども、私は特に、この質問をして、再質問もしたのでありまして、再質問の答弁を、今、使われているようなことがありますけれども、趣旨は非常によくわかるということであります。前もって、平成２３年２月１７日に出された、平成２３年請願第４号でも議論をしているということもありまして、それを踏まえて、趣旨採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":164,"id":"exchange-052"},{"speaker":"若林委員","kind":"提案","question":"公明党も、これまで、特別養護老人ホーム、老人保健施設、数えたらきりがない提案、質問をしています。意見につきましては、２月の同趣旨の請願から半年、まだ特別養護老人ホームを一日も早くという部分についての採択は、私たちはそぐわないと考えていますので、同様の趣旨採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":165,"id":"exchange-053"},{"speaker":"向委員","kind":"意見","question":"この内容、趣旨は重々と承知しておりますし、理解できると、会派としてもそういった考えでおりますし、先ほど、高齢者福祉課長からも、健康福祉事業部長からもお話がございましたが、本区としても、前向きに検討してくださっているというお考えも十分にわかりましたので、それを踏まえましても、もうちょっとはっきりと明記をするというところは、やはり難しいのだろうなというところで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":166,"id":"exchange-054"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"いろいろ質問もさせていただいたなかで、要望も言わせていただいたんですけれども、積極的に、引き続きほんとうに進めていただきたい。一日も早くという気持ちで、建設に向かっていただきたいと思いますので、採択でよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":167,"id":"exchange-055"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3304#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":43193,"voices":175}},{"id":"h23-20110926-8","meetingId":"h23-cm09","date":"2011年9月26日","dateIso":"2011-09-26","committee":"建設委員会","time":"午前１０時００分～午後２時２８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第５２号議案、品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","agenda":"第５２号議案、品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","exchanges":[{"speaker":"武内委員","kind":"質問","question":"耐震工事が終わった後、今回、設置するところの駐輪場は、また撤去して、陸橋の下にまた同じように場所を変えるのか。それともそのまま変えないのか、それか、もしくは、併用するのかということと、あと今度新しく変わるところ、順番が逆になりましたけど、新しく敷設するところは台数的には今陸橋で敷設されている台数と比べてどんな感じなのか教えてください。","respondent":"藤木交通安全担当課長","answer":"ご質問の１点目の耐震補強工事終了後、移設した駐車場をどうするかです。こちらのほうでは、現在地元ですとか警察のほうと現在の交通上の問題などを勘案しまして、とりあえず現時点では耐震工事終了後、またもとのところにすべて戻すという考えで進めているところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"武内委員","kind":"質問","question":"そうすると、当日利用は同じだということなんですけど、定期が半分ぐらいになっちゃうのとバイクが０台ということなんですけども、今の需要というんですか、状況がよくわからないんですけど、減ってしまうので、その辺の放置自転車の心配と、もし心配なら対応をどうするのかということと、あと需要はかなりあるのなら、今のところという条件つきでしたけども、場合によっては一部陸橋に戻したとしても。","respondent":"藤木交通安全担当課長","answer":"今回６６０台に変わるということで、それでもさらに１４０台程度不足しているわけですけれども、大井町駅西口の駐輪場で、立会道路沿いの区のほうで設置してあるところがございまして、こちらのほうは非常にあきがございましたので、今回あふれた方につきましては。","voiceIndex":7,"id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"定期のことはわかりましたということで、今度バイクなんですけど、バイクの方は西口、立会道路側に少しあるということもわかりますが、この辺はどういう状況なのか。委員会の参考送付の案件でも、バイクのことについて出ていますけれども、そこのところはどのようになっているんでしょうか。","respondent":"藤木交通安全担当課長","answer":"バイクにつきましては、道路上でいろいろ設置、移設できるところはないかということで、いろいろ私どもも調査したり、あと道路以外にも調査をしたんですが、ちょっと該当するところがなく、また法令上も設置不可能ということで。","voiceIndex":9,"id":"exchange-003"},{"speaker":"井上委員","kind":"質問","question":"もう一つ、このバイクの９２台というのは、定期と当日利用というのはどういうふうになっていて、今までの利用率というか、現況はどうなっているんでしょうか。","respondent":"藤木交通安全担当課長","answer":"バイクにつきましては、すべて定期利用でございました。それで、定期利用で、利用率につきましては、東側が７０％程度、西側が６７％です。","voiceIndex":11,"id":"exchange-004"},{"speaker":"井上委員","kind":"質問","question":"ということは、民間あるいは普通の駐車場だとバイクがとまると相当ひんしゅくだということでとめにくいという状況があって、区でもそういうところをある程度ここにありますよという周知がないと、振り分けというか、移動もできないんじゃないかと思うんですけど、その辺の対応はどのようにされていたのでしょうか。","respondent":"藤木交通安全担当課長","answer":"今回の移設に伴いまして、これは自転車の方も同じなんですけど、移転の時期ですとか、移設先の駐輪場ですとか、それぞれご利用いただいている方のかごとかハンドルとかに、こちらのほうにバイクでしたら駐輪場があります、自転車だったら。","voiceIndex":13,"id":"exchange-005"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"８００台だったので、１４０台程度が足りないけども、あふれた分は立会道路のほうに案内したという話ですけども、それで足りているのか、それでもまだ足りない状況なのか、そこをご説明いただきたいと思います。改めて１,０８４台が、なぜ８００台しか確保できなかったのか、同規模程度の代替地の確保をしようとしなかったのか、その辺の経過をご説明いただけますでしょうか。","respondent":"藤木交通安全担当課長","answer":"もちろん無尽蔵にその範囲を広げていけば、当然もっと台数を多くすることができたんですけど、そのような中で、円を広げていく中で既存の区の駐輪場があって、そこで収容可能の見込みがあるということで今回このような形をとらせていただきました。","voiceIndex":15,"id":"exchange-006"},{"speaker":"中塚副委員長","kind":"質問","question":"今後のことですけれども、現状はもとに戻すというご説明でしたけども、そのときに、利用者の実態調査だったり、利用者アンケートだったり、そういうのはしっかり調べた上で大井町駅前の駐輪場をどう確保していくのか、そこはしっかりと踏まえた上で再検討すべきじゃないのかなと思うんですけども、その辺についてはどのようにお考えでしょうか。","respondent":"藤木交通安全担当課長","answer":"現在移設中で、今特に問題は起きていませんが、歩道上ということで、何らかの今後事故とかが発生する可能性が全くゼロとは申し上げられませんので、そういう状況を踏まえまして、改めて検討していきたいと考えています。","voiceIndex":17,"id":"exchange-007"},{"speaker":"武内委員","kind":"質問・要望","question":"２項目について聞きたいと思います。１期、２期となっているので、あえてそういうふうに分けたその辺の考え方を教えていただきたい。今年度から事業所も一定の条件に対して対象になったんですね。それから、その上の道路環境美化作業委託、これは汚れの除去ということなんですけど、もうちょっと具体的に何をどうするのか、ちょっとわからないので教えてください。","respondent":"野呂瀬環境課長、三宅都市開発課長、藤木交通安全担当課長","answer":"０件ですので、今後ＰＲ等を強化していく所存です。２点目の土壌汚染の関係についてご説明いたします。８月２２日は簡単に土壌汚染があったという程度のご報告でしたので、もう少し詳しくご説明いたします。こちらのほうは、区内に設置してあります「自転車の放置防止」ですとか、または交通安全上の「自転車はゆっくり走りましょう」ですとか。","voiceIndex":31,"id":"exchange-008"},{"speaker":"武内委員","kind":"質問","question":"わかりました。道路環境のほうはわかりました。資料は件数で載っているので、我々も件数ベースで質問しているものですから、その辺がキロワットという単位というのはどういう意味なのかちょっとわからないんですけども、その助成のやり方はわかっているんですけど。私がお聞きしたいのは、去年の実績だと６３件太陽光があって、それだけの実績があったわけですね。だったら最初から何で組まなかったのか。","respondent":"野呂瀬環境課長","answer":"平成２０年度は１０件ということでございまして、この６３件につきまして、当然どういう推移をするかという予想を立てたところですが、６０件以上になるのか、それとも５０件も行かないのか、これは非常に難しいところなんですが、それは当初予算の中で。","voiceIndex":35,"id":"exchange-009"},{"speaker":"武内委員","kind":"質問・要望","question":"わかりました。３・１１を受けて、非常にそういう気運も高まっているし、ぜひ予算立てのときにもうちょっと増やしていただきたいなと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-010"},{"speaker":"井上委員","kind":"質問・要望","question":"道路環境美化作業委託のところで、緊急雇用対策ということなんですけれども、委託先をどういうふうに考えているのかということを教えてください。","respondent":"野呂瀬環境課長、藤木交通安全担当課長","answer":"１期の件数、後ほどご説明のところでしようかと思ったんですが、１期の申請件数が１４件ありました。１４件あって、１,１２０万円支出予定、実績があるところです。道路環境美化作業委託の関係です。委託先につきましては、競争入札で今のところ民間事業者を想定しております。","voiceIndex":38,"id":"exchange-011"},{"speaker":"井上委員","kind":"確認","question":"ですから、民間の入札についてどういうふうに考え、そこをしっかりと明確にしていかなければ、ただお金が横に流れただけになりますので、それをどういうふうに考えているのかということを１点。それから、補助金に対する考え方として、２分の１という４０万円なんですけど、ほかのところの補助上限率は、すべて単費なのかということだけちょっと確認をさせてください。２点です。","respondent":"藤木交通安全担当課長、野呂瀬環境課長","answer":"ちゃんと報告も求めるようにいたします。当然東京都のほうからお金が参りますので、ちゃんとそちらのほうに報告を上げないといけませんので、それは書面ではっきりとしていきたいと考えております。補助率につきましては、ほかのエコキュート、エコジョーズ、エコウィル、エネファーム、すべて都と区で２分の１ずつの補助が出ているところです。","voiceIndex":41,"id":"exchange-012"},{"speaker":"井上委員","kind":"質問・要望","question":"もう一つ、省エネのほうで、以前にエコキュートについて環境課のほうに、このエコキュートは、設置する場所によっては隣家、隣のおうちに対して振動とか夜間の音によって睡眠妨害とかがあるということで、設置をするところさえ気をつければ別に否定をするシステムではないということで要望書を出させていただいて。","respondent":"野呂瀬環境課長","answer":"隣家とのトラブルの件ですけれども、当然申請の時点で設置者にその辺の説明をしておいて、隣家と、お隣の方とうまくやるような形で進めさせていただいているところです。","voiceIndex":44,"id":"exchange-013"},{"speaker":"井上委員","kind":"質問","question":"でも、区が税金をかけて、そこに補助をして、そういう問題を発生させたということは、道義的にやっぱりまずいというふうに思っているので、そういうふうなルールを、隣に寝室がないことを、そこまではちょっとプライバシーがあるので難しいとしても、そういうことが起こる可能性があるということは、設置者の業者は十分承知をしていることだと思うので。","respondent":"野呂瀬環境課長","answer":"後々トラブルになるよりも、事前にいろいろ説明することは当然です。騒音・振動というのは、隣の受ける方によってちょっと違うというところがあるんですけれども、当然区としてはそういうトラブルを事前に防ぐという形で説明はしていきたいと考えているところです。","voiceIndex":46,"id":"exchange-014"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"太陽光発電システム設置助成のことですけれども、区民の関心も高まっていますので、しっかりとこたえていただきたいと思うんです。もう１点、この太陽光発電システム設置ですけれども、新築の建物のみなのか、いわゆる既存の建物でもオーケーなのか、建物要件、今回中小企業にも広げましたけど、ちょっと建物要件について対象を少しご説明いただけますでしょうか。","respondent":"野呂瀬環境課長","answer":"今回につきましては、１期の伸びがこれだけ多いということで補正を組ませていただきました。当然抽選にならないような形で考えておりますし、今後もそのような形でいく考えです。２点目の要件ですけども、これは新築に限らず設置できる。助成していけるです。","voiceIndex":48,"id":"exchange-015"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"今までは予算の枠の範囲だったから当然抽選になるはずがないんですけれども、区民の関心が高まっているときに抽選にするという要綱ではなくて、しっかりと我が家でも設置したいと、そういう要望に対して積極的にこたえるように変えるべきだと思うんですよね。","respondent":"野呂瀬環境課長","answer":"抽選につきましては、今後考え方としましては、積極的に太陽光発電を進めていく観点で、考え方で進めていきたいと考えています。","voiceIndex":50,"id":"exchange-016"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"当然予算を組むときの考え方は、あらかじめ想定したものをしなければ予算を組めないわけですから。区民へのアピール、説明のところももう一工夫必要じゃないのかなと思うんですけど、その点を伺いたい。何よりも区民の関心、要望にしっかりこたえられるよう、そういう事業として考え方や、そのものを改善していく、充実していく、そういうことが大事だと思うんですけれども、改めていかがでしょうか。","respondent":"岩田都市環境事業部長、野呂瀬環境課長","answer":"先ほど申し上げましたように、いわゆる助成制度の骨組みというのは、やっぱりなかなか変えることは難しいと思いますので、来年度の新年度予算の中で。あわせて、区民への姿勢として区として積極的にアピールしていきたいと考えているところです。","voiceIndex":55,"id":"exchange-017"},{"speaker":"武内委員","kind":"質問・要望","question":"都が２,３００万円全額補助なので、これは区がどういう事業、区が積極的にこれから推進していこうという考えでそういうものを例えば、働きかけてコミュニティをつくったのか、それともそういうご要望があって、たまたまこういうふうな補助事業があるよということでいくのか、今後のモデル事業みたいな形で考えているのか、何かその辺の位置づけというんですか。","respondent":"野呂瀬環境課長","answer":"という中で、この大崎のエリアの中で、カーシェアリング事業を区が運営するんじゃなくて、今年度２,３００万円の中で運営立ち上げ資金といいますか、それを大崎のエリアの中で事業委託という形でしていただいて、実質的には今年度立ち上げますけど。","voiceIndex":58,"id":"exchange-018"},{"speaker":"武内委員","kind":"意見","question":"それと、とりあえずは大崎地域の中でということ、それで、あと推移を見ながら、区も場合によっては積極的にかかわっていくのか、その辺はまだこれからなので、区のかかわりですね、今後のこの事業の、その辺。","respondent":"岩田都市環境事業部長","answer":"ただ、こういったものが他の地区、例えば荏原とか品川地区でどこまでできるかというのは、まさに今後のまちの動き次第だろうと思います。これはかなり初期の投資と、それなりの企業が入っていませんと形ができませんので、まずは大崎でやってみようというものです。","voiceIndex":60,"id":"exchange-019"},{"speaker":"井上委員","kind":"質問","question":"３６ページの債務負担行為の説明書なんですけれども、ゼロ債で二つ項目が入っているというふうに聞いていますけど、これは早期着手する必要があるということで説明書では読み取ってくださいというものなのか、ここはすごく簡単に説明をさらっと飛ばされましたけれども、２カ年で困難であるというようなことで延長するというのはわかるんですが、その辺とこの時期をゼロ債というのは。","respondent":"武藤都市整備下水道課長、三宅都市開発課長","answer":"この整備の中身なんですけれども、現在国文学の跡地につきましては、建物の解体整備を行っておりまして、この工事が今年の夏に着手しまして、施工計画を具体的に検討したところ、来年度早期に着手すれば。こちらは国庫補助金の制度上の締めが平成２６年度ということがございまして、あとまた百反歩道橋の架替につきましては、早期整備という地元の声も聞いておりますので。","voiceIndex":62,"id":"exchange-020"},{"speaker":"井上委員","kind":"質問","question":"わかりました。表記のことなんですけれども、ゼロ債にするというところが早期着手する必要ということで、それを意味した行政用語なのでしょうか。その辺の文章のつくり方を教えてください。","respondent":"岩田都市環境事業部長","answer":"今回幾つか、今年度予算を若干執行するものがこの中には入っておりますけれども、基本的にはゼロ区債、今年度執行額はゼロで、来年４月１日には本格的な工事に着手できるように準備をするためにこういった債務負担行為をご提案しているものです。","voiceIndex":65,"id":"exchange-021"},{"speaker":"大沢委員","kind":"質問・要望","question":"創業、いわゆる事業支援になってくるから、今後予算というかお金の配分の仕方はどういうふうに変わっていくのか教えていただきたい。","respondent":"岩田都市環境事業部長","answer":"最初にまず、これはＣＯ２対策として東京都が実施している事業という形がありますので、これは款が変わっていくということはないと思います。","voiceIndex":67,"id":"exchange-022"},{"speaker":"大沢委員","kind":"質問","question":"今後この部分において、仮に環境の部分ではなくて、ここの新たに起こした事業を育てていくという部分においては、環境が優先するのか、それとも事業支援が優先されていくのかという、この事業の考え方を先ほど伺ったわけですが、もう一回ちょっとすみません、自分自身も整理をして改めて聞かせていただきますが、一応そんなところで、環境なのか事業支援なのかということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-023"}]},{"id":"topic-02","title":"「品川区水とみどりの基本計画・行動計画」のパブリックコメント実施","agenda":"「品川区水とみどりの基本計画・行動計画」のパブリックコメント実施","exchanges":[{"speaker":"井上委員","kind":"質問","question":"計画を実現する第８章のところで財政までもということになると変わってくるんですが、この「区民の夢の実現」というのは、それがまさしくパブコメになるのかもしれないんですが、これはどこから持ってきた「区民の夢の実現」なんでしょうか。","respondent":"岩田都市環境事業部長","answer":"今まで過去５年間目黒川については、立会川も含めて浄化について品川区は非常に研究と実験を繰り返してまいりました。一定の成果がありまして、目黒川についてはある浄化方法をとれば非常にきれいな川に復活できる。","voiceIndex":91,"id":"exchange-024"},{"speaker":"井上委員","kind":"質問","question":"ですから、そういう過去に調査をして、区民もこの夢を持っているのか、発想的に行政が過去にこういうことがあったからこうだああだというものなのか、そこは進める上で一体感が必要と思うんですが、そういうことが過去にあったのか、ないのであれば、そういうことも含めてある程度意見聴取をした上での目標というものが必要だと思うんですけど、その辺はいかがでしょうか。","respondent":"藤田水とみどりの課長","answer":"その辺をこれから先ほど委員からもお話がありましたとおり、まさにパブリックコメントの中で皆さんの意見をお聞きしていきたいというふうに考えてあります。","voiceIndex":93,"id":"exchange-025"},{"speaker":"井上委員","kind":"質問・要望","question":"東京湾を泳げる海に変えたいという我々の政策もあるので否定はしないんですけれども、そこはたくさんの人の声が上がるような仕組みというものがあっての計画だと思うので、その辺は何らかの手当と工夫をしていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-026"},{"speaker":"武内委員","kind":"質問","question":"今の関連なんですけど、部長のほうから財源さえあればみたいな話をいただいたんですけれども、例えばちょっと、どこまでお話しいただけるかわからないですけど、その手法というんですかね、今までは難しいと言われていた中で、そういうものはどんな感じなのかというのと、あと財源で言えば、品川だけでなくて目黒区、世田谷区、東京都、いろいろあるわけですけれども。","respondent":"岩田都市環境事業部長","answer":"置換してしまいますので、この方法であれば、お金はかかりますけれども、本当に目黒川の夢が現実のものとなり得るというふうに今回説明をすることになろうかと思います。","voiceIndex":96,"id":"exchange-027"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"ちょっとこの計画について少し伺いたいんですけれども、まず緑被率でなく、みどり率にした理由は何かということを伺いたいのと、それとこのみどり率、現状は２１％ということですけれども、２３％、将来目標の２５％にするには何ヘクタールぐらい、どのぐらいの広さのものが必要なのか、ちょっとイメージが持てなかったので、どれぐらいの広さが必要なのか伺いたいと思います。","respondent":"藤田水とみどりの課長","answer":"これを将来２５％のときには、全体で５８６.１ha、そのうち水面については面積が変わりませんので９１haということで、その差し引きがみどりの部分あるいは公園になっているけれども、みどりで覆われていない部分ということで考えますと。","voiceIndex":99,"id":"exchange-028"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"これをどう進めていくのかという点での目標値や考え方というものがあるのか、先ほど言った８９haにグリーンカーテンの部分は入っているのかいないのか、そこの考え方を改めて伺いたいと思います。あわせて、このパブリックコメントについて何件ぐらいのご意見をお寄せいただきたいというのを目指しているのか、そこも伺いたい。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"壁面緑化等の考え方ですけれども、みどりのカーテン、夏場に言われるみどりのカーテンと言われているものは、基本的には夏の暑さを少しでもやわらかくするための対策でございまして。定点で何百カ所、どこかの区はやっているんですけど、定点で毎年写真を撮って、その写真に写っているみどりのボリュームの量をずっと毎年計算しているんですけど、あまり、それが何なんだろうということで。","voiceIndex":101,"id":"exchange-029"}]},{"id":"topic-03","title":"省エネルギー設備導入助成・太陽光発電システム等設置助成第二期追加募集","agenda":"省エネルギー設備導入助成・太陽光発電システム等設置助成第二期追加募集","exchanges":[{"speaker":"中塚副委員長","kind":"質問","question":"太陽光発電システムの普及をしたいということで、要するに普及をするためには今課題になっているものというのをどう考えていらっしゃるのか、今回、中小企業へと対象を広めたというのも普及をするための一つの方法だとは思うんですけども、太陽光パネル設置を進めるための、普及のための課題とは何か、技術的にも、また区民へのアピールにもいろいろ乗り越えていくものは何なのか。","respondent":"野呂瀬環境課長","answer":"それと２点目の対象を広げる、枠を広げるということも、あわせて今後検討していきたいと考えているところです。","voiceIndex":109,"id":"exchange-030"},{"speaker":"中塚副委員長","kind":"質問","question":"なので、課題についてどういうふうに研究されているのか伺いたいと思います。基本的にやっぱり補助の増額、対象の拡大、区民が太陽光パネルをつけたいという、その思いにどうやったらこたえられるのか、そこをしっかりと踏まえていかないと、今後の普及の方向、方策が見えてこないと思うんですけども、そこはどんなふうに現状ご研究されているんでしょうか。","respondent":"野呂瀬環境課長","answer":"もう一つは、メーカーの今後の普及というか技術革新も進んできて、今太陽光発電のパネル設置が高いのがもう少し下がってくる、いろいろそういう面も今後の普及については、そういうものが進んでくれば、ＰＲももちろんやりますけれども、今後の課題について。","voiceIndex":111,"id":"exchange-031"},{"speaker":"中塚副委員長","kind":"質問","question":"例えば、既存の建物につけようと思うと、まず重いですから、建物がどうかというのがあると思います。分譲ですから、そういう意味では、建物は１個かもしれないけど、住民としてはたくさんいるわけで、なぜ同じ金額なのか、いろんな普及するに当たって、課題をしっかり明確にしていくことが今後の普及に必要な対策につながってくると思うんですよね。なので、改めて普及に当たって何が課題なのか。","respondent":"野呂瀬環境課長","answer":"いろいろな課題があると思いますけれども、今後のＰＲを普及するためには、太陽光発電の今後の研究等もとらえながらＰＲをしていく考えです。","voiceIndex":113,"id":"exchange-032"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"改めて課題を明確にして、必要な補助額の増額、対象の拡大をしっかりと進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-033"}]},{"id":"topic-04","title":"地域が主導するＥＶカーシェアリング事業","agenda":"地域が主導するＥＶカーシェアリング事業","exchanges":[{"speaker":"井上委員","kind":"質問","question":"これは、単年度の設立の経費として都の助成ということで、区のこの事業に対するかかわりというものが、基本的にはこの立ち上げで次年度から事業者の独立した事業というふうに認識をしているので、カラー刷りのほうの２ページ目のところで、区への報告書作成・提出というのは、今年度２,３００万円の補助金に対して、こういった手続があるもので、区のこの事業へのかかわりが、どういうもので。","respondent":"野呂瀬環境課長","answer":"当然のごとく、先ほど申しましたとおり、大崎のエリアをこういう形で進めていくということでございまして、区が何らかの形、例えばですけれども、区がプレミア会員になるのかならないのかも含めて今後詳細を詰めていくです。","voiceIndex":121,"id":"exchange-034"},{"speaker":"井上委員","kind":"提案","question":"基本的に助成をするということで、提案が事業者と区を通してということだから、こういう形になると思うんですけど、品川区が委託という、ここの委託の意味がよくわからないんですけど、なぜここで区がこれを委託するのか、そこが整理できないんですけど、どういう仕組みですか。","respondent":"野呂瀬環境課長、岩田都市環境事業部長","answer":"追加しますけども、対象が区に対しての補助ですので、補助につきましては、区を通して当該の「大崎エリアマネージメント」に委託するというものです。補助制度は、例えば国とか東京都が直接民間事業者に対して補助をする、これは直接補助と言っているんですけど、今回の東京都の仕組みは、あくまで間接補助で、中に品川区が事業主体として、今回の事業主体というのは。","voiceIndex":123,"id":"exchange-035"},{"speaker":"井上委員","kind":"質問","question":"ということは、来年以降、この委託というものはなくなって、基本的にはそういう考え方のもと、進むべきというふうに私は思っているので、そういうふうな認識でよろしいのでしょうか。","respondent":"岩田都市環境事業部長","answer":"ただ、品川区が全くかかわらないかといったら、そうでもなくて、この事業主体となります「大崎エリアマネージメント」、ここの監事に片田防災まちづくり事業部長が名を連ねておりますので、常にここの状況については区のほうにわかるようになっております。","voiceIndex":126,"id":"exchange-036"},{"speaker":"中塚副委員長","kind":"意見","question":"実は、ちょっとさっき聞こうと思っていたんですが、要するに品川区と「大崎エリアマネージメント」という一般社団法人との関係がよくわからなくて、以前に中間法人を立ち上げるときに、若干説明があったとは思うんですけども、改めてどういう関係にあるのか、なぜ片田防災まちづくり事業部長が監事に入っているのか。","respondent":"三宅都市開発課長","answer":"その中の戦略５というところで、継続的に発展するための体制をつくるという項目があります。その中で、まちづくりを継続的に地元主体でやっていくための組織ということで、エリアマネージメントというものを発足させようということをうたっております。","voiceIndex":128,"id":"exchange-037"},{"speaker":"中塚副委員長","kind":"質問","question":"品川区が監事として参加をしている理由は何なのか。今回、区が入っていながらも、そこに委託料として間接補助ですから出すわけですよね。住民から見ればいただいたんだという構図になるわけですね。そこをご説明いただけますか。","respondent":"三宅都市開発課長、岩田都市環境事業部長","answer":"そちらが主体でこういうエリアマネージメントをつくったというところから、エリアマネージメントの監事という形でまちづくり連絡会の構成と同じように、区のほうも監事という形でかかわってきているです。これから本格的なソフト、ハードを含めた活動を展開していくところなので、今後区はどういう形でここに支援をしていくかというのは、これから仕組みをきちっとつくって、議会にもご説明を申し上げたいと思います。","voiceIndex":130,"id":"exchange-038"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"要するに現職の区の職員がそこに入っているわけですよね。そこに区の補助金が入っているわけですよね。えっ、何でというのが、やっぱりそこに見えてくるんですよね。だから、その経過の中で、まちづくりの中でそう位置づけたという話ですけど、品川区自身がやらずに、そこをあえてつくった理由というのは一体何なのか、そこをご説明いただきたい。","respondent":"三宅都市開発課長、岩田都市環境事業部長、片田防災まちづくり事業部長","answer":"先ほど申し上げましたように、こちらの地域の継続的な発展は、地元主体でやっていただきたいということで地元主体の組織にしておりまして。ちょっと説明が足りないんですけど、この会社は一般社団法人でありながら、約款でいろんな事業を展開できるんですけど、収益が上がっても。大崎の西口駐輪場等々についても、区が委託をお願いしているという経過もありますし、やはりお金の流れを含めて。","voiceIndex":133,"id":"exchange-039"}]},{"id":"topic-05","title":"リニア中央新幹線の環境影響評価（方法書）","agenda":"リニア中央新幹線の環境影響評価（方法書）","exchanges":[{"speaker":"井上委員","kind":"意見","question":"表記のことでわからないので、スケジュール、経緯のところで、一番最後に、工事完成予定というのと、工事計画完成予定とか、そういう感じで、工事計画・着工で、平成２７年から着工して、平成３９年に完成予定ということなのか。","respondent":"野呂瀬環境課長","answer":"すみません。ちょっと図がくっついているように見えるんですけど、実際、平成２７年から工事を始めて、大体１２年かけてということで、平成３９年に竣工です。","voiceIndex":143,"id":"exchange-040"},{"speaker":"井上委員","kind":"質問","question":"方法書についての説明、住民説明会とかというのは、いつもだと環境アセスに対する意見とか閲覧とかというイメージがあるんですが、２番目の方法書というのはどういうものなのかということと、あと住民説明会、方法書の住民説明会というのは、いつごろ予定されていて、それの周知はまた区が行うのかどうかというところを教えてください。","respondent":"野呂瀬環境課長","answer":"説明会につきましては、以前の法律ですと準備書の後に義務づけられていたんですが、今回法改正で方法書の後に説明会を開催するというのが義務づけられたです。日にちにつきましては、現在まだＪＲのほうから聞いておりません。","voiceIndex":145,"id":"exchange-041"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"リニア中央新幹線の計画に対して、区はどういうご意見をお持ちなのか伺いたいと思うんですけれども、方法書に対するコメントの説明がありましたけれども、中身をもう少しご説明いただきたいのと、この計画そのものについて、区はどういうふうに考えている、見ているのか、区の姿勢を伺いたいと思います。","respondent":"野呂瀬環境課長、松代都市計画課長","answer":"それと震災の前と後につきましては、ＪＲ東海のほうはそのまま計画を進めているというところでございまして、特段区のほうとして、それに対してコメントする立場ではございません。基本的には今回の環境影響評価をするということで、東京都とともに説明を受けたというのが初めてです。それ以外はホームページ等々で知り得る情報ということでご理解をいただきたいと思います。","voiceIndex":149,"id":"exchange-042"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"予算特別委員会だか決算特別委員会だかわかりませんけれども、以前から濱野区長のほうからも出発駅がどこなのかと、まだはっきりしていないけどというようなコメントがありましたので、改めてこの計画そのものについて、どういうふうにお考えなのか伺いたいと思います。最近の５月１２日の３回目では７３％が中止・見直しを求めていると。どういう関係にあるのか、よくわからないんですね。","respondent":"松代都市計画課長","answer":"先ほどご答弁したとおり、今ご質問にお答えできるような情報は持ち得ておりませんが、まず事業費の件に関しましては、先ほど申し上げましたように、ＪＲ東海の自己負担ということで進められております。そういったことでご理解をいただければと思います。","voiceIndex":152,"id":"exchange-043"},{"speaker":"中塚副委員長","kind":"質問","question":"最後に伺いたいのは、１時間で結ばれるというお話がありましたけれども、例えば震災対策はこのリニアに対してどうなのか、二つの断層そのものを地下で突き抜けるわけですよね。なので、計画そのものについて、今国際化という話がありましたけども、何よりも乗客の安全、また必要性をしっかりと見ていく必要があるんじゃないかと思うんですけども、最後の件についてはいかがでしょうか。","respondent":"松代都市計画課長","answer":"構造等、大深度地下、４０ｍということで計画が示されております。それの地震等への耐震、そういった安全性というのは具体的なものが示されておりませんのでなかなかコメントはできない状況です。","voiceIndex":154,"id":"exchange-044"}]},{"id":"topic-06","title":"二葉４丁目区有地不法占拠の適正化","agenda":"二葉４丁目区有地不法占拠の適正化","exchanges":[{"speaker":"武内委員","kind":"質問","question":"そうすると、六十五、六年にわたってということで、自分はあまり知らなかったんですが、それまで何回か、区が管理するようになってからのことなんですけど、何回も交渉してきたという中で、今まではだめだったんですかね。それまでの間に、もうちょっと方法的な部分で何か対応するということも検討されたのか。","respondent":"井浦土木管理課長","answer":"本件につきましては、昭和２０年４月に占拠が開始されまして、昭和２４年から当時立ち退きの交渉ということで行政機関が対応しております。","voiceIndex":161,"id":"exchange-045"},{"speaker":"武内委員","kind":"質問","question":"わかりました。地域の方からの苦情ですとか、何かそういう、どうなっているんだみたいなのが結構あったんですか。","respondent":"井浦土木管理課長","answer":"地域からの問い合わせ等も、記録によるとやはり数件ございました。現在記録に残っているものですね。","voiceIndex":163,"id":"exchange-046"},{"speaker":"武内委員","kind":"質問","question":"こういった不法占拠みたいなところが、品川区内に、ほかにも何カ所かあるんですか。今わかっている範囲で。","respondent":"井浦土木管理課長、岩田都市環境事業部長","answer":"このように全面的な不法占拠というケースについては、ほかにはつかんでおりません。ただ、法定外公共物、いわゆる公共溝渠について、宅地の一部に数平米囲い込んでいるというケースについては把握しています。これは品川浦という北品川に位置しているところなんですが、船宿がずっとあるところなんですけれども、ここを、これも戦後から何年かかけて勝手に埋めて、そこに居住用の住宅を建てて営業しているというケースが１件ありますけれども。","voiceIndex":165,"id":"exchange-047"},{"speaker":"井上委員","kind":"質問","question":"少し今の質問と関連するんですけれども、公営住宅を希望していて、それがかなわなかったということなんですが、今回従前居住者用住宅をあっせんしたというのであれば、もう少し早い段階でそういうことができたんではないかと思うんですけれども、そこの判断と、今後の対応で、建物の解体と整地ということを、これは全額区の負担で行うということだと思うんですけれども。","respondent":"岩田都市環境事業部長","answer":"このペーパーにも書いてありますけれども、この方は戦後の大空襲で焼け出されて、十数件こういった方が当時、昭和２０年代にはいらっしゃったそうです。","voiceIndex":168,"id":"exchange-048"},{"speaker":"井上委員","kind":"質問","question":"今の話を伺っていて、すごく困難な方はたくさんいるんじゃないかというふうに思う中で、何となく、個人的にこの方を知りませんからどういうことというのはないんですけれども、何となく今のお話だと、もっと適切な対処はすべきであるだろうと、ほかの住宅とかそういうところでも、いろいろ個別に対応しているんですけど、その辺がちょっと納得できないような。","respondent":"岩田都市環境事業部長","answer":"それで、解体費用については債権ですから、当然その人の収入から強制的に徴収するということを行うわけですけど、今回の方の事情は、債権をとるに至れない、こういうことですから、債権放棄もやむなしということで、この方からお金の徴収することはできないです。","voiceIndex":170,"id":"exchange-049"},{"speaker":"松澤委員","kind":"質問","question":"二葉４丁目は本当に防災危険区域ですから、小さな公園でもよかったなと思います。一般論で、戦争で焼け出されてと、戦時特例法で借地権が認められたなんていう話もあるんですけど、こういう場合は河川敷だからそういうのはなかったということなんですか、その辺はどうなんでしょうか。","respondent":"井浦土木管理課長","answer":"この土地については、もともと公共溝渠と、いわゆる河川敷の土手の部分ですので、国有財産法で国有財産という位置づけですので、私の権利は発生する余地がないというふうに認識しております。","voiceIndex":172,"id":"exchange-050"},{"speaker":"大沢委員","kind":"質問","question":"「今般立退き交渉が成立し」と書いてあるけど、立退きの交渉を始めたのはいつですか。","respondent":"井浦土木管理課長","answer":"記録によりますと、昭和２４年から立退きの交渉を行っております。","voiceIndex":174,"id":"exchange-051"},{"speaker":"大沢委員","kind":"質問","question":"そうすると、平成１５年から区有財産で、それ以前は国有財産ということですから、国と区で、おのおの分かれながら段階を経て交渉したということですか。途中で変わってくるんですね。","respondent":"井浦土木管理課長","answer":"平成１５年まで国有財産でありますが、管理権につきましては、東京都が昭和３６年まで国から委任されておりまして、東京都の管理下にございました。昭和３６年以降は、品川区に管理権が移管されておりますので、品川区として立退きの交渉を続けていたという経緯です。","voiceIndex":176,"id":"exchange-052"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"もともと土手というか、暗渠だったということもあって、ちょっと見通しが悪くて、どうしても空き缶とかも含めたいろんなごみがたまっていってしまったり、あと薄暗かったり、そういうのがあって、長い間この問題を抱えていましたら、全体としてどうしてもいじくりようがないという部分もあったと思うんですけども、今回を機に近隣の方々の意向も含めて見通しがよく、段差も解消されるような。","respondent":"稲田道路公園課長","answer":"来年度は解体してみないと、今家が目いっぱい建っておりまして、高さの関係とか、そういうふうなところが見えませんので、まず測量等を実施しまして、来年度の整備につきましては、その後検討していきたいというふうに考えております。","voiceIndex":178,"id":"exchange-053"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"来年度の整備の中で、よく近隣の方々のご意見を伺っていただいて、長い間ここにあったことはご近所の方はよく知っていて、一定経過も知っているだけに、やっと今回こういう形で、いわば解決というのであれば、そういう新たな公園整備について住民要望も反映していただきたいなとお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":180,"id":"exchange-054"}]},{"id":"topic-07","title":"街路灯・公園灯の全面復旧","agenda":"街路灯・公園灯の全面復旧","exchanges":[{"speaker":"井上委員","kind":"意見","question":"夜間の消灯が限度を超えたものではないかという疑問が結果的に残るというところからなんですけれども、消費電力の削減に効果的だったのかどうか、以前に公園のところで２３区の消灯率ということをお話しいただいたんですが、振り返ってみて、今後の対策に影響すると思いますが、今回の消灯のことについて、評価をどのようにしていらっしゃいますか。","respondent":"岩田都市環境事業部長","answer":"前にも当委員会でお答えいたしましたけれども、我々が消灯するときに一番心配したのは、やっぱり防犯の問題なんですね。","voiceIndex":185,"id":"exchange-055"},{"speaker":"井上委員","kind":"質問・要望","question":"ですから、苦情がなかったことをよかったとするというのは、一方で、そういう施策に対して無関心であるという区民の姿勢であるかもしれないということで、苦情がなかったこと、イコール、いいことということは一概に言えないというところがあって、今回消費電力削減に向けて、夜間電力を削減したことで、区が１５％を求められたところを、それを上乗せした計算で。","respondent":"岩田都市環境事業部長","answer":"とりあえず、今回については、区の節電対策本部で区の全施設については、従来どおりに戻すという決定方針に基づいて我々も行ったわけですけれども、この冬、おそらく来年の１月から３月にかけて、第２の節電の山が来ると思いますので、そのときまでに私どもとして。","voiceIndex":187,"id":"exchange-056"},{"speaker":"井上委員","kind":"質問・要望","question":"結果的に３０％の節電に対して、これがどのぐらい上乗せのデータになったのかというのがちょっと答弁漏れなので、それをお知らせいただきたいことと、あと１点、苦情という形で直接は言っていなくても、やはり駅のエレベーターとか、区の話ではなく、全体的なもので、視覚障害者の方たちにとっての事故というのが実際にあったというふうに伺っているんですが。","respondent":"岩田都市環境事業部長","answer":"大崎の夢さん橋のエレベーターについては、同じ出口に２カ所エレベーターがついておりますので、障害者の方や利用者が一番便利なほうの１基を残して、不要な１基をとめたです。","voiceIndex":189,"id":"exchange-057"},{"speaker":"井上委員","kind":"質問・要望","question":"エレベーターのところなんですが、不要なエレベーターという表現は、やっぱりそこを利用している人がいるかと思うので、どちらか一つをとめたということは、普通の健常者だとポンポンと行けるかもしれないですけど、いろいろなルートで来ている方たちもいる中で、やはり今後こういったものを考えるときには、ちょっと慎重に考えていくということをぜひ課題にしていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":191,"id":"exchange-058"},{"speaker":"武内委員","kind":"質問","question":"今回いろいろな問題で、どうしても一つ一つ街路灯にしてもやらなければいけないというお話を何度もいただいて、大変だなと思うわけです。そういう１本１本やらなくて済むようなものというのはないんでしょうか。あるけれども、今すぐ、もちろん予算をかけてとか、いろんな関係で当分できないとか、それとも技術的にはできないというのはわかりますか。","respondent":"岩田都市環境事業部長","answer":"街路灯も公園灯も基本的には同じなんですけれども、都道とか国道の場合は、地中化をしておりまして、どこかの分電盤１基に対して１０基ぐらいがつながっていますので、その分電盤のブレーカーを落とせば、一斉に消すことが可能なんですけれども、区道の場合は。","voiceIndex":192,"id":"exchange-059"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"今回、大震災を機に起きたことですから、そういう意味では今までの対策とはある意味チャンネルが変わったわけですよね。この前の台風を受けて感じたんですけれども、そういう節電、省エネ社会に向けた対策と、あと街路灯についても、新しい仕組みというのを考える、そういう時期に来ているんじゃないかと思うんですけども、いかがでしょうか。","respondent":"岩田都市環境事業部長","answer":"それと、そういう検討委員会を立ち上げるべきだということですけれども、今節電対策本部というのは、まだ一応休止になっておりますけれども、何かあればまた復活して全庁的な対策をとってまいりますけれども、これとは別に今回執務室の電気。","voiceIndex":194,"id":"exchange-060"},{"speaker":"井上委員","kind":"質問・要望","question":"防災にかかわる部分で、伊藤議員の品川区の防災対策についてというところと、鈴木ひろ子議員の障害者・患者・高齢者の災害時支援計画の策定をという質問の中で、要援護者に対する支援の仕方というのが、ちょっとはっきりしていませんでしたので要援護者に対する考え方、要綱をつくられて、その中で規定された要援護者の方がいるということがありましたので。","respondent":"松代都市計画課長","answer":"要援護者に対する支援のあり方の考え方、要綱等準備して、明日お配りしたいと思います。","voiceIndex":199,"id":"exchange-061"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"私からは、本多委員の副都心大崎の発展と品川区の発展についてという質問の中で、この間の大崎の３０年のまちづくりの課題について、今年度総括をしていきたいという答弁がありましたけれども、この総括についてどういうメンバーで、どういう中身で、またどういうテーマで評価をしていくのかというところを伺いたいと思います。その２点です。","respondent":"松代都市計画課長","answer":"総括のメンバー、その中身とか内容とか、その評価。それとあと、６０haに及ぶ開発の中のマスタープランの中での再構築、その再構築というものの内容、今後どのような方法か、範囲、そういったものの質問というふうに伺いましたが、よろしいでしょうか。","voiceIndex":202,"id":"exchange-062"},{"speaker":"武内委員","kind":"意見","question":"ケーブルテレビのＬ字放送で、ずっと出ていたんですけれども、９時半、１０時ちょっと前ぐらいに自宅に帰って見たらば、その段階では消えていたんですよね、Ｌ字が。それまでは目黒川とか立会川の水位について出ていたんですけれども、それは区のほうで、例えばもういいからということで、９月２１日の台風当日ですね。夜の９時半過ぎに私が戻ったときに見ていたんですよ。そうしたら、消えちゃったんですね。","respondent":"岩田都市環境事業部長","answer":"区は水防態勢で引き続いてやったんですが、雨の心配は９時の段階で全くないということが判明したので、本部そのものも９時半に縮小しております。この時点でもってケーブルテレビに対して解除ということを本部からの指示でやらせております。","voiceIndex":208,"id":"exchange-063"},{"speaker":"中塚副委員長","kind":"質問","question":"今回の台風１５号の被害状況についでですけれども、まず、倒木が６５件ということで、随分と木が倒れたなと思うんですけれども、このことについてどうお考えなのか、今後の必要な対策などはどのように考えているのか、そこを伺いたいと思います。倒木についてはある意味区の木というんですかね、ですから報告が上がってきているんでしょうけれども、今回非常に風が強かったんですよね。","respondent":"稲田道路公園課長、中山防災課長、松代都市計画課長","answer":"公園樹木につきましては、今年度樹木医による診断を実施している最中です。帰宅困難者の対応ですけれども、私どもその４カ所を決めるときに、近隣区にどうされますかと伺ったんですね。それと、帰宅困難者につきましても、大井町を中心として主要駅を巡回等しまして、状況等を刻々と本部のほうに報告をして、その対応を判断するです。","voiceIndex":211,"id":"exchange-064"},{"speaker":"中塚副委員長","kind":"質問","question":"これは直接体験したんじゃないんですけど、例えば八潮に渡る橋、いろんな橋がありますけども、そこをバイクで通ろうとしたときに猛烈に強い風が吹いていて、そういうところにもアナウンスがなかったという話を伺うので、警察と区といろいろ役割はありますけれども、今回強い風がどこを吹いたのか、つかんだ上でそういう警戒の呼びかけが必要だと思うんですけど、これはいかがかということが１点です。","respondent":"片田防災まちづくり事業部長","answer":"ただ、それがほかの新聞報道と若干時間的な、早目に引き上げたといいましょうか、消えてしまったというところはありますけれども、それはまず区民の方にきちっと現状を把握していただくということで一応対応したものですので、いろいろと今後の課題があるとすれば。","voiceIndex":215,"id":"exchange-065"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"風については、やはり全体が強い風が吹いているのは知っていますけれども、やっぱり部分的に、例えば倉庫が倒れたり、バイクが転倒したり、自転車なんてとても乗っている状況じゃない。帰宅困難の問題も、やっぱり適宜情報のアナウンスについては、よりわかりやすく適切に工夫をしていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":217,"id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4016#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":61629,"voices":219}},{"id":"h23-20110926-9","meetingId":"h23-cm09","date":"2011年9月26日","dateIso":"2011-09-26","committee":"文教委員会","time":"午前１０時００分～午後２時４６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の第４９号議案、品川区奨学金貸付条例の一部を改正する条例","agenda":"の第４９号議案、品川区奨学金貸付条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"今回、入学準備金が保護者に変わったということで、なぜ本人から保護者に変わったのかというところをまずお伺いします。","respondent":"小林青少年育成課長","answer":"あわせて、私どもの認識は、多少、昭和３０年代、４０年代と現在においては、状況の変化もあろうかと思います。","voiceIndex":13,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ここのところが、いろいろ今お話しありましたけれども、親に変わるということは、子どもが借りるということは、学校を出て出世払いというか、仕事をした、収入があったときに返しなさいというところが、今、親の状況から見ても、今、子どもの就職が難しい、親御さんもかなりリストラとか賃下げとかで生活困難になっている中で、これが親の負担になるということは。","respondent":"小林青少年育成課長","answer":"しかしながら、今までも東京都の制度を利用する人と、区の制度を利用する人と、いろいろな多面的に制度を利用していただくことも環境の整備の一助だったという考え方もあり１つの制度を継続してきたわけですが、この間の環境変化をもとにして。","voiceIndex":15,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"返還期間のところですけれども、現行は貸付終了・据置期間終了後ということですから、貸付終了３年間の在学中と据え置き期間が１年で、その後１５年ということが、在学中３年に大幅に短縮になるわけですよね。これだけではないですよね。ですので、ちょっとこれは大きな意味で後退、改悪であるなと思っています。","respondent":"小林青少年育成課長","answer":"そういったときに、ただ、この制度はそれに該当していませんのでと言ってしまうのも１つかもしれないんですけれども、身近な区としてその痛みに寄り添うということからしたときに、だったらこういう形でとりあえずつなぎで区のほうでやって、勉強を続けて。","voiceIndex":17,"id":"exchange-003"},{"speaker":"須藤委員","kind":"意見","question":"この改正案については、まとめて十分やってきたことと思っています。それで、１つは、今まで奨学金というのがどの程度きちんと返されているのかなと。その保護者に全部貸すよという形になっているのかというような思いが１つあります。それからもう１つは、外国人に対しての場合にはどういうふうになっているのかなというような思いがあります。","respondent":"小林青少年育成課長","answer":"その結果、都の制度との関係も含めまして、区の利用者数もかなり減ってきております。その辺を考え合わせて、今回、制度調整を１年おくれで対応するところと考えたところです。","voiceIndex":19,"id":"exchange-004"},{"speaker":"須藤委員","kind":"質問・要望","question":"今、いみじくも課長のほうから言われて、未納者がかなりいるよということなので、そのことに対してもう少し何らかのアプローチを考えていかなければいけないだろうというようなお話もいただきました。我々としても、税のときにはいろいろ担当があって、徴収に回ったりきめ細やかにご案内したりという形になります。このことも了としますし、そういったこともお考えいただきたいというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-005"},{"speaker":"阿久津委員","kind":"質問・要望","question":"ご説明ありがとうございました。何点か教えてください。もう１つが、先ほど須藤委員のほうからもお話しありましたが、高校無償化の間は減額調整すると書いてあるんですけれども、それは条例の中には明記されているのでしょうか。パッと目を通した中では見つけられなかった、私が見過ごしているかもしれないんですけれども、それが１つ。","respondent":"小林青少年育成課長","answer":"それと、条例の規定の問題ですけれども、条例では金額の限度額が規定されており、規則で奨学金の金額を規定する予定です。","voiceIndex":22,"id":"exchange-006"},{"speaker":"阿久津委員","kind":"質問","question":"高校無償化の件で、付則のほうに記載があるということでしたけれども、今ちょっと初めて伺って納得いたしましたが、条例案ですと、やはり限度額が書いてあるということで、先ほどもおっしゃっていましたけれども、どうにもならないという方がいらっしゃった場合、この２万８,０００円をあてにされていらっしゃる方も来るかもしれない、ご説明はあるとは思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-007"},{"speaker":"吉田委員","kind":"質問","question":"貸付方法なんですが、年９回を年４回になさったという理由をお伺いしたいんです。","respondent":"小林青少年育成課長","answer":"学校への支払いが学校によってみんなばらばらなものですから、半期払いのところも、学期ごとの払いのところもあるものですから、基本的にはすべて前払いしていくということで、支払いを４、５、６を４月、７、８、９を７月、それから１０、１１、１２を９月、１、２。","voiceIndex":25,"id":"exchange-008"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。やはりどうしてもお借りしなければいけないということで前払いを、それが気になって、ご自分で負担しなければならなくて、後からお借りできるのではちょっとあれかなと思った、そこをちょっとお聞きしたかったので、払う前にお借りできればということでした。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-009"},{"speaker":"渡部委員","kind":"質問","question":"２点お伺いします。新旧対照表の第１条の「経済的理由により修学困難な者およびその保護者に対し」ということで、今度新たになるので、あくまでも在学資金というのをお貸しする相手方というのは、「者および」という言葉遣いになっていて、これが僕は逆に非常にあいまいだなという感じがしてしまったんですけれども、要は、保護者に貸すんですか、本人に貸すんですかというのがどうなのかな。","respondent":"小林青少年育成課長","answer":"したがいまして、奨学金の内容が２つあるので、「困難な者」というのは本人ですけれども、「およびその保護者」ということで、本人は在学資金、保護者は入学準備金という対応の中での区別とご理解ください。","voiceIndex":28,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"反対します。授業料が、教育費もとてもかかる日本の中で、１５歳、高校、高専とか、あと専修学校ですか、親の経済的な理由で進学をあきらめることがない、本当に命綱である奨学金の制度であると思っています。共産党はこの間、貸付ではなくて給付型のほうにしてほしいと求めているところですが、今回のこの条例改正は、より借りにくくなる制度の後退であるという受けとめをしていますので反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-011"}]},{"id":"topic-02","title":"の第４６号議案、平成２３年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"の第４６号議案、平成２３年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"ご説明いただきました。児童福祉費の中で、今回、私立認可保育園、定員予定３７８名、また相当頑張って待機児童の解消に努めていただけるということは非常にありがたいことだと思います。実際のところ、今まで私立認可保育園、時間がたって株式会社等で運営しているという問題点は何か生じているのかどうか。品川区外において保育事業を何か経験されてきているのか。その辺をお聞かせいただけますでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"１つには、実施計画のほうで、２園、３園、３園ということで予定しておりますが、定員につきまして、１００人規模をまず想定しておりましたので、それと比較して、今回は小規模の園ということがございましたので、園が増えているということが１点あります。","voiceIndex":46,"id":"exchange-012"},{"speaker":"渡部委員","kind":"質問","question":"ありがとうございました。今伺いました新しい会社も結構いろいろなところで経営されているんだなということで、そういった意味では安心感があります。この先、今、子どもは増えていて、たしか０歳児は３,０００人ぐらいですか、どんどん増えてきていますけれども、この先、本当にどうなるかわからない。しかしながら、やはりやっていくことはやっていかなければいけない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"意見","question":"２５ページの奨学金のところなんですけれども、先ほど、条例で反対したんですけれども、内容的に中身を変えないで、国の対応に変えていくシステムの改正というのは、国の制度に対応して今までどおりの内容で、国の制度に対応した部分に変えていくというのが可能なのかどうかというのがちょっとわからない。","respondent":"小林青少年育成課長","answer":"今回予定しております改修の内容ですけれども、さきにご説明させていただきました金額の部分と、それから支払いの納期の部分と、それから一番大きいのが入学準備金の部分の３つです。","voiceIndex":49,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"意見","question":"今の最後のところ、どういうときに改修が必要なのか。","respondent":"小林青少年育成課長","answer":"親に入学準備金を貸し付けないというふうに将来また変わったというふうになれば、それはまた修正を行わなければならない。いわゆるどちらにもできるようにシステムを維持するということにはなっておりません。","voiceIndex":51,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"開設前家賃補助と開設後家賃補助の考え方を大もとのところを聞かせていただきたいのと、あと、区独自の後家賃のところの補助要綱も、まだこれからつくると聞いているんですが、基準となる金額がどういう基準で出していくのか、期間的にどのくらい出していくのかというあたりをまずお伺いします。","respondent":"伊崎待機児童対策担当課長","answer":"２点目の株式会社であることによる資金の使い道についてのご質問ですが、こちらは国の規定でもあります保育所の運営経費として補助されるものにつきましては、用途に規制がかかっておりますので、例えば補助金を保育事業以外の株式会社の事業に投入するとか。","voiceIndex":53,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問","question":"具体的に総額は書いてあるんですけれども、各園ごとの前家賃とか、改修費とか、個別に出ますか。前家賃、金額も出してから何カ月というか、具体的に決まっているところがあったら教えてほしいんですけれども。働く人の条件のところに影響が出るかと思うんですけれども、その辺についてのお考えを聞かせてください。","respondent":"伊崎待機児童対策担当課長","answer":"企業会計に関する規則ですけれども、認可の条件といたしまして、企業会計、きちっと保育所に関する収入支出と企業の別事業とそれぞれ分けて計算、年間収支、資金収支計算分析表等をつくるように等々、非常に細かく定めがありますので。","voiceIndex":55,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"提案","question":"この間、世田谷区は、株式会社参入をここのところずっととめているんですね。社会福祉法人立で行っているというところを頑張っているのが世田谷なんですけれども、ぜひそういった方向を求めてほしいなと思うんですが、その点はいかがでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"民立民営の保育園につきましては、区といたしましては、運営主体の区別なくきちっと保育の姿勢については指導助言等々を行ってまいっておりますし、これからもそのような姿勢で対応してまいります。","voiceIndex":57,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今回この予算に対しては、反対はしないというか、今後も勉強させていただきたいなと思っています。短期間であっても臨時の職員の方が入ってやっていけるのかどうか、その辺については、このような事態は本当に極力起こらないようにしていただきたいなと思っていますが、いかがでしょうか。","respondent":"冠木指導課長","answer":"今回そういったところで、複数の方が産休・育休をとられるということで対応していますので、その辺は十分に人選を行って学校の業務に差し支えないように対応してまいりたいというふうに思っております。","voiceIndex":59,"id":"exchange-019"},{"speaker":"須藤委員","kind":"質問","question":"２８ページの児童福祉総務費と児童措置費なんだけれども、補正予算説明資料は、順番が逆になって、この目の順番で来るのかなと思ったら、２番目の児童措置費が先に来たんだけれども、何か説明の理由があるんですか。","respondent":"伊崎待機児童対策担当課長","answer":"通常でしたらこのとおりご説明するところではありますが、保育事業につきましては、認可保育園を主体として待機児童解消をやっていくというところで考えておりますので、その事業全体の流れに従いまして、認可保育園を先にご説明させていただいたところです。","voiceIndex":62,"id":"exchange-020"},{"speaker":"須藤委員","kind":"意見","question":"何かそういう思いがあればいいんだけれども、あれっと思って、最初の数字を合わせようとしたら違ったというので、その辺がわかるようにしていただけると。それから、同じところで、説明があったのかもしれないけれども、認可保育園、認証保育園で参考として２園ずつ載っているんだけれども、この意味合いは何か。","respondent":"伊崎待機児童対策担当課長","answer":"本件は補正予算のご説明ですので、新しく出てきました園が実は認可保育園は１番から４番目までの４園で、参考としましては、５、６につきましては、当初に計上してはありますが、補正予算の中で金額の精査、増減がございましたので、そちらが多少反映をしているということで。","voiceIndex":64,"id":"exchange-021"},{"speaker":"須藤委員","kind":"質問","question":"そうすると、この数字自体は、その参考を除いた園に対しての数字というふうにして理解しておけばいいですか。","respondent":"伊崎待機児童対策担当課長","answer":"その分はこの補正の総額の中に差し引きされて入っているものです。ですので、認可で申し上げますと４園については全くの新規で補正を組んでいる。参考の２園については、当初予算との増減が補正予算のほうに入っているというつくりになっております。","voiceIndex":66,"id":"exchange-022"},{"speaker":"須藤委員","kind":"質問","question":"はい、わかりました。それはそれでいい。それから、３５ページ、スポーツ教育推進事業、中学校１校、小中一貫校１校というものだけれども、内容的に説明があったのか、もうちょっと詳しく教えていただければと思います。","respondent":"冠木指導課長","answer":"豊葉の杜中学校は、荏原第三中学校と荏原第四中学校が一緒になりまして、当初から陸上競技等々で十分な力をつけてきた学校でございまして、その内容を豊葉の杜中学校としてもやっていきたいということで、走ることを基本とした走力向上の授業。","voiceIndex":70,"id":"exchange-023"},{"speaker":"須藤委員","kind":"質問","question":"このスポーツ教育推進事業というのは、当初予算でなくて補正で上がってきたというのは、何か意味があるのか。それと同時に、こういう推進の事業というものは、この平成２４年度でも続けていくものか、単発でのものなのか教えてください。","respondent":"冠木指導課長","answer":"４年間続いてきておりますので、私どもとしても、引き続きこの事業はあるものとしていろいろと、例えば基本的には手を挙げていただくシステムをとっているんですけれども、体育の部分で区としてこういう学校に力をつけたいというようなことがあった場合には。","voiceIndex":72,"id":"exchange-024"},{"speaker":"須藤委員","kind":"質問","question":"都の推進でこういう形をとってきているというので、品川区も受け入れた。そういうところがあれば、品川区としても一般会計としてこういう方向性をつくっていくということをするだろうと思うんだけれども、そのあたりはどうか。国会でもスポーツ基本法ができて、スポーツの推進というのは非常に言われてきているんだけれども、そういう方向性というのはいかがでしょうか。","respondent":"冠木指導課長","answer":"品川区としても、さまざまな各学校の１校１取り組みというような形で、今、取り組みをやっておりまして、そういうような中で、品川区の体力についても、少し一時期よりは上昇カーブになってきたと、いろいろな種目ありますけれども、瞬発力とか、持久力とか。","voiceIndex":74,"id":"exchange-025"},{"speaker":"阿久津委員","kind":"質問・要望","question":"私も一人の親として、３・１１のときには幼稚園に子どもを預けていたものですから、全く連絡がとれずに、本当に、それを教訓として、また、ご要望もたくさんいただいているものですから非常にありがたいんですが、システムのイメージとしてどういうものなのか、これは１６１万円と計上してありますけれども、これは業者が入ったりするのか、またパソコンの購入とかがあるんでしょうか。","respondent":"吉岡保育課長","answer":"それで、その遅延対策については、インターネットの特性上、１つのルートから回らないときは別のルートから回れるような、いわゆるワールドワイドウェブと言われているインターネットのネットワークの中でいろいろな複数の回路を持つことによって。","voiceIndex":76,"id":"exchange-026"},{"speaker":"阿久津委員","kind":"質問・要望","question":"ありがとうございました。大体のイメージがつかめました。これに頼るというよりは、さまざまな手段を使ううちの補完という形で区民の皆様にもお知らせいただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-027"},{"speaker":"浅野委員長","kind":"質問","question":"今、質問がありましたメール配信サービスの件ですけれども、小中学校はもう既に行われているということで認識はしているんですが、ウェブの配信対象、今、保護者というふうにご回答いただいているんですが、保護者以外の方、例えば子どもからすればおじいちゃん、おばあちゃんとか、例えばご両親が遠くのほうで働いている、今回の３・１１のときには。","respondent":"吉岡保育課長","answer":"ただ、今お話があった祖父母、あるいはそれ以外の親戚の方等、保護者、ご両親以外の方にも配信する可能性については、システムを入れた後の運用も踏まえまして、今後の検討の課題だなと思います。","voiceIndex":79,"id":"exchange-028"}]},{"id":"topic-03","title":"平成２３年陳情第８号、品川区の子どもたちを放射能被ばくから守る為の陳情","agenda":"平成２３年陳情第８号、品川区の子どもたちを放射能被ばくから守る為の陳情","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"１番目には、放射能の汚染の実態調査と除染を求めました。言い切ったんですよね。その辺の理由もあわせてお聞かせいただきたいのと、もう１点、内部被曝に対しての認識、特に乳幼児、小さい子どもたちに対する内部被曝の認識をどう持っていらっしゃるのか、特にここの分科会は子ども未来事業部、そして教育委員会ということで子どもに本当に身近な部署ですので、しっかりとお伺いしたいと思います。","respondent":"齋藤庶務課長","answer":"それが根拠です。内部被曝につきましても、先ほど学務課長、保育課長がご説明したとおり、流通しているものを給食食材で提供しておりますので、内部被曝というものも学校、保育園で改めて対応しなければならないということはございません。","voiceIndex":98,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"公園なんかは、草むらとか、ジャングルジムとか、滑り台の下など、たまりやすい場所を調べてほしい。私はやっぱりはかってみて初めて安心できるというところでは、今やっている、測定をしていることは認めますが、今の測定の箇所数、対応だけでは足りないということを言っていらっしゃるんだと思うんですが、その点についてお答えをいただきたいと思いますが、いかがでしょうか。","respondent":"齋藤庶務課長、和氣学務課長","answer":"基本的な問題につきましては、区の中でも都市環境事業部長がご答弁申し上げたとおり、どの場所でどう測定するかについては環境課で対応する、これがまず第１点お答えします。先ほどもお話しさせていただきましたけれども、実際にこれで書かれているように全品調査を実施すると、給食を出さないということに等しくなります。","voiceIndex":100,"id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この陳情されている方々は、実際に八潮の地域も測定をされています。思ったよりも高いところもあります。特に子どもの成長期には本当に内部被曝は極力抑えたい、これも放射能防護委員会なんかが見解を出していますが、この内部被曝に対して、本当に子どもに対して極力内部被曝をさせないという、やはりこういう立場に立っていただきたいんですが、この２点に対してはいかがでしょうか。","respondent":"齋藤庶務課長、和氣学務課長","answer":"したがって、区内随所でモニタリングを実施した結果、区内ではおおよそ３５％から７５％程度の年間の放射線量しか得られないということでしたので、極めて低い値しか出ていないのに、ここで直ちに洗浄ですとか、土砂の入れかえだとか。私どもは、どうでもいいなんて１つも思ってございませんので、どういうように合理的に子どもたちを守るかということで言いましたら、今ある情報の中で選んでいくしかないし、その中で最善を図るしかないというように考えておりまして。","voiceIndex":103,"id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問","question":"もっときめ細やかにはかってほしいと言っているんです。この１ミリシーベルトでいいんでしょうか。極力ゼロにしてほしい。広島の原爆の２０個分以上のものがばらまかれたんですよね。私は本当に国がやるべきことはたくさんあると思いますけれども、国がやるべきことをやっていない中において、自治体で地域の子どもたちを守るという立場に立てないのでしょうか。なんで品川はできないのでしょうか。","respondent":"齋藤庶務課長","answer":"繰り返しになっておりますけれども、まず、放射線量は、これは都市環境事業部長もご説明申し上げておりますとおり、きめの細かさ、いわゆる１メートルおきに計測すれはいいというものはないんです。","voiceIndex":108,"id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった面では、ここの部分は基準大丈夫、ここの基準も大丈夫、だから大丈夫なんですと言うのは、とても考えられないと思うんですが、この基準値の引き上がっている部分、私は本来の数字に戻すべきである、でないと、子どもと妊産婦の方、おなかに胎児のいらっしゃる方は守れないと思うのと、あと。","respondent":"齋藤庶務課長","answer":"委員のご発言の中で幾つか、水道水の中の放射線物質の値、これは区で定められるものではありませんので、私どもとしてはお答えできないことはご理解願います。","voiceIndex":110,"id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問・要望","question":"機械も買って、いつ機械が届くのでしょうか。私はぜひその機械を使って保護者の皆さんと一緒にはかっていただきたいなと思うんですけれども。今、メッシュではかってと、ホットスポットはメッシュではかったのではあらわれないんですよね。だから、そういった意味では、ここが心配だと思えるところを実際に機械を持っていって一緒にはかっていただきたいなと思うんですけれども、その辺はいかがでしょうか。","respondent":"齋藤庶務課長","answer":"測定につきましては環境課で対応しておりますので、ご意見として承らせていただきます。","voiceIndex":112,"id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この状態を何とか守ってあげたいという立場にぜひ立っていただきたいんですけれども、お母さんたちが、この間、９月１１日に勉強会をされた後にアンケートをとられて、本当に率直な切実な声が載っているので、ちょっと幾つか紹介させていただいてよろしいでしょうか。しかも、３回もということで、親としてとてもつらい思いをしたということとか、給食は安全な食材を使用してほしい。","respondent":"和氣学務課長","answer":"そもそも放射能、シーベルトから何から、単位から非常に難しいことがありまして、その基礎知識についてしっかり勉強していただいていることと、実際の東京都の状態について、これをちゃんと学んでいくというのが中心です。","voiceIndex":114,"id":"exchange-035"},{"speaker":"須藤委員","kind":"質問","question":"今ずっとお話を聞いていると、これを全部１つ１つやるというのは、庶務課長の話だと、なかなか難しいですよというお話が出ていると思うんですが、今、率先的に教育委員会なり、あるいは環境課なりでこういった放射能に対するまちの心配なことに対して、品川区として独自性を持ってこういうことをやってきているよというようなことがあったら教えてください。","respondent":"齋藤庶務課長","answer":"品川区としていち早く区長が取り組んで実施している。これはちょっと答弁漏れだったんですけれども、シンチレーションサーベイメーターは９月中には入っておりましたので、使ってはおります。","voiceIndex":116,"id":"exchange-036"},{"speaker":"須藤委員","kind":"質問","question":"今言ったように、これの時期が終わってすぐに区側に線量計をしっかりとした、今、線量計と言っても、簡単なものだと数値がいろいろ出てきてしまう。食については、今、現時点では、産地とか云々とかということではなくて、いわゆる大丈夫ですというような話で来ているのか、それともそういう福島のほうの産地のものはだめだというような表現で買い入れる食材にしているのか、そのあたりはどうなんですか。","respondent":"和氣学務課長","answer":"そのようにそれぞれのところで、また特にそういうところはしっかり検査をしていますので、そちらの汚染されたものをそのまま出すなんてあり得ない話ですので、私どもはちゃんと検査をして安全だと流通したものというふうな確認をして。","voiceIndex":118,"id":"exchange-037"},{"speaker":"吉田委員","kind":"質問","question":"その中で2)のところで、勉強会等を開催していらっしゃるということ、これは保護者の方は参加していないですよね。それをちょっとお聞きしたいことと、もう１つは、先ほどちょっと飯沼委員のほうから健康被害等のアンケート、私も持っているんですけれども、現実に健康被害等の届けとかあったのかということをちょっとお伺いしたいということ、２点お願いします。","respondent":"和氣学務課長、吉岡保育課長","answer":"もしくはうちの職員を対象にしていますので、まず私どもがしっかりと勉強して周知に努めてやっています。健康被害については一切聞いてございません。具体に何かあったとか、そういうことは一切聞いておりません。保育園におきましても、それぞれ職員、保育園の栄養士、それから、もちろん調理の職員も含めてですけれども、しっかりした情報は把握して対応してまいっております。","voiceIndex":120,"id":"exchange-038"},{"speaker":"吉田委員","kind":"確認","question":"ここのお母さん方に2)があるということは、お母さんたちは、先生方や、また保育士の方々が勉強会をやっていらしたということをご存じないということではないかと思うんですけれども、その辺をちょっと確認します。","respondent":"和氣学務課長","answer":"保護者の方にこういう勉強会をしましたという報告は特にしてございません。内部でやっているものです。","voiceIndex":123,"id":"exchange-039"},{"speaker":"吉田委員","kind":"意見","question":"それがわからないので、やってくれているのだろうかということを、１つ１つなんですけれども、不安を取り除くにも１つの、今、区がやっていることに関して、やっていますよということはわかるんですけれども、そういう意味でも、働きかけたらいいんじゃないかと思うんですけれども、その辺をお願いします。","respondent":"和氣学務課長","answer":"その点については、十分検討させていただいて考えてまいりますので、よろしくお願いします。","voiceIndex":125,"id":"exchange-040"},{"speaker":"阿久津委員","kind":"提案","question":"幾つかご質問します。公明党といたしましても、第３回定例会、今回の定例会でお母様方から伺った意見を踏まえた上で質問をさせていただきました。これに対しては、品川区はこういったものを活用していっていただきたいというご提案と、また、どのようなお考えなのかをひとつお伺いしたいと思います。","respondent":"和氣学務課長","answer":"ということで、これも安全である、安心を与えるためだけにやっているですので、例えば、先ほど言ったように数校、数品種、それだけで安全かどうかということよりも、そういうことをやっているということに意味があるというふうに言っておられるので。","voiceIndex":127,"id":"exchange-041"},{"speaker":"阿久津委員","kind":"質問・要望","question":"これはやはり国としてのこういう考え方を持っているということですから、品川区としても、さっき独自のという考え方を求められたご意見もありましたけれども、これは進めていただきたいというのが要望の１つです。もう１点は、先ほど、すみません、学務課長にまたお伺いしたいんですけれども、また勉強会のことなんですが、８月２６日には教員のセミナーがあって、これはお子様にどう教えるかのセミナーだと。","respondent":"和氣学務課長","answer":"それ以外の栄養士であるとか、教員、管理職を対象にしたものには、都が今、頻繁にやっておりまして、都よりももっと頻度を上げてやるとか、国のほうがしっかりやるとかということについては、私どももつかんで、そちらのほうに行ってちゃんと勉強してきてあります。","voiceIndex":129,"id":"exchange-042"},{"speaker":"阿久津委員","kind":"質問・要望","question":"先ほど何回もありましたけれども、これ、しっかり勉強した内容を、どういったことを勉強されたのかということを区民の方に周知徹底していただくということがやっぱりひとつ安心につながるのではないかというように思いますのでお願いしたいと思います。品川区としては、これはどういう形で教育委員会から学校側に伝え、また保護者に伝わっているのか、これを確認させていただきたいと思います。","respondent":"和氣学務課長、吉岡保育課長","answer":"６月の時点で、全校に対して柔軟に対応するようにということで、弁当、水筒の持参について、各学校で柔軟に対応してほしいという通知を各学校に出しています。保育園におきましても同様の扱いをしてございまして、お弁当、水筒については、お持ちになりたいという申し出については、園のいろいろなほかのキャパシティー等もありますけれども、対応可能な限りお受けするようにということで、園長。","voiceIndex":131,"id":"exchange-043"},{"speaker":"阿久津委員","kind":"確認","question":"ご答弁ありがとうございました。各学校、園に対しては、区としての姿勢を伝えているということなんですが、そこから先の保護者に対してどういう通知がされているのかというのは確認されていらっしゃるでしょうか。","respondent":"和氣学務課長、吉岡保育課長","answer":"学校に積極的に通知を出しているというふうには聞いておりません。基本的に学校も安全な給食を出しているということで認識がありますので、どうしても食べるのが嫌だという方については柔軟に対応してほしい。保育園も同様でございまして、特に保護者の方にお弁当をお持ちになればというお知らせをするようにという指示は園長には出してございませんが、どうしてもご不安があってお弁当を持たせたいという方については対応という実態です。","voiceIndex":134,"id":"exchange-044"},{"speaker":"阿久津委員","kind":"質問・要望","question":"ただ、いわゆる牛肉にセシウムが付着しているかもしれないわらを食べたかもしれない牛肉を使っていた可能性があるということが報道されていて、これが特別な例というふうに言われるかもしれませんけれども、いわゆる安全というところがやっぱりここで言い切れるのかどうかというところで多分お母様方は心配をされているということですので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-045"},{"speaker":"渡部委員","kind":"質問・要望","question":"いろいろな話、今の議論で聞かせていただいた中で、１つだけ確認させていただきたいことが。今、安全、安全じゃないという議論がされているわけなんですけれども、あくまでも品川区にとっての安全というものは、区としては、国の出している基準をもって安全という言葉が動いているということでよろしいでしょうか。そこをお聞きします。","respondent":"齋藤庶務課長","answer":"そのとおりです。","voiceIndex":138,"id":"exchange-046"},{"speaker":"渡部委員","kind":"質問・要望","question":"前の基準値が安全だと思っている人は前の基準値に照らしてこの数値がどうなんだと見ると思いますし、逆にゼロが安全だという方にしてみれば、検出されずが安全で、０.０１でも出てきたら出ているじゃないかというふうに見る人はいますので、これは要望になりますけれども、これから出てくる数値に関しては、まずは安全か安全じゃないにかかわらず、その出た数値をそのまま記載していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":140,"id":"exchange-047"},{"speaker":"渡辺副委員長","kind":"確認","question":"今、断言できなくても、区が今どのように最善を尽くされているかという点で確認の意味で伺えればと思います。測定器のところは、先ほど出ました、ここをちょっと詳しくまた伺えればと思います。周辺状況として、本来国がすべきというところで、先ほど、先般、議会も６月でしたか、意見書を国へとやる中で、区長会の動きを確認の意味を込めて、どのようになっているのか。","respondent":"齋藤庶務課長","answer":"空間線量につきましては、いろいろ物がありまして、東京都が２台お借りしたものは、簡易放射線測定機で、シンチレーションサーベイメーターで計った場合と比較して１.５倍高く出る場合があるものでした。","voiceIndex":141,"id":"exchange-048"},{"speaker":"渡辺副委員長","kind":"質問・要望","question":"それと、区長会要望です、詳しい資料ではなかったんですが、ちょうど特別区長会として６月の時点で、学校、幼稚園、保育所で放射線量の安全基準値を明記してほしいという旨があったかと思うので、そういう周辺状況がまた詳しくわかればなと思ったんですが、方向は方向であるとかと思うので、再度確認をしたいのが、測定器と測定方法、じゃあ、現実問題、拡大をするという中では、僕は今。","respondent":"齋藤庶務課長","answer":"測定器につきましては、２台買い求めました。","voiceIndex":143,"id":"exchange-049"},{"speaker":"木村委員","kind":"質問","question":"行政の方々も一生懸命そういう意味でやっていただいていると思うんですが、やはりこういうふうにしていろいろな陳情など、いろいろお母さんの立場、区民の皆さんの思いに対する気持ちのあらわれだと思いますけれども、そういうことに対して、やっぱり先ほど８０数カ所の地点を２カ所ずつ検査をするということなんですが、それは決まった場所でやっているということですか。","respondent":"齋藤庶務課長","answer":"８４カ所で実施したということです。例えば、八潮であれば、八潮南保育園、八潮学園、八潮公園など。旗の台であれば、第二延山小学校、荏原第五中学校、旗の台保育園、旗の台南公園。","voiceIndex":145,"id":"exchange-050"},{"speaker":"木村委員","kind":"意見","question":"そういうことを努力していただいていることはよくわかるんですが、区民の皆さんの子どもに対しての気持ちの心配は、これ、本当に長期の間やっぱり続くと思うんですが、そういう区民の皆さんの実際に品川区の子どもたちを守る会の方々とのお話をして、また、こういうところをちゃんとやってほしいという意見を聞いて、実際のそういう何かアンケートをとるとか。","respondent":"齋藤庶務課長","answer":"どの場所をどういう形でローテーションして検査するかは区で考えました。今後、どのような形で検査するかにつきましては、環境課のほうで対応してまいりますので、いただいたお話については承るです。","voiceIndex":147,"id":"exchange-051"},{"speaker":"木村委員","kind":"意見","question":"そういうことを考えますと、もっともっと区民の皆さんの考えを区側が取り入れていただいて、そういう検査をやっていただいて、またそれをはっきりと公表、もちろんしていらっしゃるのでしょうけれども、もっともっと区民の皆さんの信頼を得るように、我々、こちらの行政側もやっていかなければいけないのだと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":149,"id":"exchange-052"},{"speaker":"須藤委員","kind":"質問・要望","question":"ただ、行政側にいろいろな意見があったときに、安全と思う、ただ安心感というのはまた違ってくるので、その安心感を与えるためにいろいろな広報を出したりなんかするときにも、先ほど、伝達はこういう形で出していますということで、いたずらに出してしまうことでまた安心感を逆になってきてしまうので、その安全であるということと、安心につなぐというのは非常に難しいところがあるので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-053"},{"speaker":"阿久津委員","kind":"質問・要望","question":"結論を出します。先ほどから各委員からもありましたけれども、子を持つ親として当然の感情の発露の陳情だと思いますし、区も本当に最善を尽くしていただいていると思うんですが、今後もできる限り皆さんの要望のような姿勢が求められるのではないかということで。ただ、表現において一部一学説に寄っているような表現もありますので、趣旨採択という形にさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今日、結論を出すということで。共産党としては、一刻も早く対策をとっていただきたいので採択したいと思いますけれども、子どもを守るために国と、そして自治体ででき得る限りのことを求められていますので、安全対策、不備な部分をぜひ安全を確保する体制に変えていくために、自治体で努力できるところはたくさんあると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":154,"id":"exchange-055"},{"speaker":"渡部委員","kind":"質問・要望","question":"先ほど述べさせていただきました放射能を相当皆様心配されていまして、今後どうなっていくんだろうというのは注視していると思います。理事者の方々からもいろいろなお話を今伺い、やはり出せる情報をしっかり出していく必要があると思います。その検査結果がどうだ、国の基準値を超えた場合は速やかな対策を打っていただくことは要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":155,"id":"exchange-056"},{"speaker":"吉田委員","kind":"質問・要望","question":"みんなの党としては、結論を出していただきたいと思います。行政のほうも柔軟な姿勢をしていただきたいと。今のこの内容ではちょっと難しいところもあるので、気持ちは本当にわかるんですけれども、これから先、長い年月いろいろなことがあると思うので、柔軟に区政のほうがやっていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":156,"id":"exchange-057"}]},{"id":"topic-04","title":"平成２４年度以降の日光林間学園での移動教室等","agenda":"平成２４年度以降の日光林間学園での移動教室等","exchanges":[{"speaker":"須藤委員","kind":"意見","question":"日光林間学園名称変更というのをただいま言っておられたので、これはどういうふうに、請け負った事業者が勝手に決めるのか。それとも区民のほうから公募するとかなんかそういう形でやる、どういう仕組みでやるのか。","respondent":"和氣学務課長","answer":"これは私ども聞いているのは、民間業者がその営業のために使うので、民間業者が決めるというふうに聞いております。","voiceIndex":165,"id":"exchange-058"},{"speaker":"渡部委員","kind":"質問","question":"すみません、１点だけ。これを機に日光でないところでとかという議論はなかったんですか。何かそういう議論というのは。","respondent":"和氣学務課長","answer":"日光は非常に使い勝手がいいということと、総合的な学習をする上でいろいろなものがそろっているので、今後も日光で継続したいという考えです。","voiceIndex":167,"id":"exchange-059"},{"speaker":"飯沼委員","kind":"意見","question":"子どもの負担増にはならないということですが、この使用料を払って利用するということでは、この辺の基準というのは、この貸し付けた業者の一般的なものなのか、区として特別に配慮があるのか、その辺を。","respondent":"和氣学務課長","answer":"これは業者と所轄の部署のほうで料金体系については協議するということになるかと思います。業者が決まらなければ、業者も採算があるでしょうから、そこで決まると思います。私どもについては、基本的に子どもたちに負担をかけない。そういう話になっております。","voiceIndex":171,"id":"exchange-060"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"南恵子議員の「保育の市場化「新システム」はやめよ、待機児解消は区立認可保育園増設で」の中身の中で、ご答弁で、子ども・子育て新システムの中間のまとめの内容が触れられたので、そこの中身で待機児問題をどうとらえているのか、もうちょっと中身をお伺いしたいなと思っています。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問","question":"旗の台のすまいるでおにぎりとカロリーメイト、ほかのところは、例えば備蓄が今回役に立ったとか、そういうことは、夕食といおうか、対応は何かありましたでしょうか。","respondent":"吉岡保育課長","answer":"それぞれのオアシス等で食事に何を使ったかという報告までは受けてございませんけれども、当然あるものの中で対応したというふうに伺ってあります。","voiceIndex":181,"id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4738#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":63806,"voices":184}},{"id":"h23-20110926-5","meetingId":"h23-cm09","date":"2011年9月26日","dateIso":"2011-09-26","committee":"総務委員会","time":"午前１０時００分～午前１１時２５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第４８号議案、品川区特別区税条例の一部を改正する条例","agenda":"第４８号議案、品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"原委員","kind":"質問・要望","question":"ＮＰＯと同じような類似した考え方でしょうけれども、どうでしょうか。それから寄附金税額控除の対象を拡大して全体で５４法人ということなんですけれども、それに関しまして、区としてどんな考え方なのか、この２点を教えていただきたいと思います。","respondent":"高森税務課長","answer":"公益法人につきましては、今、ご指摘いただいたとおり、所得税法第７８条第２項および第３項関係ということで、こちらは所得税法における認定団体ということで認定させてありますので、それを連動した形でこれからも進めていくという考え方でおります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"原委員","kind":"質問・要望","question":"私も今のご説明のとおり、日本って意外とそういう意味での寄附行為等の考え方がまだまだ諸外国に比べておくれている部分がありますので、特に私はそれは非常にいいことかなと考えていますけれども、今後において、逆に今度は区の立場としては、不正がないように厳しく行っていただければと思いますので、その点、答弁いただきたいと思います。","respondent":"高森税務課長","answer":"確かにＮＰＯ法人等、なかなか行政が手の届かないところを、いろいろな形でＮＰＯ団体等々が活動いただいているという状況です。ただその反面、そういう意味での不正のないように、しっかりした形で対応していきたいと考えています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"阿部委員","kind":"質問","question":"そうなるのかということまで区民に浸透しないと、なかなか寄附という行為が広がっていかないと思うんですけれども、その周知等についてはどのようなお考えでしょうか。","respondent":"高森税務課長","answer":"そこに寄附された方、いろいろな条件が実はありまして、単純に、例えば学校法人にただ寄附するだけ、入学に際して寄附する場合はそれは該当外だとか、何十周年記念でもって体育館を立て直すだとか、そういう広いものについては該当するわけなんですけれども、そういう形で。","voiceIndex":9,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"それから４番、５番のところの各種特例税率の影響、それから配当所得等々のこの部分なんですが、先ほどの説明では、始まった時期が平成１５年度からだということだったと思うんですが、改めて４番と５番の両方の開始時期を教えていただきたいのと、それからこういう制度が延長がとられるようになった目的というか、理由というか、このあたりを改めて教えてください。","respondent":"高森税務課長","answer":"それと４点目の各種特例税率の適用期間の延長についての開始時期については、平成１５年から導入されたということで、延長につきましては、申し上げているとおり、さまざまな経済状況等々がよろしくない状況、現下の厳しい経済情勢ということで、冒頭申し上げましたように。","voiceIndex":11,"id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"当初、私も記憶がないですけれども、株式に参入が個人でできるようになることによって、経済状況を活性化させていくのだという説明があったと思うんですけれども、１０年近くたつ中で、品川区として、日本の経済状態がそういう延長をずっと何年間か繰り返す中で、当初の目的のように景気が高揚してきた、あるいはそういう個人投資家を広げる中で、全額控除をされるという措置をとってきている中で。","respondent":"高森税務課長","answer":"この間、３月１１日には東日本大震災という大きなことが起きましたので、そういう状況を見ると、景気は決してよくなってはいないのではないかという認識で、私個人は思ってあります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"ですから、これは区のレベルのことなので、法律というか、そういう改正の中でされていることですけれども、もっとこういう抜本的な経済の改善をしないで、小手先のところをやることで格差がどんどん広がるということはやめるべきだと私は思います。先ほどの課長のご答弁を、それはそれとして伺っておきたいと思います。意見を申し上げました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問","question":"寄附金控除団体、先ほど５４団体という数も言っていますが、この５４団体については、区としては何か公表していくような考え方があるんでしょうか。というのは、かえって公表するのがいいのか悪いのかという判断もあると思うんですけれども、区の考え方と、例えばＮＰＯは３団体しかないですよね。そのＮＰＯ間の中でも差がついてしまう。そこら辺の考え方はどうなるんでしょうか。","respondent":"高森税務課長","answer":"そういう中で、東京都と連動して今回、認定を３団体、品川区内に本拠地というか、本店というか、主たる事業所があるところがありますけれども、そこを認定して公表していくような形になります。","voiceIndex":16,"id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もう１つは、社会福祉法人的なものが１４ですけれども、これは品川区内で運営している法人、区とも関係があるような法人は１４の中にすべて含まれているという判断をしていいんでしょうか。","respondent":"高森税務課長","answer":"今回におきましては、品川区内に本店所在地があるということで、そこの部分につきましては、品川区内に主たる事業所があるという認定になってあります。区と関係している団体すべてということですが、区外の法人につきましては、今回は対象外という形にしています。","voiceIndex":18,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問・要望","question":"罰則規定の改正について教えていただきたいんですが、品川区は税金を徴収するにあたって細心の注意を払って、何とか納めてください、納税してくださいということでお願いしていると思うんです。その境目というのはどの辺なのか、参考までにお聞きしたいんです。どうでしょうか。","respondent":"高森税務課長","answer":"今回の罰則規定の改正というのは、申告に際する課税部分の内容になっておりまして、徴収のほうの話になってしまうとちょっと脱線してしまうわけですけれども、可能な限り区民の方に、お支払いいただけない状況であればご相談いただいて。","voiceIndex":20,"id":"exchange-009"},{"speaker":"阿部委員","kind":"確認","question":"それから認定ＮＰＯ法人なんですけれども、この認定というのは、国税庁長官はそうなんでしょうけれども、区はどこを認定する、しないということに多少なりともかかわった結果の３団体であるのかどうかということ、それから非認定もできる規定があるということなんですけれども、その基準づくりというのは今後進めていかれるのか、それとも当分は非認定のところについては全く動かないということなのか。","respondent":"高森税務課長","answer":"ＮＰＯ法人につきましても、そういう考え方で３団体を認定ＮＰＯ法人として指定しています。それから非認定ＮＰＯ法人につきましては、検討課題ということで受けとめさせていただきたいと思います。","voiceIndex":22,"id":"exchange-010"},{"speaker":"阿部委員","kind":"質問・要望","question":"既に所得税法のほうで都でかかっているものについて今回ということですね。一方で不正の可能性も少しずつ増えていくわけで、慎重でなければいけないと思うんですけれども、ぜひ前向きに議論していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"私は反対です。理由は、先ほど質問した部分の特例控除、株式の部分です。それは質問の中で景気の浮揚策だと言っていたわりには、全然景気が、政権の無責任さぶりもあるとは思うんですけれども、そういう中で、こういうことをしてもなかなか格差が広がるばかりだと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-012"},{"speaker":"阿部委員","kind":"質問","question":"１点だけ教えてください。これは昭和６３年から、要は毎年１年ごとに軽減措置を延長しているという形でずっと続いているんですか。","respondent":"高森税務課長","answer":"このことは平成１８年ぐらいからは毎年延長しているような状況でございまして、ちなみに品川区における影響というところでまだ申し上げていなかったんですけれども、約２０億９,４００万円というのが品川区内における軽減、減額の実態というか。","voiceIndex":37,"id":"exchange-013"}]},{"id":"topic-02","title":"の区民参加による行政評価の実施結果","agenda":"の区民参加による行政評価の実施結果","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"今回、初めて行われた、区民参加の行政評価というのが一通り実施されたということですけれども、改めまして、今回、区議会議員も委員として参加をして、区民と同列というんですかね、同様に一つ一つのテーマを評価したということなんですけれども、うちの会派から出ている委員からもお話を聞いたんですが、若干違和感を感じていたようで、区議がそういうものに区民と同じ立場でかかわるということに関しては。","respondent":"久保田行財政改革担当課長","answer":"ただ今後もこうした形でやっていくかどうかということについては、検討課題であるとは認識しているところでございまして、実際に評価委員会の方々にも今、アンケート調査を行ってありますので、そうした中で改めて意見をお聞きした上で。","voiceIndex":46,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"これは意見ということです。今回の場合は、たしか公募した委員の方は３人ですよね。ここにも書いてあるように３人ですから、あまりにも３人では少な過ぎるんじゃないかなと思いますので、こういう形をとっていく際には、もう少し公募委員の数を増やすということも必要なんじゃないか。ぜひ積極的に検討していただきたいと思っています。そのあたりについて、もし見解があれば伺っていきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"数等の問題、また全体の委員構成の問題もありますが、先ほども申しましたように、いろいろとアンケート調査もありますし、これから今後のあり方についても見直していくというところの中で、検討の課題の１つであるかなと思っているところです。","voiceIndex":48,"id":"exchange-015"},{"speaker":"須貝委員","kind":"質問・要望","question":"質問というよりは意見として、先ほどもありましたが、委員の中に区議会議員が入っている。できるだけ一般の区民に近い、本当に区民が参加しての行政評価を、どのような目でとらえているかということを主として今後、検討課題として、よりいい区民参加による行政評価を目指していただきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"確認","question":"１点確認なんですけれども、委員の方に対しての今後の流れというか、このペーパーの意見にしても、委員の方には確認をしていただいたと思うんですが、この後、議会報告とかホームページに載せていく段階で、こういう状況ですという流れは委員の方に、公募区民の方とか、そういう方々にどういう扱い、連絡をとっているのか、その辺だけ確認をさせてください。","respondent":"久保田行財政改革担当課長","answer":"それらについても区民にも公表はしていくですので、そこのところは委員の方には丁寧な対応はしていきたいと考えているところです。","voiceIndex":51,"id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最後に丁寧な対応をしておかないと、今後にこういうケース、これから行政評価をそのままやるかどうかわからないですけれども、いろいろな委員会等の中で、公募の方等に参加していただいた上で、きちんと最後までフォローしていただきたいと思いますので、よろしくお願いいたします。","respondent":"伊藤委員長、諸岡危機管理室長","answer":"ご発言がないようですので、これで本件を終了いたします。報告事項の(2)、節電に伴う公共施設の対応についてご説明申し上げます。お手元の資料の３枚つづりのものがありますが、こちらをごらんいただきたいと思います。一番下の３枚目についてあります経済産業省からの参考資料があります。","voiceIndex":53,"id":"exchange-018"}]},{"id":"topic-03","title":"の節電に伴う公共施設の対応","agenda":"の節電に伴う公共施設の対応","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"３点伺います。それから３点目なんですけれども、挙げられた公共施設の中で、幾つかは指定管理者等に運営してもらっているのがあると思うんですけれども、閉館ですとか開館時間を短縮することに伴って、多少なりとも契約等の見直しというのはあったのでしょうか。","respondent":"諸岡危機管理室長","answer":"それから委託の関係で、ここには表記してございませんけれども、区の事情によって、こういった施設運営を行ったということから、各業者とそういったことについてどうするのかというのは、それぞれの施設において検討していると聞いております。","voiceIndex":58,"id":"exchange-019"},{"speaker":"阿部委員","kind":"質問","question":"そういうのは別にこだわるところではないんですけれども、なんとなく使用制限となるとどうなんでしょう。何か理由があるんでしょう。でもこれは動かないわけですしね。むしろ委託をしているところはすぐには戻しにくいということなんでしょうかね。直接運営しているということでないと、少し対応に時間がかかるという理解でよろしいんでしょうか。どういうことでしょうか。","respondent":"諸岡危機管理室長","answer":"２点目の児童センター等については、委員のご指摘のとおりでございまして、委託等の業者との関係、人員の配置のローテーション等の都合、もとに戻すのに若干時間がかかったという状況です。","voiceIndex":60,"id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"その辺について区として事前にもう少し、いつごろ解除するからちゃんと整えておきなさいみたいな、そういうことも含めて、指導とか対策というのは、一定程度、９月になったら解除することだって大いに予想してきているわけですから、その辺について、区の姿勢として、どこまでどういうふうに見込んできたのかというところの姿勢の問題というのは私はあると思うので。","respondent":"諸岡危機管理室長","answer":"児童センター等の関係ですが、９日に決定して直ちに翌日ということになりますと、児童センターの場合は、地域ごとに輪番制で休館をしてきたりという、かなり職員のローテーション、あるいは委託業者とのローテーションを細かく決めながら対応してきたということもありますので。","voiceIndex":62,"id":"exchange-021"},{"speaker":"南委員","kind":"意見","question":"私は区が全く努力しないということを言っているつもりはないんですけれども、区民の方々にとりわけ密接にかかわっているセクションなだけに、ここについてはきちんとした対策をとるべきだし、そういう臨機応変にできないということが、委託にしちゃっている問題点だと言わざるを得ないと思いますね。そういうことであれば。やっぱりその辺の改善も含めて、きちんとした対策をとるべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-022"},{"speaker":"須貝委員","kind":"意見","question":"ここはどうする、ここはだめなんだとか、いろいろあったと思うんですが、今回、この節電中に相当数苦情といいますか、さまざまなご意見が区のほうに寄せられたんじゃないかなと推測できるんですが、どんな状況だったのか。特に主立ったものに関して、わかる範囲で結構ですが、ちょっとお話ししていただけますか。","respondent":"諸岡危機管理室長","answer":"ただしこういう厳しい状況であるので、被災地に配慮して、もっと区民として協力して、節電等を図るべきではないかと、そういうご意見もあったと聞いておりますし、また区民生活も非常に支障を来しているから、何とかもう少し節電を緩めるべきではないかとか。","voiceIndex":65,"id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"できるだけ区のほうで対応したかと思うんですが、相当区民にとっても、区にとっても初めての体験なので、東電のほうから、また国の経済産業省のほうからぱっとこういうふうに言われて、品川区全体をどういうふうにするのだというのは大変なことだったと思うんですが、その中で、高齢者の方とかお子さん、その他いろいろ生活をするにあたって不自由を感じている人もいらっしゃると思うので、その辺も今後。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-024"},{"speaker":"塚本委員","kind":"質問・要望","question":"区道上の街路灯とか公園等のいろいろな点灯とか、基本的には９月９日をもって終了と同時に点灯しますと伺っているんですけれども、２点ありまして、１つは、１０月２４日ということで、全部一つ一つつけていかなければいけないという事情がありまして、全部復旧するのに結構時間がかかるということで、個々の区民にとっては、家の前がまだついていないという話が結構聞こえてきます。","respondent":"諸岡危機管理室長","answer":"これを一本一本作業して復旧していくということで、どうしてもある程度の時間がかかるということで、何班か班を組んで、それぞれなるべく点灯するように回っているですが、作業効率なんかの面もあるかと思いますけれども。","voiceIndex":68,"id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問","question":"先ほどの委託先の人員配置の問題でおくれるという話もあったと受け取ったんですが、そういった節電対策の中で、委託先の金額の件も話が出て、節電対応して、ない部分ということになってしまうかもしれないんですが、委託をしたところは、委託で１年間の金額が決まりますよね。その中で人件費の問題、派遣人員の人間の金額も出てくる。契約の問題はどうなっているんでしょうか。どういう形になるのか。","respondent":"阿部経理課長","answer":"今、申し上げたとおり、休んだ期間についても払わなければいけないという契約をしている場合もあると思うんです。その場合には、当然のことながらその人件費がかかわっているわけですので、直ちに計画の変更というものではないと考えております。","voiceIndex":70,"id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"後段の時期があっていれば、当然その方がすぐに入ってくることができると思うんですが、今回の場合、先ほどの質疑だけでは、金額的に、その期間、受託先としては契約が切れているのかなと感じたので、変更契約ができてくればあれですけれども、その辺のところをよくチェックしていただきたいと思います。それは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1892#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":24847,"voices":76}},{"id":"h23-20110927-6","meetingId":"h23-cm09","date":"2011年9月27日","dateIso":"2011-09-27","committee":"区民委員会","time":"午前９時５９分～午後０時２１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"この取り組みなんですけれども、例えば品川区の観光の観点から、ほかの課をまたぐと思うんですけれども、そういった取り組みはなかなか難しいのかなと思うんですけれども、やはり品川ならではのできる企画だと思いますので、できればほかの部署との連携なんかも、すぐにできるものとできないものがあるかもしれませんけれども、その辺の考え方というのをちょっと教えていただければと思います。","respondent":"安藤文化スポーツ振興課長","answer":"他課との連絡調整ですが、先ほどご説明しました、まず第１点としましては、しながわ観光協会と共催でイベントをやります。これは屋形船でめぐるというものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"本多委員","kind":"意見","question":"すばらしい展開になることを期待しています。細かいことですみません、いただいた資料の１０月２３日午後９時からになっています。こちらのパンフレットではちゃんと午前９時から１３時となっているのでいいんですけれども、ちょっと。それだけ言うだけで結構です。","respondent":"安藤文化スポーツ振興課長","answer":"失礼いたしました。訂正します。申しわけございません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"山元委員","kind":"質問・要望","question":"私もちょっと１つお聞きしたいんですが、今、いろいろなところで取り組みをしていただくということですが、周知の方法なんですが、特に御台場というと私、どちらかというと旧街道沿い的なところにおりまして、町会のほうとか、今、いろいろ学校のことで教育委員会のお話もありましたけれども、周知方法としては、かなりのイベントをなさるということなので、周知の方法を教えていただきたいということと。","respondent":"安藤文化スポーツ振興課長","answer":"それについても私のほうから、しながわ観光協会に申し入れていきたいと思っています。","voiceIndex":10,"id":"exchange-003"},{"speaker":"山元委員","kind":"質問","question":"かなり大々的に、大イベントをなさろうということですが、全体的に当初の目標といいますか、人数というんですかね、具体的にどの辺を目標にやろうというのを持っていらっしゃるかと思うんですけれども、その辺の数も教えてください。","respondent":"安藤文化スポーツ振興課長","answer":"特別展になりますと、やはり品川区の歴史館として全国に発信できる、郷土の文化を発信するということで、前年の平成２２年度の品川歴史館特別展「中原街道」につきましては４,３１４人、その前の。","voiceIndex":12,"id":"exchange-004"},{"speaker":"山元委員","kind":"質問","question":"具体的に、「品川を愛した将軍徳川家光」で約６,４００人ということは、７,０００人とかいうような数で、勝手なことを言っちゃっていいんでしょうかね、よろしいんでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"目標としてはやはり「品川を愛した将軍徳川家光」を上回るということで、６,４００人以上を目標にしています。","voiceIndex":14,"id":"exchange-005"},{"speaker":"本多委員","kind":"確認","question":"分担金、今、ご説明いただいたんですけれども、工事費全体の額がもしわかれば教えてください。このレクリエーションホールの解体、壁を壊しているときに、夜間とかは使用可能ということなんですけれども、その安全管理というか、安全確認というところだけ１点教えてください。","respondent":"安藤文化スポーツ振興課長","answer":"それで、区のほうが今言いました１,０１３万円と。計、合わせて２,０２１万円の計上をされています。これに基づいて前年度の平成２２年度に実施設計をしています。平成２１年度には基本設計ということでやってあります。","voiceIndex":20,"id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問","question":"多分、説明会等でそういう意見がなかったのかなと思ったんですけれども、どうなんでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"それで、東京都のほうが月曜日から土曜日まで工事をするということで、東京都のほうも住民に対しては、１０月に入ってから説明をするというふうに聞いています。","voiceIndex":23,"id":"exchange-007"},{"speaker":"宮崎委員","kind":"意見","question":"ちょっとやり方が反対、逆じゃないかなという気がするんですけれども、そこのところは、一応工事期間というのが決まっている、３月末までということで決まっていて、例えば土曜日やるか、やらないかでまたいろいろな、延びたりとかそういうことも出てくるかもしれないですけれども、ぜひそこのところ、住民の方にも配慮した工事にしてほしいと思うんですけれども。","respondent":"安藤文化スポーツ振興課長","answer":"ですから、この施行の実施主体が東京都であるということが第一。それで、東京都は都営住宅の方々に対して責任を持って説明をするというようなお話を聞いています。","voiceIndex":25,"id":"exchange-008"},{"speaker":"宮崎委員","kind":"質問・要望","question":"東京都がやる工事だということ、それはわかるんですけれども、やはりそこに住んでいるのは区民の方ですし、今までも、そこはまだ説明会をやっていない、これからなんですけれども、ぜひ、そういう苦情が出た場合等、工事期間、一応３月末ということで区切っているんですけれども、それはやはり、住民の方の声が出てきたらしっかり対応していただきたいなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"事業者自身にやってもらって、これを自分たちで事業所自身でこういう評価を出してもらって、これで経営会議のほうで必要な指摘をするということになっているんですけれども、事業者自身、こういう評価を出してもらったことに対する点検といいますか、実際に導入なのかという、そういう、この仕組みというのはどういうものなんですか。","respondent":"安藤文化スポーツ振興課長","answer":"指定管理者モニタリングについては、平成１８年モニタリングガイドがございまして、それに基づいて区はやっております。","voiceIndex":32,"id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"委託する側がこの報告に基づいて検査、監査。要するにその内容が具体的にどういうふうにやられているのかというのを伺いたいのですけれどもね。それを評価してもらったのが本当にそういうふうに、適正につながる評価になっているかどうか。要するにそれ自身が、ちゃんとした評価になっているなということがあって、その上で区としても今後どういうふうにしていこうかとかいうことになると思うんですね。","respondent":"安藤文化スポーツ振興課長","answer":"業者からのモニタリングシートの件、そのものをいかにしていくかというような話ですけれども、総合体育館の財団法人品川区スポーツ協会、または財団法人品川文化振興事業団とも、まず第１点目は、モニタリングシートの前に、まず我々が直接業務についてミーティングをやるなり。","voiceIndex":34,"id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問","question":"具体的にどういうふうに。人数の必要枠という、そういう頭数の問題が１つあるのと、あと、実際にどういうメンツを配置しているのかということなんですけれどもね。やはりそういうふうにも見られる。ですから、さっき聞いたのは、頭数をどうするのかとあわせて、どういうメンツを配置していくのかということで、委託する側とされる側の関係はどういうふうになっているのかということです。","respondent":"安藤文化スポーツ振興課長","answer":"ただ、指定管理を行う上で、財団法人品川文化振興事業団と財団法人品川区スポーツ協会に対して委託をしているです。","voiceIndex":36,"id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問","question":"やはり、今の説明ではなかなかやはり、そうだなというふうに腑に落ちないんですよね。ちょっと、この問題についてはいろいろ私も聞きたいことがあるんですけれども、今日はとりあえず、今のこの件で絞って伺いたいんですけれども、ちょっと何かお話があれば。","respondent":"安藤文化スポーツ振興課長","answer":"内部の職員体制については、自主的な団体であるそれぞれが、職員体制については職員配置を考えて決めていることでございまして、区としてはその指定管理者として指定をしたです。","voiceIndex":38,"id":"exchange-013"},{"speaker":"本多委員","kind":"確認","question":"指定管理を区議会のほうで議決をして決めていくことですから、その経緯というものは十分にわかっております。そのいろいろな、すべて使うときも指定管理者の管理が行き届いているのかということだけを確認させてください。","respondent":"安藤文化スポーツ振興課長","answer":"それで、また日野学園のほうとも、そういうイベントだとか、そういうものについては連携をして、スムーズに進むようにしています。","voiceIndex":42,"id":"exchange-014"},{"speaker":"本多委員","kind":"質問・要望","question":"いろいろな声を聞きますと、管理は総合的に財団法人品川区スポーツ協会がやっていただけるということで、総合的に管理をしていただきたいと思うんですけれども、いろいろな参加される方の声を聞きますと、例えば選挙開票事務のときの音響はすごく聞きやすいけれども、小中一貫サミットのときの音響が全然聞こえなかったとか、あと、体育館の中でマイクを使う、例えば何かスポーツの大会とかがあるときに。","respondent":"安藤文化スポーツ振興課長","answer":"ですから、非常に、場所によって聞きづらいところと、スムーズに聞けるところと非常にあるそうで、非常に難しい。ですから、日野学園の小中一貫サミットをやったときは、別途音響設備を中に持ち込んで、四隅に大きなスピーカーを置いてやったという事実があります。","voiceIndex":44,"id":"exchange-015"},{"speaker":"石田副委員長","kind":"質問","question":"体育館ですが、これ、平成２０年、平成２１年、平成２２年と３カ年の管理運営実績が載っていて、管理運営委託料が年々２５０万円前後増になっていて、利用料金は増になったり減になったりという中で、利用料金が減ると今の委託料が増すというような予算執行をしている中で、収入が増えているにもかかわらず管理運営委託料も増えているというのは、それはかかる費用がどんどん。","respondent":"安藤文化スポーツ振興課長","answer":"平成２２年度について、実際に３.１１の２０日間の部分の寒風もございましたという話に、料金が減っているです。大体、こう見てみますと、平成２０年から平成２２年まで２億円前後で、総経費としてなっているです。","voiceIndex":47,"id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"春も、春というか、プレミアム商品券はずっと施策としてやっているんですけれども、実績、春の実績について教えてください。","respondent":"米田商業・観光課長","answer":"春の実績ですが、４月１８日に発売を開始いたしました。金額としては同様です。３億３,０００万円分ということで発行いたしまして、売り切れましたのが５月１８日ということで、発売から約１カ月、３１日間で完売ということになってあります。","voiceIndex":53,"id":"exchange-017"},{"speaker":"藤原委員","kind":"質問・要望","question":"で、一般質問等でこれを続けていってくださいと、私は続けていくだけじゃなくて、増額をしてくださいという要望をしているんですけれども、増額に対しての答弁は全く一般質問でもなく、できませんみたいな話だったのかな。そこでまずお伺いしたいのは、緊急経済対策という形でするんであるならば、緊急経済対策を判断する基準というのは、区として明確に持っているんでしょうか。","respondent":"米田商業・観光課長","answer":"そういう景況調査等を判断材料にいたしまして、今後も緊急経済対策、続けてまいるかどうかというようなことでの検討をしていくものです。","voiceIndex":55,"id":"exchange-018"},{"speaker":"藤原委員","kind":"質問","question":"ということは、景況がよくなったと判断したら、この施策をまずやめちゃうという判断もあるのかということが１点と、であるならば、いつもお伺いするんですけれども、いわゆる商店街へ助成をする、商店街を区として、行政としてどれだけ助けられるかということをいつも考えているわけですよね。において、これだけ成果あるじゃないですか。","respondent":"米田商業・観光課長","answer":"ただ、こちらの施策につきましては緊急経済対策ということで申し述べておるとおり、次年度への発行事業を実施するか否かにつきましては、その都度、区のほうでも商店街連合会と意見交換をしながら進めていくものであると、このように考えてあります。","voiceIndex":57,"id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"課長、わからないというか、納得できないんですよ。商店街振興について、東京都でも、何でも、これから決算が始まると思うんですけれども、金額はそんなに高くないかもしれないけれどもね、産業経済費の中においての割合というのはそんなに、項目は多く出るけれども、金額的にはそんなに大きくないじゃないですか。だって、地域も喜んで、区民も喜んで、商店街の振興にも必ずなっているわけじゃないですか。","respondent":"米田商業・観光課長","answer":"先ほど来申し上げておりますが、現状厳しいというようなことで、その辺のところは十分踏まえつつ、金額の増減等に関しましても来年度どうしていくべきかということにつきまして、今後区のほうで検討を重ねて、また次年度予算に反映させていきたいと考えているところです。","voiceIndex":59,"id":"exchange-020"},{"speaker":"山元委員","kind":"質問・要望","question":"先ほど言った８９％ということは、あと１１％の人が持っていて使えないのか、それに対して区としては、区じゃなく、例えばもうちょっと使える日にちというか、延長できるのか、その辺お考えがあるかどうかも教えていただきたいと思います。","respondent":"米田商業・観光課長","answer":"８月分までで、各商店からの請求があって、各商店にお支払いした部分が８９％です。８月末で使えなくなりますよということは商店街のイベント等でも、商店街の方が常々外の方に、区民の方に向けてお話ししています。","voiceIndex":62,"id":"exchange-021"},{"speaker":"山元委員","kind":"質問・要望","question":"すみません、言い方が悪かった。購入じゃなくて、消費者が買うというか、使う場所というのは偏っていないのかどうかということをお聞きしたかったんですけれども、その辺は把握なさっていれば教えていただきたいと思うんですけれども。","respondent":"米田商業・観光課長","answer":"はっきりとしたデータというのは正直、持ち合わせてはいないんですけれども、いわゆる使える場所というのが区の商店街連合会に加盟している商店街が中心となってまいります。","voiceIndex":64,"id":"exchange-022"},{"speaker":"山元委員","kind":"質問","question":"最後にもう一回。すみません、しつこくてごめんなさい。今、いろいろなところで使えるということですが、今までというか、前回と今回と使用できる商店街というのは変わらないですか。例えば商品券が使えるところが増えたのか、減ったのか、その辺がわかれば教えてください。","respondent":"米田商業・観光課長","answer":"およそ使用のできる商店が２,２００ということで聞いてあります。商店街に加盟していることが一つの使用の条件になりますので、商品券を使いたいんだということで商店街の中に入っていくと、加盟するというような話も聞いてあります。","voiceIndex":66,"id":"exchange-023"},{"speaker":"沢田委員","kind":"質問","question":"ちょっと単純な質問なんですけれども、区役所で販売というのはしていないんですか。区役所の中での販売。","respondent":"米田商業・観光課長","answer":"区役所でということなんですけれども、中小企業センターの中に商店街連合会事務局がありますので、お問い合わせがあった場合は中小企業センターの商店街連合会連事務局、こちらのほうで販売しておりますということで、現在のところ区役所のこちらのほうですと。","voiceIndex":69,"id":"exchange-024"},{"speaker":"沢田委員","kind":"質問","question":"近いんであれですけれども、せっかく区のやっている事業だということもあるので、区役所に例えば商品券を、区の事業だということで置くとか、窓口とかで売っていたらいいんじゃないかなと思ったんですけれども、それは、でも、中小企業センター、そこは確かにそんなに遠くないですけれども、と思って質問しました。","respondent":"米田商業・観光課長","answer":"こちらの取り扱いについては商店街連合会のほうにお願いしているものですので、主体的に、一義的には区役所でなく商店街連合会をはじめとした民間ベースで行っていただくものだと考えていますが、ＰＲ等につきまして何か検討の余地があれば今後工夫を重ねてまいりたい。","voiceIndex":71,"id":"exchange-025"},{"speaker":"石田副委員長","kind":"質問・要望","question":"２点お伺いします。１点、経費で流通促進事業特別助成金１,０００万ちょっと出ているんですが、この概要を教えていただきたいのと、以前から言われているんですが、この商品券、商店によっておつりを渡さない商店がありますね。その中で、区としてそのことについて、一定の基準を設けるのが一つのやり方なのかなと思うんですが、その点の考え方があれば教えてください。","respondent":"米田商業・観光課長","answer":"おつりに関してですけれども、プレミアムという趣旨から考えますと、原則的には５００円の商品券は５００円以上のものに使っていただくということをこちらとしては考えておりまして。","voiceIndex":73,"id":"exchange-026"},{"speaker":"石田副委員長","kind":"質問・要望","question":"できる限り商品券を使っていただいたほうがいいというのはわかりますが、聞いたのは１００円のものを５００円券で買って４００円おつりをもらうという部分に関して、いろいろな考え方があるのかなと思いますが、若干の部分に関してはできる限り品川区商店街連合会と調整していただいて、そういった部分にはできる限り調整していただければという、これは要望で終わります。","respondent":"米田商業・観光課長","answer":"当然ポスターですとか、取扱店一覧ですとか、そういうものは適宜、適切な数量を印刷してＰＲに努めていただく。助成があるからそれを湯水のように使うというようなことはなく、適宜、適正に使っていただきたいとこちらのほうは考えてあります。","voiceIndex":75,"id":"exchange-027"},{"speaker":"宮崎委員","kind":"質問","question":"高齢者の生活を監視するといいますか、そういうところで非常に難しいと思って。どうしても断れないとか、そういうことも非常に言っている人も多いんですけれども、こういう見守りだけじゃなくて、もうちょっと、例えば町会とかを通じての講習会とか、そういうものをどんどん、どんどんやっていくというか、そういうことが必要かなと思うんですけれども、そこら辺の取り組みはどんな感じなんでしょうか。","respondent":"米田商業・観光課長","answer":"「高齢者の消費者被害防止リーフレット」のところで、開いていただきますとトラブル対応のフローチャートということで、主にホームヘルパー、民生委員というようなことで、本人の様子の変化があった場合にどういった対応をとるかということで、一つの目安が書いてあります。","voiceIndex":81,"id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"わかりました。高齢者のほうの啓発というんですかね、もっと町会でもやっているぞというような、アピールできるような、高齢者にも見えるような形でやったほうがいいかななんて思っていますけれども、もうちょっと実践していただけたらなと思っています。何かあれば。","respondent":"米田商業・観光課長","answer":"そういった意味では、既に実践されているところはされておりますが、地域センターのほうで高齢者の方に対する講座ということで、さきに申し上げました出前講座、地域センターに集まっていただいてそういうことをやっていくということも既にやっているところもありますので。","voiceIndex":83,"id":"exchange-029"},{"speaker":"本多委員","kind":"質問・要望","question":"高齢者の方は大体クーリング・オフ制度というのをほとんどご存じだと思うんですが、クーリング・オフ制度の期間を過ぎてもという、この部分がすごく大事な部分だと思うんで、この部分をさらに周知を広めていただきたいと思うんですけれども、そのことと、今は議題が高齢者ですから高齢者対象ですけれども、今、高齢者の方はクーリング・オフ制度というものを相当認識していると思うんですけれども。","respondent":"米田商業・観光課長","answer":"」というようなことが真ん中のあたりに大きく書いてありますけれども、こちらをまた大々的にお知らせしていって、消費生活相談にぜひとも、どういう状況であっても、個々の状況をお伺いしながら最善の方法をとっていきたいと考えていますので。","voiceIndex":86,"id":"exchange-030"},{"speaker":"山元委員","kind":"質問","question":"もう一つ、皆さん集まっていろいろお話しなさるんですが、例えば非通知、これも課長のところにいいのかどうか、ごめんなさい、非通知、要するに自分の家族以外はかからないとかいろいろあると思うんですが、非通知の制御というか、そういう方法もあるんだよなんていう、そんなこともお教えとかはなさっていらっしゃるんですか。","respondent":"米田商業・観光課長、中川原地域振興事業部長","answer":"１点目のご質問ですが、消費者センターでは具体的に相手はどんな会社で、どんな名前を名乗って、電話番号は何番ですかというようなことは聞いてありますので、消費者センターとしてデータは持っておりますので。特に電話なんかは、今生活安全担当のほうで、すぐ出ないで、まず留守録してちゃんと確認してから対応しましょうと周知しているところなんですね。","voiceIndex":88,"id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"ぜひお伺いしたいんですけれども、こういうふうに具体的にいろいろな悪質商法、高齢者をねらったというのは日々出てくると思うんですけれども、なのでぜひお伺いしたいんですけれども、川崎生活安全担当課長にせっかく警視庁から来ていただいているわけですから、この辺について今置かれている立場においてと、また警視庁出身という部分において。","respondent":"川崎生活安全担当課長","answer":"このようにしましょうというのを実例を交えながらお話しして、そして、委員の方々が、個人個人の高齢者の方々に広く伝わるようにいろいろな手を尽くして今、広報、アナウンスしている最中でありますので、今後とも高齢者の方がだまされないように。","voiceIndex":92,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"私は区議会議員ですから、これ、都議会議員だったら所長とか、副所長の対応とか、ちょっと違ってくるのかなという思いがすごくあるんですけれども、やはりその辺の、警視庁と区行政との回付といいますか、やっていただくために、品川区としてはいわゆる伝統的にというか、警視という幹部の警視庁の方に来ていただいているわけですから、その辺もすごく胸に据えていただいて、こういう品川区の区職員として。","respondent":"川崎生活安全担当課長","answer":"ですが、やはり住んでいらっしゃる方から被害者が出ているのも事実であります。ですので、その数をさらに減らせるように警察といろいろ意見を出し合い、工夫し合いながら、犯罪を減らしていきたいと、そのように考えております。","voiceIndex":94,"id":"exchange-033"},{"speaker":"宮崎委員","kind":"質問","question":"このハローワークの移転、これ自体、けしからん話だというふうに思うんですけれども、実際これで移転して、実際にこういう方向で行きそうというふうになるんでしょうかというのが１点と、あと、中小企業センターの産業ＰＲ室、今後どうなっちゃうんでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"ハローワークが紹介を縮小するとかそういうことはございませんで、また、区がかわってやるということはありません。あくまでも品川のハローワークが職業紹介等をしますので、区としましては場所の提供等を行っていくということで、連携しながら進めていくという内容です。","voiceIndex":100,"id":"exchange-034"},{"speaker":"宮崎委員","kind":"質問","question":"いずれにしろ、でもね、品川の駅前からやはりそこは撤退するわけですよ。それは今の説明が、そういうふうに言うけれども、やはり住民から見たら全然不便になるというのは明らかなんですから。そうすると、今の説明ですと、あくまでも品川区は場所を貸すだけという。そうなると、場所代とか、そういうのは今後協定を結んで、応分の負担というか、というのも含めてということになるんでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"場所代ですとか、電気代だとか、そういうかかる経費については今後詰めてまいりたいと思いますけれども、品川区もハローワークと連携して行うという、品川区の実施主体といいますか、主体性もありますので。","voiceIndex":102,"id":"exchange-035"},{"speaker":"藤原委員","kind":"提案","question":"この施策、勝負かけたなという思いがすごくあるんですけれども、今までは若者に対して、若者と限定してはいけないけれども、今までの仕切りは、国と東京都は、広域性があるから、働きに行く場所の広域性があるから、若い方はいわゆる国と東京都という形になっていて、この一番身近な自治体として、サポしながわ、いわゆる高齢者の就活といいますか、に関してはサポしながわとか。","respondent":"福島ものづくり・経営支援課長","answer":"確かに今まで就業支援につきましては、基本的には国や東京都の役割だです。ただ、今回の移転に伴いまして、区としましても積極的に連携を強めていくという明確な姿勢を示していると考えています。","voiceIndex":105,"id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"だから、さっきの答弁の中で、場所を提供するということもおっしゃったけれども、その後で連携という言葉が出たじゃないですか。せっかく品川区でそういう形でやるわけですから、その辺の意気込みとか、こういう形で、まだ決まっているわけじゃないですけれども、その辺の担当課長としての意気込みといいますか、思いをもう一回お伺いしたいんですけれども。","respondent":"福島ものづくり・経営支援課長","answer":"そのように、品川区のこういった施策につきましては全力を挙げて行っておりますので、また、今回ハローワークがこちらのほうに来るということがありますので、区としましても一緒に連携しながら、区内の求人。","voiceIndex":107,"id":"exchange-037"},{"speaker":"藤原委員","kind":"質問・要望","question":"サポしながわもね、高齢者のところの課からそこに行ったとき、私は質問して、何でそこに行くのと質問したんですけれども、まあ、そのときはハローワークのことは頭になかったと思いますが、せっかく１つの中小企業センターの中においてそういう形になるわけですから、あと、要望と言っちゃったんだけれども、もう一つ、最後、質問で終わりたい。","respondent":"福島ものづくり・経営支援課長","answer":"あそこはかなり広いスペースがありますので、十分対応できるのではないかということで、端末自体も相談用に３つ、さらに自分で自由に検索できるようなものを５つ、それが来るように今交渉している段階ですので、そういうことができれば。","voiceIndex":109,"id":"exchange-038"},{"speaker":"本多委員","kind":"質問・要望","question":"品川庁舎と六本木庁舎が港区芝大門に移転するということで、直接は、あまり情報がなければいいんですが、もしその概要、例えば今までこのぐらいの規模とこのぐらいの規模とか、例えば１日何人ぐらいと何人ぐらいが今後は何人ぐらいになるとか、床面積はこのぐらいあるとか、人とか、ものとか、お金とか、その概要がもしわかれば教えていただきたいのと、あとは。","respondent":"福島ものづくり・経営支援課長","answer":"すぐ隣には生活福祉課もありますので、問題があればそちらのほうにつなげて住宅相談ですとか、そういうこともできます。そういった形で、ハローワークが来ることによりましてそういった相談業務が一体的に、また的確に対応できるのではないかと考えています。","voiceIndex":111,"id":"exchange-039"},{"speaker":"本多委員","kind":"質問・要望","question":"これはやはり配慮しなければいけないと思うんですが、今までと、同じ品川でやるにしても、中小企業センターというのはいろいろな目的で来館者も多いので、求人を求める方たちの配慮というものを考えて、その場のつくりを、キャパ的には大丈夫だと思うんですけれども、その辺も配慮していただくようにお願いしたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"プライバシーの問題ですけれども、あそこの部屋は、入ってすぐ入り口がありますので、中に入ればプライバシーは保たれると思いますし、またその中につきましても間仕切りですとか、あるいはパーテーション、そういったものを、まだどれだけつけるか。","voiceIndex":113,"id":"exchange-040"},{"speaker":"石田副委員長","kind":"提案","question":"非常にすばらしい提案だと思います。私、一般質問、予算、決算等で、区役所の庁舎内にハローワークの窓口を設置してほしいとかねてから何度もお願いをし、なかなか区としては、広域的なものであるので、東京都と国にその部分は任せているということでしたが、今回のこの移転に絡んで、区のほうからこういうものを発していただいているというのは非常にうれしく思います。その２点をお願いします。","respondent":"福島ものづくり・経営支援課長","answer":"ワンストップサービスですけれども、なかなか、あそこ、中小企業センターですべてを賄うというのは難しいかと思いますけれども、これでワンストップサービスに限りなく近づいてきたのではないかと思いますので、完全なワンストップサービスは難しいと思いますけれども。","voiceIndex":116,"id":"exchange-041"},{"speaker":"石田副委員長","kind":"質問","question":"１点だけ。この「酔う・喰う・バルin戸越」、このチケットはどこで購入できるのか、それだけ教えてください。","respondent":"米田商業・観光課長","answer":"こちらですけれども、今考えておりますのは、区商店街連合会の事務局、それからしながわ観光協会、それから戸越銀座のほうになると思いますけれども、商店街の事務局、あるいは参加店舗でも売れるようにならないかというようなことで。","voiceIndex":130,"id":"exchange-042"},{"speaker":"宮崎委員","kind":"質問","question":"今の件ですけれど、店舗数はどのぐらい参加の予定でしょうか。","respondent":"米田商業・観光課長","answer":"地区の飲食店を中心に、一つひとつ回らせていただいているところですが、４０店舗は確保して、最終的には四十数店舗になるというようなことで、現在、調整を進めていると聞いてあります。","voiceIndex":132,"id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2618#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":45010,"voices":143}},{"id":"h23-20110927-7","meetingId":"h23-cm09","date":"2011年9月27日","dateIso":"2011-09-27","committee":"厚生委員会","time":"午前１０時００分～午後３時３０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"荏原第二地区 支え愛・ほっとステーションの開設","agenda":"荏原第二地区 支え愛・ほっとステーションの開設","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"生活リズムセンサーですけれども、これは品川第二地区のときも付いてやっていたことなのでしょうか。ちょっと分からなくて。それで、どんなふうにこのセンサーは設置されていくのかなと思うのと、あと対象は、ここに書いてある対象の皆さんなのか、それから警備会社はどこになっているのか、教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"こちらにつきましては、荏原第二地区の中でどういう高齢者がどのように住んでいるかということで、品川第二地区のほうはアンケートをとったり、そういった形で実態把握をし、それから、いろいろな町会の会議であったりとか。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"確認","question":"コーディネーターの役割のところに、生活リズムセンサー等発報情報の確認とあるのですけれども、これは何かがあったときは警備会社のほうで駆けつけて、コーディネーターが駆けつけるというわけではないのですか。","respondent":"原高齢者福祉課長","answer":"発報があった情報を得ることによって、今までにない対応が必要、例えばケアプランの見直しが必要であるとか、この方については緊急の連絡先がもう１カ所あったほうがいいのではないかとか、そういった、起きた後の今後の対応というところで、その情報を十分分析しながら。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もうちょっと突っ込んで教えていただきたいのですが、品川第二地域センターの国の補助事業と、東京都のこの補助事業と、今、生活リズムセンサーのところは違いがあるのだというところがあるので、私はこれはリズムセンサーみたいなものをつけてもらうのは非常にいいことだと思うので、もっと広めてほしいという意味で聞きたいので、どう違うのか。","respondent":"原高齢者福祉課長","answer":"コーディネーターの情報収集の関係ですけれども、こちら、荏原第二地域センターもそうですけれども、ふれあいサポート会議というものが地域の中にございまして、こちらは町会長を含め、それから民生委員を含め、学校のＰＴＡの方を含め。","voiceIndex":9,"id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"２つ、改めてちょっとお伺いしたいのは、今、この生活リズムセンサーをまだつけていないからわからないのだけれども、私は、つけるということは非常にいいことだと思っています。それは即そのときからやるということですよ。","respondent":"原高齢者福祉課長","answer":"夜の場合等々もありますし、そういった状況のなかで、区、民生委員、それからケアスタッフ、こういったところが連携して、そのなかで対応ができるところで対応していくと、こういった形で従前もやっていますし、今後も。","voiceIndex":11,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"どうしてそういうことを聞いたかというと、これ、センサーをつけると、２４時間体制になるではないですか。変な話、夜とか。「あれ、この人」と言って、朝に開けようと言って、開けたりして亡くなっていたなどということがあるわけだけれども、これ、２４時間で、先ほど言った１２時間トイレへ行っていないとか、そうなると、夜中という可能性もあるではないですか。区でも連絡をつけられない。","respondent":"原高齢者福祉課長","answer":"なかには「少し具合が悪くて横になっていました」という方もいらっしゃいますし、電話で対応できれば、状況に応じて確認をしていく。それでもやはり中で倒れているおそれがあるという場合については、かぎを開けて中に入るということも、当然、考えての対応になっております。","voiceIndex":13,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"だから、例えば１カ所に６５０万円かかってもいいんですが、補助が４分の３出てくるでしょう。１カ所で例えば２００万円とかそのようなものだと、１０カ所やっても、区の負担は２,０００万円ではないですか。そういう考えでやっていくのかどうか、あとは東京都もそのような補助金は全部は出せないという割合があるのかどうか、そこら辺のところを教えてください。","respondent":"原高齢者福祉課長","answer":"ただ、それがなくなったときどうするかというところも、一方で視野に入れていかなければいけないわけでして、そういったところを、このなかでも品川第二地域センターと同様にこの３カ年のなかで検証しながら、ほかの地区への展開も含めて、それから財源が。","voiceIndex":15,"id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"このリズムセンサーのことについてお聞きしたいのですが、対象者は、1)に書かれている対象者ということで先ほど高齢者福祉課長からお話があったと思うんですけれども、そういうことで考えていいのでしょうか。結局、幾らぐらいの補助ということになるのかということを教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"料金のところですけれども、こちらの機能にはそういったセンサーと、緊急通報、火災報知器、ここまでがセットされている中身でございまして、今、契約の準備をしているところですけれども、２,８００円ぐらいが契約金額、それから利用者が負担しますので。","voiceIndex":17,"id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"基本的に警備保障会社との契約という点では、今の緊急通報システムとそんなに変わらない利用料で、今のも多分、何か２,８００円ぐらいかかったような記憶があるんですけれども、そんなにかからないという、そういう状況なのでしょうかということと、それから、そこの相差の分も補助事業の対象になるということでいいのですかということをお願いします。","respondent":"原高齢者福祉課長","answer":"そういった意味では、料金そのものは、先ほど言った３つの機能が入っていまして、もっと本当は高いんですけれども、２,８００円ぐらいの想定で今やっている、そういった意味では、従前の緊急通報との関係もこれから私ども。","voiceIndex":19,"id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それともう一つは、品川第二地域センターの実績なんですけれども、４０件と５０件で合わせて９０件の相談があったということなのですが、この相談の内容、大まかなところで結構ですので、この点についてもお聞かせいただけますでしょうか。","respondent":"原高齢者福祉課長","answer":"緊急通報システムと同じ業者を選んでいるというところは、そういう意味では、広範囲にしても、比較的スムーズにそういった展開を考えられるのではないかということも念頭に置きながら、検討していきたいと思っているところです。","voiceIndex":21,"id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それと同時に、緊急通報システムは、こういうリズムセンサーを全地域にも広げていっていただきたいと思いますし、少なくとも今、全区的に実施している緊急通報システムの対象者に対しては、ここでの対象者と同じような形で広げていただくように要望させていただいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-010"}]},{"id":"topic-02","title":"高齢者見守り事業 救急医療情報キットの活用","agenda":"高齢者見守り事業 救急医療情報キットの活用","exchanges":[{"speaker":"向委員","kind":"質問・要望","question":"１つお尋ねなんですが、この販売対象が区内の町会とか自治会ということなのですけれども、私はもっと気軽に、例えば区の担当の課に連絡すればすぐ買い求められるとか、もう少し販売対象の箇所を増やしていただけるとか、そういうお考えがあるかどうかお聞かせください。","respondent":"原高齢者福祉課長","answer":"そういったなかで私ども、こういったものを町会に１つのツールとしてお分けするなかで、町会の中で町会に住んでいる方々がどういった方がいて、どういった方が支援を求めているか、こういったものを考えていただきながら進めていただこうということで。","voiceIndex":29,"id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この情報キットは、各地域でも、今、すごく普及しているということも聞いているのですけれども、大体どれぐらいの自治体で広がっているのか、わかるでしょうか。もし要望が多かったときに、この１,０００セットはさらに増やすことはできるのかどうかお聞かせください。","respondent":"原高齢者福祉課長","answer":"それからあとは、無料でというようなご意見かと思いますけれども、私どもは、こういった見守りは個々の見守りも必要かと思いますけれども、やはり町会単位でその地域の中にどういった方が住んでいて。","voiceIndex":31,"id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり何かあったときはなかなか冷静に対応できないというところでのこの情報キットだと思いますので、高齢者の皆さんに広く広げていただきたいと思うのと、町会の皆さんのなかでも見守りネットワークは本当に大事だなとも思いますし、ご苦労されているということも聞きますので、こういったことも含めてより多くの高齢者にこれを広げていきたいとも思うのですけれども、冷蔵庫に張っておく。","respondent":"原高齢者福祉課長","answer":"先ほど、中身までお見せしなかったのですけれども、こういったシール、これは共通のシールでして、救急車にはこういったマーク、これは難しい名前のマークなのですけれども、世界的な共通のロゴになってございまして。","voiceIndex":33,"id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"救急隊の皆さんには、もう周知されているということで、やはり先ほども言いましたけれども、だれが助けに入るかわからないということで、やはり区内全体に品川区はこのキットを高齢者の皆さんに配っていますということを周知していただけたらと思います。よろしくお願いします。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-014"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これは一体どなたが準備するのでしょうか。先ほどのお話だと、例えば炊飯器のお話とか、お年寄りが一人で準備するのは、なかなかちょっと大変なのではないかと率直に感じたのですけれども。","respondent":"原高齢者福祉課長","answer":"例えば主治医が変わった場合に、前の主治医のまま書きっぱなしではいけませんので、そういう意味では、援助にかかわるスタッフが訪問したときにこういったことを話題にしながら、何か変わったところがあれば変更しましょうということのなかで新しいものにしていくということです。","voiceIndex":36,"id":"exchange-015"},{"speaker":"鶴委員","kind":"質問","question":"先ほど、先行して５町会でというお話がありましたけれども、わかる範疇でもしあれば、１町会、大体今どのくらいの方がという、町会ごとで参考でいいですけれども、平均値でいいですけれども、その数と、それからあと、これは予定個数が１,０００セットなのですけれども、これも例えばプラスチックだとか何だとかセットの、さらにその発注のロットがこの１,０００セットからなのかとかということと。","respondent":"原高齢者福祉課長","answer":"町会にどのくらいかですけれども、高齢者見守りネットワークのなかで実施しているのが５町会、それから、この形で見守りネットワークにはまだ参加していないけれども、これを町会で購入して、それでお分けする形をとっているということで。","voiceIndex":38,"id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それだったら、どこでも手を挙げて町会がそのラインに乗って、２０３町会・自治会があって、みんな手を挙げれば、１０万円ずつ全部お金を出すのかというふうになってしまうではないですか。ここら辺のところをどういう形で直してもらうのか。だから、そこら辺の町会にどういうことをお願いしていくかということをもう一度、どういうふうに運用していくつもりなのか教えていただきたい。","respondent":"原高齢者福祉課長","answer":"ただ、町会、町会の事情の中で、やはりこれは１回やって終わりという事業ではございませんで、やはり継続的にどういうふうに次の役員につなげていくか、これも私も町会と話をする中で、そこが一つ課題なのだ、始めるときはいいけれども、それをどういうふうに継続していくか。","voiceIndex":40,"id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひ見守りネットワークのお金が欲しいわけではなくて、例えばこれをやったら、今、見守りでも高齢者でもアナログで、町会、例えば敬老会の何歳以上の人にお祝いを配るというものは、すべてデータは、町会はアナログです。多分、これをやって、アナログなのですね。要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"この情報キットは1)から5)までありますけれども、これは全国という意味では共通したものかどうかの確認、あえて区独自で何か足したり引いたりしたものがあるかということを確認させていただきたいと思います。どういうふうにこれからそういう実態を見ていくかということ、ちょっと３点お願いいたします。","respondent":"原高齢者福祉課長","answer":"地域のなかでの展開ですけれども、いいものをどのように進めていくか、それから、町会を含めてどのように考えていくのかというところでは、まさに品川第二地域センターあるいは荏原第二地域センターというところもそういうネットワークができているなかで。","voiceIndex":43,"id":"exchange-019"},{"speaker":"若林委員","kind":"質問・要望","question":"コピーをとる行為、写真を用意すること、極端な話、もしかすると健康保険証そのものを入れて、これでいいのだというふうに、そういう方もきっとこの１,０００セットがまたこれから広がっていくなかで、配るなかで、きっとそういう方も、高齢者だからという意味ではなくて、障害のある方だからという意味ではなくて、そういうことはもう往々にあるわけで、更新とともに、最初に配るときの丁寧な。","respondent":"原高齢者福祉課長","answer":"まさに、委員ご指摘のとおり、こういった情報がきちっとまず書かれて、それが上手に運用されていくのが私ども大変重要なもので、物があればいいというこの安心感だけでは、せっかくのものが活きてきませんので、そういった意味では、今、委員ご指摘のところを。","voiceIndex":45,"id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"だから、ぜひ私はこれをもっと、町会の見守りネットワークとあわせてやるというのはすごく有効なことだと思いますので、それはそれで進めていただくのと同時に、自分がやはりこういうふうなもの、あるいはまた地域の方でいろいろな趣味のサークルだとかいろいろなところでみんなで話し合って、こういうのは大事だよねというような。","respondent":"原高齢者福祉課長","answer":"何度かお話しさせていただいていますけれども、この事業を始めたばかりですし、まず、町会の方々が、地域のなかでどういった方が住んでいて、どういった手助けが必要なのかということを行政と一緒になって、これをきっかけに考えていただきながら、ご協力いただきながら。","voiceIndex":47,"id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"自分自身が、薬が変わったらそこに入れることをちょっと意識づけるというか、そういう点でも薬剤師会との連携もすごく大事かなと思うのですけれども、その点と、それからあとは２５０円というお金なのですけれども、先ほど高齢者福祉課長からも、１００円ショップでこのケースを買って、自分たちでコピーして入れるという、そういうふうなこともと言われていましたけれども、そういう点では。","respondent":"原高齢者福祉課長","answer":"薬剤師会との関係ですけれども、こういったところは地域のなかで町会も含めて、先ほどもケアマネジャーのお話もさせていただきましたが、さまざまな方の協力のなかで地域の方を見守っていく、そういったなかに薬剤師がそういう、こういった提供書を配るときに。","voiceIndex":49,"id":"exchange-022"}]},{"id":"topic-03","title":"平成２２年度指定管理者の管理に対するモニタリング・評価の結果","agenda":"平成２２年度指定管理者の管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"荏原特別養護老人ホームのところでの「暮らしの情報シート」、すごくたくさん文章内に出てくるのですけれども、これはとても効果的なものなのでしょうかということもお聞きしたいと思います。それから、同じ荏原特別養護老人ホームのノロウイルスの感染があったということで、いつごろ何人ぐらいが感染して、発生原因は何だったのか、どういう対応がとられたのか、お聞きしたいと思います。","respondent":"原高齢者福祉課長","answer":"ノロウイルスですけれども、２回ほどこちらの４ページの組織管理体制及び業務の適正執行の視点というところでございまして、ちょっと時期のところは十分把握はしてございませんけれども、こういった感染がありますと、私どもも、当然。","voiceIndex":58,"id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ノロウイルスのことで、すみません、何人かかったかというのはわからないですか。わからなければ大丈夫です。事故発生などもあるというのが６ページに書かれて、どういった事故がどれぐらい起きているのかとちょっと不安に思ったのですけれども、具体的にわかれば教えていただきたいと思います。お願いします。","respondent":"原高齢者福祉課長","answer":"なるべく本人が歩ける状況であれば、その持てる能力を活かすなかで対応しているなかで、あるいはご利用者がお一人で歩くなかで転倒するということもございまして、そういったことがこういったところにつながっているです。","voiceIndex":60,"id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"いくつか教えてください。それから、教えていただきたいのは２５ページ、これの小規模多機能サービスの登録者が何名になったのか。２５.４％が５２.５％にショートステイがなっているので、登録者が何人になったのか教えていただきたい。","respondent":"原高齢者福祉課長","answer":"それから２５ページの東大井地域密着型多機能ホームのところですけれども、登録は２５名という形になってございまして、利用者は２０人です。この利用者は、状況によって前後するところですけれども、直近の利用者ということで、数字は、今、２０名です。","voiceIndex":62,"id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それが１つ。満タン。これはもう制度上の問題なので、あまりこれを、利用率を上げるよう頑張ってくれと言うのはかわいそうであって、なかなかそれを調整してうまくやっても、多分、この５２.５％がいいところなのかなと私は思っているので、これを上げるのは非常に難しいところがあると思うので、そこら辺は、評価をするときにもうちょっと違う言い方があったのではないのでしょうか。","respondent":"木下健康福祉事業部長","answer":"小規模多機能のほうは登録制をとっておりまして、ショートステイとは違って急な状況の変化、あるいは家族のさまざまな都合に対しても臨機応変に対応できるというところが、この小規模多機能のショートステイ部門のよさでありますから。","voiceIndex":64,"id":"exchange-026"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"その部分のショートステイの部分については、ぜひ東京都、ほかにも言っていただいて、一番はやはりケアマネジャーの話とその包括の話の横断の話ができないのは、どうやってもおかしいと思うので、別に包括の中で１００％使おうとは思わないけれども、だけれども、何かあったときに小規模のショートステイを使える体制は、全部満タンにしろとは言わないけれども。","respondent":"小川健康課長","answer":"委員ご指摘のとおり、コース型の教室に関しましては、最初に利用料をいただいてしまいますので、欠席をされても、もう返還することはできないという状況になっていますので、そういった意味で、コース型教室についての利用料の収入もアップはしています。","voiceIndex":66,"id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１ページのところで、積極的に評価した事項というところで、「医療ニーズが増加する現状を踏まえ」ということで、「夜勤看護師の配置」ということが書いてあるのですけれども、今、本当に特別養護老人ホームでも医療処置の必要な方が増えていると思うのですが、そこら辺のところがどれぐらいの割合でどんな方が増えているかというあたりが、大まかにわかったら教えていただきたいのと、夜勤看護師。","respondent":"原高齢者福祉課長","answer":"特別養護老人ホームの状況のなかで、医療ニーズがここの施設だけではなく、ほかの施設も含めて少しずつ増えているというような状況のなかで、限られたスタッフのなかで工夫をしながら対応しているという状況で考えているところです。","voiceIndex":68,"id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それと、処遇改善交付金で、若干、改善したということがあると思うのですけれども、そこら辺のところで、どれくらい人材確保という点で状況が変化しているのか、また、賃金面でもどれぐらいそれが効果となっているのか、そこら辺のところがつかんでいるところがありましたら、お聞かせいただきたいと思います。","respondent":"原高齢者福祉課長","answer":"処遇改善のところですけれども、区内でも各法人のなかで月額１万５,０００円でしたか、そういったところもきちっと対応されているというところのなかでは、処遇改善につながっていると理解しています。","voiceIndex":70,"id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほど６ページで、どんな事故があったのかというのは、転倒が多いということで報告がありましたけれども、これは、事故の相談は結構私たちも受けるのですけれども、どの施設でどれくらいの事故があって、どんな対応がされているかは、こういう事故報告みたいなもので、区としてもまとまってとらえられているものがあるのか、具体的なところでちょっとわかったら教えていただきたいのと、それで。","respondent":"原高齢者福祉課長","answer":"そういった取り組みとともに、給付の適正化ということで、こちらのほうも利用者への給付金の通知のなかに、そういったモニタリングを含める形での利用者からの評価をいただくなかで、そういった取り組みのなかで活かしていくこともあわせて実施をしていく。","voiceIndex":72,"id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それと、デイサービスなのですけれども、デイサービスの認知症にしても一般にしても、利用率という点ではもうちょっと向上に努めることということがいろいろ書かれているわけなのですけれども、この全体の需要と供給のバランスという点では、今、デイサービスが５０カ所近くあるのですか、そういう状況になっていると思うのですけれども。","respondent":"原高齢者福祉課長","answer":"災害時のマニュアルの件ですけれども、これは３月１１日の東日本大震災のなかでも、デイサービスも非常に大きな状況のなかで現場で対応していただき、また、区のほうでもその状況の把握に努めたところです。","voiceIndex":74,"id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"本当に災害時のことは想定をしておくことが大事だと、改めて今回の震災から学ぶことができるのではないかと思います。そういう点では、もうぜひ皆さんが災害が起こったときも無事でいられるような対応ということでよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-032"},{"speaker":"若林委員","kind":"質問・要望","question":"健康福祉事業部長の答弁にもありました、大事なモニタリング評価ということで、改めてこれはどういうお立場の方が、どういう期間、このモニタリングをされたのか、これをまず１つ確認したいと思います。","respondent":"原高齢者福祉課長、永尾障害者福祉課長","answer":"そういった意味では、時期としましては、ここに書いてあるのが１つの決算額になりますので、決算は６月、大体５月末で数字が固まりますので、その後、現場に赴き、現場のなかでヒアリング。「迅速な相談支援を行う」ということは、医療や保健所、保健センター、福祉サービスに迅速につなげてあげるというような意味での評価ということでご理解いただきたいと思います。","voiceIndex":77,"id":"exchange-033"},{"speaker":"若林委員","kind":"質問・要望","question":"やはり児童学園は福栄会にさらなるレベルアップを当然求めることは、当然、指定管理者ですので大事ですけれども、それとともに、指定管理者のレベルが上がるということは、区の所管が、例えば発達障害についてのレベルとか理解を本当に上げていかないと、そういう意味では区内のあらゆる、例えば発達障害について言えば、さまざまな施設、機関があって、それがいい意味での切磋琢磨。","respondent":"山田副区長","answer":"今ご指摘のあった発達障害という新しい領域のなかで、どういう療育のあり方がいいのかというのもこれから考えていく視点だと考えています。","voiceIndex":80,"id":"exchange-034"}]},{"id":"topic-04","title":"東品川シルバーセンターの耐震化工事に伴う休館","agenda":"東品川シルバーセンターの耐震化工事に伴う休館","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"ほかに耐震化が必要なシルバーセンターはあるのでしょうか。","respondent":"間部高齢者いきがい課長","answer":"シルバーセンターも、かつてゆたかシルバーセンターですとか、南品川シルバーセンターですとか、それぞれの改修工事、耐震化に伴って順次進めております。今後も幾つか、まだ２つほどですか、予定されているものがありますが、まだ実施時期については未定です。","voiceIndex":87,"id":"exchange-035"},{"speaker":"石田（秀）委員","kind":"質問","question":"これが昭和４７年だと、ここで耐震化工事をやるとなると、結構残ってしまうのかなという感じがしてならないのだけれども、逆に耐震化工事を遅らせてくれとか、それが順次建て替えをしていくなかで、私はあそこにあれがあのまま残るよりは、建て替えのなかで区の意見も言って、それは費用も負担しなければならない部分も出てきたりいろいろあるけれども。","respondent":"間部高齢者いきがい課長","answer":"私が東京都から聞いている範囲では、やはりこの耐震化工事とスーパーリフォームをあわせて実施していき、なるだけ長く使いたいという意向をお持ちのようです。","voiceIndex":91,"id":"exchange-036"}]},{"id":"topic-05","title":"品川寮の新型自立支援センターへの移行","agenda":"品川寮の新型自立支援センターへの移行","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"この変更点のところで、定員に変更はありませんと書いてあるのですけれども、一時保護センターと自立支援センターを一本化して新型になっているということなのですが、１００人と７０人が２５人と４５人ということで、数は減っているのかと思うのですけれども、これは何でなのか、教えていただければと思います。","respondent":"平澤生活福祉課長","answer":"申しわけございません、ちょっと私のほうで舌足らずだった部分があります。世田谷寮は単独の施設で１００人の規模があります。私が申し上げました品川寮の定員が変わらないというのは、あくまでも品川寮の中の定員、７０名定員が変わらないです。","voiceIndex":97,"id":"exchange-037"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ教えてください。自立になった方は、実績で何人ぐらいいらっしゃるのでしょうか。ブロックの中でもいいし、東京都の中でもいいのですが、それを教えてください。","respondent":"平澤生活福祉課長","answer":"利用実績ということで平成１２年１１月から、ちょっと長いのですけれども平成２２年９月までです。緊急一時保護センター全体を利用した方が、入所者が２万６,８００名ほどいらっしゃいました。このなかで、就職した方が１万人強です。","voiceIndex":99,"id":"exchange-038"},{"speaker":"石田（秀）委員","kind":"質問","question":"大変ご苦労いただく事業だと思いますけれども、今言ったように１万人ぐらいの方が就職したということなのですが、そこでデータは終わりでしょうか。それで、もう一度路上生活者に戻ってしまうとか、そういうところまでは追っていないということなのですか。わかればでいいのですが。","respondent":"平澤生活福祉課長","answer":"大変難しいご質問なのですけれども、実を申しますと、そういった弱点を追う、欠点を追うというのですか、これまでの事業の反省を含めまして、就職後というのですか、地域に戻られた後もアフターケアということで、先ほどの図にありますバックアップ部門。","voiceIndex":101,"id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"緊急一時保護センターの世田谷寮がなくなるわけですけれども、この１００人、前は多分、大田寮がもっとたくさん、３００人ぐらいあったと思うのですけれども、路上生活の方そのものがずっと減っていると思うのですけれども、そこら辺で路上生活の方のこの間の推移というあたりをちょっと教えていただきたいのと、それから、今、世田谷寮は１００人定員で、利用状況がどういう状況になっているのかと。","respondent":"平澤生活福祉課長","answer":"何点かのご質問なのですけれども、まず大田寮の定員なのですけれども、大田寮につきましては、この自立支援事業が始まったときの最初のころの事業でございまして、平成１３年８月に開所されております。","voiceIndex":103,"id":"exchange-040"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"路上生活者の推移はまた後で教えていただきたいのですけれども、世田谷寮が９０％ということで、これが、今までは１カ月なのが２週間になるので半分にはなるのですけれども、定員は４分の１になってしまうということですけれども、結構、今はちょっとどういう状況なのかはわからないのですけれども、世田谷寮も入れなくて、親とかいろいろなところに行かざるを得ないというときもありましたけれども。","respondent":"平澤生活福祉課長","answer":"その後、平成１２年から東京都ならびに２３区で路上生活者対策事業を始めたということで少しずつ減ってまいりまして、この見直しをすると申し上げました平成２０年には、８月統計で２,６４５名に減りました。","voiceIndex":105,"id":"exchange-041"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"自立支援住宅の借り上げが５０戸を限度ということなのですけれども、この借り上げは５区で５０戸ということですよね。そうすると、品川区では１０戸相当ということになるのでしょうか。ここのところで、自立準備、自己負担と書いてあるのですけれども、この自己負担とは何が自己負担なのかをちょっと教えていただきたいと思います。","respondent":"平澤生活福祉課長","answer":"委員ご指摘のとおり、品川区は１０戸の予定です。各区１０戸ずつです。この自己負担とは、お金の払い方の話です。実を申しますと、この自立支援住宅にいる間につきましては、食費についても支給します。","voiceIndex":107,"id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"今までの自立支援センターもそういう形で、食費も部屋代もかからずにそこで就労活動をして、仕事が見つかって働いたところを貯めて、部屋を借りるための資金に充てる、というふうなことでやられてきたと思うのですけれども、そういうことでこの自立支援住宅も、食費もかからなければ部屋代もかからずに、働いた分については、次へのステップのための資金に充てることができるという。","respondent":"平澤生活福祉課長","answer":"委員ご指摘のとおりです。","voiceIndex":109,"id":"exchange-043"}]},{"id":"topic-06","title":"後期高齢者医療制度の保険料の概要等","agenda":"後期高齢者医療制度の保険料の概要等","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"均等割の軽減のところ。均等割だけの方が何人くらいいらっしゃって、この８.５割、９割、５割、２割が、それぞれ何人とか、何パーセントとか、わかっていたら教えていただきたいと思います。それと、その隣の所得割軽減、1)、2)、3)というのがあるのですが、そこの人数、または割合もわかっていたら教えていただきたいと思います。","respondent":"榎本高齢者医療担当課長","answer":"もう１点、1)、2)の全額もしくは７５％軽減につきまして、このまま続くかどうかというご質問だったと思うのですけれども、今のところ、東京都内の市区町村につきましては継続という見通しになっております。","voiceIndex":115,"id":"exchange-044"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"東京都がここの平成２２・２３年度で４項目にわたる軽減措置をとって、それをとらないとかなりの額になってしまうものを軽減してきたという経過があると思うのですけれども、ここのところで今回出されていないのが、２ページの財政安定化基金等の活用、１０５億円が今回出されていないのではないかと思うのですけれども、ここのところについては、考え方としては、この財政安定化基金の財源の中身というか。","respondent":"榎本高齢者医療担当課長","answer":"６ページの左下に説明がありますけれども、平成２２年度の決算におきまして、東京都後期高齢者医療広域連合の剰余金が１６億円ほど見込まれました。","voiceIndex":117,"id":"exchange-045"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これは国とともに東京都へもさらなる支援要請ということなのですけれども、いろいろと４項目についても、全部、区市町村が負担ということになっていると思うのですけれども、そういう点では東京都がこの中に入っていないと思うのですけれども、そういう点では東京都に対しても支援の要請は求めていくのが必要なのかなと思うのですけれども、そういう点では東京都に対してどういうふうに。","respondent":"榎本高齢者医療担当課長","answer":"東京都への支援の要請というご質問でございました。前回につきましては、国からの通知がございまして、その上で東京都と協議をいたしまして、東京都と国に東京都後期高齢者医療広域連合の負担にならないように、追加で負担積み増しをしていただいたです。","voiceIndex":119,"id":"exchange-046"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-047"}]},{"id":"topic-07","title":"旗の台高齢者住宅入居者募集","agenda":"旗の台高齢者住宅入居者募集","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"昨日の林町の質問とちょっと重なるのですが、部屋の平米数と総事業費、また、その建設費の補助金は幾らぐらい出ているのか、あと、ここの職員体制を教えてください。それから、要介護になってもいられるところなのかということをお聞かせください。","respondent":"間部高齢者いきがい課長","answer":"それぞれどの部分がという按分については、すみません、詳細な資料を持ち合わせてございません。職員体制につきましては、こちらにつきましても、やはり昨日の林町と同様で、管理者の方、また、生活支援の方、事務の方が配置される予定だと、「ゆ～き」からはお聞きしています。","voiceIndex":126,"id":"exchange-048"},{"speaker":"石田（ち）委員","kind":"質問","question":"この家賃助成のところで、きのうは国が４５％で区が５５％負担するということだったのですけれども、今回は額もちょっと４万円と高いのと、負担割合も区はどれだけ今回ここに出していくのかを教えてください。","respondent":"間部高齢者いきがい課長","answer":"支援についてですけれども、林町につきましては公共団体が建設したということで、東京都の助成がありませんので、国が４５％、区が５５％ということでしたけれども、今回についてのこの民設型につきましては、国が４５％、東京都が２２.５％、区が３２.５％と。","voiceIndex":128,"id":"exchange-049"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それと、これはちょっと、昨日の高齢者住宅とどういうふうに制度が違うのかがよくわからないので、昨日の高齢者住宅だとサービス付き高齢者向け住宅ということで、国の制度で国からしか補助金が出なくて２万５,６００円までが家賃助成ということだったと思うのですけれども、これは地域優良賃貸住宅（高齢者型）ということで。","respondent":"間部高齢者いきがい課長","answer":"大井林町については公設民営型で、かつ９０戸という大規模型、また、この旗の台につきましては、民設民営で１５戸ということで、比較的小規模だということになってございまして、先ほどの家賃助成とからめましても、やはりサービス支援費につきましては。","voiceIndex":130,"id":"exchange-050"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"すみません、制度がすごく複雑で、なかなかわからなくて。昨日のサービス付き高齢者住宅は、高齢者専用賃貸住宅ですとか、高齢者優良賃貸住宅ですとか、あともう一つありましたよね。それで、そういうふうな制度を使うのと、このサービス付き高齢者向け住宅を使うのとの使う対象、そういうふうなものがどう違うのかというところもちょっと制度として教えていただけますでしょうか。","respondent":"間部高齢者いきがい課長","answer":"委員ご指摘のとおり、昔ありました高齢者円滑入居賃貸住宅、高齢者専用賃貸住宅、高齢者優良賃貸住宅ということが一本化されてきて、高齢者住まい法、いわゆる高齢者の居住の安定確保に関する法律に統一されてきたという流れについては正しい認識であると思います。","voiceIndex":132,"id":"exchange-051"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"この家賃の設定ということなのですけれども、これは高齢者優良賃貸住宅などでも多分、近傍家賃ということで近隣の家賃と同じような設定になると思うのですけれども、これが近傍家賃ということになるのかどうなのかというふうなところは、どういうふうにして確認されるのか、この家賃の設定ということに対しての補助金をこれだけ出すわけですから、家賃の補助についても。","respondent":"間部高齢者いきがい課長","answer":"こちらについては「ゆ～き」が調査するなかで、そういう報告を受けたなかで、区としてこの家賃が適正かどうかについては判断したものです。","voiceIndex":134,"id":"exchange-052"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"最後に対象者なのですけれども、この入居者条件のところで2)の要介護１程度までの方も対象になるということなのですけれども、この割合は、自立、全く自分で生活できる方とその認定を受けて要介護状態にある方の割合はどうということはあり得ますでしょうか。そこの確認をお願いいたします。","respondent":"間部高齢者いきがい課長","answer":"結果的に要介護の方が多くなったとしても、先ほどご説明しましたように各住居についてはおふろがなく、ここは共同浴場という形でもありますので、要介護の方が半分以上を占めたとしても、運営が可能な体制についてはとられているということと。","voiceIndex":136,"id":"exchange-053"},{"speaker":"石田（秀）委員","kind":"意見","question":"先ほどの補助金の件なのですが、結果として国が１７％とか東京都が１２％となっているのだけれども、こういう、例えば地域優良賃貸住宅とか、小規模多機能、認知症、それから例えばグループホームとか、施設によって補助金の決まった金額があって、それで例えば何戸入れるよというと、こういう補助金があって、それを足し込んでたまたまここはこういうふうになったのだと思うのだけれども、それでいいのか。","respondent":"間部高齢者いきがい課長","answer":"委員ご指摘のとおりです。","voiceIndex":138,"id":"exchange-054"}]},{"id":"topic-08","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"ＡＣＴなのですけれども、今、京都と岡山という話なのですけれども、東京では有名なところはどこかあるのですか。","respondent":"本保品川区保健所長","answer":"国立精神・神経センター国府台病院というのが正式な名称ですけれども、そこで行って、一応、パイロット事業として３年で行い、うまく成果が出れば国の事業化しようとしたらしいのですけれども、そうは結果としてはならずに、今、ＮＰＯ法人として。","voiceIndex":156,"id":"exchange-055"},{"speaker":"石田（秀）委員","kind":"質問","question":"もうからないから、あまりやりたがらないと私は思っているのですけれども、意気に感じた先生はやるのだけれども、経営的にはあまり合わないからやらないのではないかと思うのですけれども、これは知識的には間違っているのか合っているのか、ここは通所リハビリテーションをやっている、行って見てきますけれども、これは考え方が間違っているのですか。","respondent":"木下健康福祉事業部長","answer":"そういう意味では、取り組みにくい側面はあると思うのですけれども、ただ、老人保健施設の場合には、当然、そのリハビリテーションをやるというのが入っている人に対してもやるということになっていますから、その資源をうまく使えば。","voiceIndex":158,"id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3306#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":82963,"voices":160}},{"id":"h23-20110927-8","meetingId":"h23-cm09","date":"2011年9月27日","dateIso":"2011-09-27","committee":"建設委員会","time":"午前１０時００分～午後０時３８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚副委員長","kind":"意見","question":"対象にはしているけれども少なく見るというのと、そもそも対象としていなかったというのは違うと思うんですけれども、なぜ少なく見るのではなくて対象からあえて外したのか、そこのリスク回避の理由がいまいち今の説明ではよくわからなかったので、そこをご説明いただけますか。","respondent":"三宅都市開発課長","answer":"今、委員もおっしゃられたように、全体を例えば１００％のところを全部５０％に落とすというやり方もあると思いますが、こちらでは、ほかの対象についてはやはりある程度、率はかけていると思いますが、この部分を全体に落とすという方法をとったと。","voiceIndex":4,"id":"exchange-001"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"その理由なんですね。その対象から外した理由はなぜなのか。今のご説明で、あえて外したわけですよね。その理由はなぜなのかというところをご説明いただきたいんですね。そういう予算の組み方は、一つあるとは思うんですけれども、そうではなくて対象から外したというのは別だと思うので、あえて外した理由、それによってリスクを回避したというその理由をご説明いただけますか。","respondent":"三宅都市開発課長、片田防災まちづくり事業部長","answer":"補助対象額の低減の仕方は、やり方はもちろんいろいろあると思うんですが、こちらの地区ではこの共用部分を計上しないということで低減したと。担当課長からも説明の中でお話ししたということの再説明になるかもしれませんけれども、やはり先ほど担当課長が申し上げましたように、サブプライムローンを含めていろいろ同時不況ということの中で、逆に補助金が。","voiceIndex":6,"id":"exchange-002"},{"speaker":"中塚副委員長","kind":"意見","question":"初めから対象になるかどうかわからなかったから対象にしなかったのか、それとも対象になっていたのにあえて外したのか。やはり対象から外した理由が、同じことなんですよ、その理由がわからないんです。","respondent":"片田防災まちづくり事業部長","answer":"だから逆に、きちっと国のほうの補助金がつくという前提ができましたので、今回はそれをいただくということで、対象に入れたと、入れ直したということです。","voiceIndex":10,"id":"exchange-003"}]},{"id":"topic-02","title":"の１、報告事項を行います。 初めに、(1)平成２２年度指定管理者による管理に対するモニタリング・評価","agenda":"の１、報告事項を行います。 初めに、(1)平成２２年度指定管理者による管理に対するモニタリング・評価","exchanges":[{"speaker":"井上委員","kind":"質問","question":"駐輪場のほうなんですけれども、使用料は品川区の歳入として入ってくると思いますので、この運営委託料が昨年は増えていて、また今回下がっていてという、この委託料の変化についてと、平成２２年度の委託料の中での人件費率を教えてください。","respondent":"藤木交通安全担当課長","answer":"この資料の２枚目にありますとおり、平成２１年度から新たに指定管理を開始したものが、駐輪場が増えておりますので、増えたです。","voiceIndex":18,"id":"exchange-004"},{"speaker":"井上委員","kind":"質問・要望","question":"企業努力というのがどういうものかということを、区としては把握をされて、それが今後どういうふうに、もっとそれができるものなのか、できないものなのかということで運営委託料が変わってくると思うので、そこのところはどういうふうに把握をされているのかということと、あと人件費率というのが適正なのか、どういう方たちがそこで雇用されているかというのは。","respondent":"藤木交通安全担当課長","answer":"経費の削減で、昨今の不況に伴いまして、私どももこの指定管理者とよくよく話し合う機会があるんですけれども、その中でどうしても人件費率が８割方を占めているということで、その辺をどうにか削減はできないものかという話し合いをずっとしてまいりました。","voiceIndex":20,"id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"バイクの定期利用のところで７８.２％ということで、大変バイクは必要があるという認識があって、でも定期利用につながって、当日が利用が少ない。どういったところが少ないかというのは、全体で数を出しているんですけれども、そういったところの把握とその改善、せっかくあるものが使われないということなので、どこが一番少なくて、それに対する対策みたいなものはどう考えてされているのでしょうか。","respondent":"藤木交通安全担当課長","answer":"こういう利用率が低いところにつきましては、こちらのほうでも広報啓発ですとかを進めているところです。このような形で駐輪場の利用率の向上を図っていきたいと考えております。","voiceIndex":22,"id":"exchange-006"},{"speaker":"井上委員","kind":"質問・要望","question":"続けて宅建のほうにも行きますが、まず修繕及び改良に関することということで、幾らまでが指定管理者の範囲として修繕の協定を結んでいるのかということが１点と、２点目に退去から入居までの平均日数というところで、先ほど説明に、区営住宅のほうで延長されているというような説明でしたので、区民住宅についてはどうなのかということを別々に評価をさせていただかないといけないなと思ったので。","respondent":"柏原住宅担当課長","answer":"その際に大規模修繕もあわせてやろうという方針でおりますので、大規模修繕分がこちらのほう、若干抜けているというところがございまして、ここの部分については減額となっているです。それから東急コミュニティーのほうです。こちらのほうの退去から入居までの平均日数です。","voiceIndex":24,"id":"exchange-007"},{"speaker":"井上委員","kind":"質問","question":"３番目のお答えの、大規模修繕を区がやったことによる削減ということなので、そうするとこれは、また委託料というのは来年以降、すぐには上がらないとしても、そういう委託料の変化というのを見込んでいるのかということが１点と、普通に考えても退去までの改修・修繕、次の人が入るまでの３カ月というのは、普通の民間でいったらそんな悠長なことはしていないで、希望者もあるし。","respondent":"柏原住宅担当課長","answer":"委託料の部分です。こちらの部分につきましては、平成２６年度までは区の区営住宅の耐震改修工事を計画的に行っておりますので、この部分までは、委託料は、大規模修繕につきましては同様の推移をするであろうというふうに考えています。","voiceIndex":26,"id":"exchange-008"},{"speaker":"井上委員","kind":"質問・要望","question":"進めていただいているということなので、頑張っていただくんですが、ファミーユのほうはオーナー型でもなく、さらに１カ月長いということは、手続の簡素化だけではなくて、何らかのルールづくりというのが区と協議をする必要があるのではないかなというふうに思いますので、その辺を適正に行っていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-009"},{"speaker":"武内委員","kind":"質問・要望","question":"自転車のほうなんですけれども、一番下の「改善が必要とされた原因の分析及び対応方針」の中で、きめ細かな料金設定の導入とか挙げられていますけれども、３年ぐらい前からこの課題が取り上げられて、短時間に対する料金設定とかということも言われているんですけれども、区民とすれば、短時間で安くなったほうがいいというのは当然なので、それからなかなか、多分３年ぐらいになると思うんですけれども。","respondent":"藤木交通安全担当課長、柏原住宅担当課長","answer":"このような実態が現在ありますので、実施にまだ踏み切れていないようなところもあるかなと思うことと、利用率の低いようなところでは、このような制度を導入する必要があるのかなと考えております。滞納者に対する１件の対応回数の考え方です。基本的には、収納率が一番上がるというところが一番の目的ですので、結果として収納率が一定以上キープできれば、これは評価できることと思います。","voiceIndex":30,"id":"exchange-010"},{"speaker":"武内委員","kind":"質問","question":"自転車のほうなんですけれども、そうすると利用目的のほとんどが通勤通学で、短時間ではないよという一定の判断が、ある程度区のほうでされているならば、なぜそれについて改善が必要とされたということで、そういう短時間の導入を目指すような表現が出ているんですか。それは意見で、先ほどの前段のほうの短時間利用について、今後のどうしていくんだというところだけ教えてもらいたいと思います。","respondent":"藤木交通安全担当課長、柏原住宅担当課長","answer":"そういうことで、先ほどのような答弁にさせていただいているんですが、その中に、実際に自転車の駐輪場１００％まで行っていない、あきがあるということで。ただ、先ほども申し上げたように、長期滞納化をしないようにフォローであるとか、それから滞納したまま退去した方というのもいらっしゃいますので、そういったところのフォローとか。","voiceIndex":33,"id":"exchange-011"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"区営住宅、区民住宅の滞納者についてですけれども、滞納の理由について、どういった特徴や傾向があるのかご説明いただきたいのと、滞納の理由についてアンケートだったり、そういう実態調査というのは行っていらっしゃるのか、あわせてご説明いただきたいと思います。","respondent":"柏原住宅担当課長","answer":"公的検査であるとか、定期的な検査というのがあります。こちらのほうを、自社のグループで要員を使って検査を行うということによって、人件費を若干落とすことができたというところが、今回このスケールメリットとなっているです。","voiceIndex":37,"id":"exchange-012"},{"speaker":"中塚副委員長","kind":"質問","question":"もう１つ、スケールメリットのことですけれども、１つ心配で改めて伺いたいのは、建物のいわゆる維持管理になると、保守点検だったりメンテナンスだったり、入居時・退去時の原状回復だったりクリーニングだったり、さまざまな仕事があるわけですけれども、こういうところというのはすべて東急がグループの中で行っているのか、それとも別に、いわゆる一般競争入札みたいな感じで入札制度になっているのか。","respondent":"柏原住宅担当課長","answer":"そういった中で、戸数が多かったものですから、東急コミュニティーだけではなかなか一気に修繕は難しいだろうということで、そういったケースにつきましては区側のほうからも、こういった区内の業者を使ってはどうだろうかという話をしたという経緯はあります。","voiceIndex":39,"id":"exchange-013"},{"speaker":"中塚副委員長","kind":"質問","question":"東急コミュニティーのほうですけれども、先ほど言ったようにメンテナンスだったり原状回復だったりクリーニングだったり、建物というのは日常の中でさまざまな仕事があるわけですよね。これは指定管理者を導入するときの問題意識の１つでもあるんですけれども、そこは改めて仕事づくり、仕事確保に位置づけ直す必要があると思うんですけれども、いかがでしょうか。","respondent":"片田防災まちづくり事業部長","answer":"指定管理者のほうにいろいろ維持管理の部分で委託する際に、一応私どものほうとしては仕様書の中に、できる限り区内業者を活用するようにという一文を必ず設けてありますので、さらに業者のほうにはきちっと伝えていきたいと、このように考えてあります。","voiceIndex":41,"id":"exchange-014"},{"speaker":"中塚副委員長","kind":"意見","question":"できる限りという一文が入っているということであれば、では実態はどうなのか、ちゃんと区内業者に仕事が回っているのか、実態はどうつかんでいるのか、ご説明いただきます。","respondent":"片田防災まちづくり事業部長","answer":"今ちょっと資料を持ち合わせてございませんけれども、そういう仕様書の中できちっとうたい込んだ中で、区のほうとしてもどういう工事を行ったのかというところの中で、今どういう業者が入って参画されているのかというところも、引き続き確認をしていきたいと考えています。","voiceIndex":44,"id":"exchange-015"},{"speaker":"大沢委員","kind":"意見","question":"今ちょっとありました、震災時の修理という話と、それと、自転車のほうでは、節電等、東日本大震災に対応策を施したということで、２点、震災時の対応について聞かせていただいたんですけれども、そもそも委託の契約の中には３.１１の以前から、震災時に向けた決まりというか、委託契約の中に盛り込まれていたのかどうか。","respondent":"柏原住宅担当課長、藤木交通安全担当課長","answer":"それから区民住宅の震災時の復興、仮設住宅の入居の際も、区民住宅の入居というところから指定管理者のほうにお願いしたというところがあります。特に震災云々ということは盛り込んでございません。ただ、震災を踏まえまして、それぞれ対応は必要だということで、協議をしています。","voiceIndex":47,"id":"exchange-016"},{"speaker":"大沢委員","kind":"質問","question":"今、両方とも、協定ということと業務概要について、その意味をうまく解釈しながら運用されてきたように思うんですけれども、このところ、起きては困るんですけれども起こり得るものに対しては、しっかりとした枠組みというか、文書化なり、協定をつくることが必要だと思うんですけれども、そこのところはどうですか。","respondent":"柏原住宅担当課長、片田防災まちづくり事業部長","answer":"協定書についてです。いろいろなことが想定されますので、それをすべてにおいて書き出すというのはなかなか難しいと思いますけれども、いろいろなところで対応ができるような形で、表現については工夫したいと思います。そういう中で、今後そういうことをきちっと意識した上で、通常の維持管理の中でも十分に震災時の緊急時の対応とか、そういうことを配慮するような、逆に指導を指定管理者のほうにもしていきたいというふうに考えています。","voiceIndex":50,"id":"exchange-017"},{"speaker":"大西委員","kind":"意見","question":"ここの役所の駐輪場もそうなんですけれども、大体１台置きに皆さんとめている。おそらく積み上げるのが女性のほうでは難しくて、あいているところをずっと探している。男性であってもかなり最近の自転車は重いのもあると思うんですね。その辺の不都合で、要するに効率の悪い運用になっているのではないかという気がするんですけれども。その辺で利用者の声というのはどういうものがありますか。","respondent":"藤木交通安全担当課長、岩田都市環境事業部長","answer":"現状のラックが、一般的な自転車のサイズぎりぎりに今つくっておりまして、それで若干ラックがスライドしたりするようなものを今入れて、多少入れやすさ、便宜を図っているところではありますけれども、その辺につきましては。基本的には、１日貸しの場合はガチャンというロック式ですけれども、これは平置きで、これはお年寄りも若い人も簡単に置けるという形になっていますので、そういう細かい工夫は業者のほうにさせております。","voiceIndex":54,"id":"exchange-018"}]},{"id":"topic-03","title":"住み替え住宅（大井林町高齢者住宅）の募集","agenda":"住み替え住宅（大井林町高齢者住宅）の募集","exchanges":[{"speaker":"武内委員","kind":"質問","question":"昨日の厚生委員会のほうで、もしかしたらあったのかもしれないんですけれども、まだ料金は出てこないんですか。それで、２０戸確保されて、木密地域と合わせて住戸を確保されていますけれども、どんな状況なのかなということですね。それから木密地域についても、何かこれからやるのか、それとも今もう、あらあらお知らせをして、そういう入居方法を呼びかけているのか、それの状況を教えてください。","respondent":"柏原住宅担当課長、品川防災整備担当課長","answer":"そのうち八潮地区の方からは２５件ほど、いろいろお問い合わせをいただいていまして、特に大井林町関係につきましては、興味があると言っていただいている方が６件ほどいらっしゃいまして、昨日も家賃関係も出ましたので。それから単身住宅のほうに関しましては、今４件ほど興味のある方がいらっしゃいまして、まだ林町のほうは詳しく条件が出ておりませんので、登録というような形で４件、優先的に入れていく可能性があるです。","voiceIndex":61,"id":"exchange-019"},{"speaker":"武内委員","kind":"質問・要望","question":"そうしますと、家賃のほうは、単身で７万５,０００円、二人で１０万円ということで、所得によって補助があるということなので、これを上回ることはないという考え方でいいでしょうか。それで、あとかなり違うのであれでしょうけれども、介護はまた別で料金がかかるのか。確認です。","respondent":"柏原住宅担当課長","answer":"それから生活支援サービス料は単身者がやはり１万円、２人世帯が１万５,０００円ということになってあります。家賃補助についてですけれども、この共益費とか生活支援サービス程度は出るであろうというふうに聞いてあります。","voiceIndex":64,"id":"exchange-020"},{"speaker":"大西委員","kind":"意見","question":"昨今、核家族化が進んで、お年寄りだけが住まうというケースもまた多くなってきていると思うんですけれども、そういう状況の中で、ペットを飼う人が増えてきている。ペットを飼うということで、毎日朝晩と散歩に行くということのニーズが高まってきていると思うんですけれども、この区営住宅とか、公のものに関してはどのようになっていますか。","respondent":"柏原住宅担当課長","answer":"一般的な話としまして、公営住宅、それから区民住宅等々については、ペットにつきましては、動物についてのアレルギーのある方等いらっしゃるとか、いろいろありますので、基本的には原則禁止ということになっていますので、こちらのほう、高齢者住宅につきましても。","voiceIndex":67,"id":"exchange-021"},{"speaker":"大西委員","kind":"質問","question":"なぜだめなのか。今、飼っているけれども、その１代限りではオープンにするとか。猫を飼っているという状況で、今、民間がどしどしそれを認める方向、飼えますよということで、皆さんに住んでもらおうということにしているのとはちょっと逆行している。どうして区営のもの、公のものについてはできないのか。できない理由というのは何なんですか。","respondent":"柏原住宅担当課長","answer":"実際そのほかに住んでいる方たちで、先ほどちょっとふれましたけれども、例えば動物に対してアレルギーがあるであるとか、それから鳴き声であるとか、そういったところでトラブルになるケースが多うありますので。","voiceIndex":69,"id":"exchange-022"},{"speaker":"井上委員","kind":"質問","question":"だから具体的には、対象と考えられる方たちはどのぐらいいるという想定をしているのかということと、あと２０戸の根拠を教えてください。","respondent":"柏原住宅担当課長","answer":"ただし、自由意見欄等々の中で、例えばこれから５年、１０年たったときに、自分が体がもし不自由になったようなときとかは心配であるとか、それから今後の住んでいく中での生活の不安であるとか、そういったところを訴えている方はいらっしゃいまして、実際その高齢者住宅。","voiceIndex":72,"id":"exchange-023"},{"speaker":"井上委員","kind":"質問・要望","question":"９０戸あるうちの２０戸という、その２０戸としたのがあまりよくわからないんですけれども、その根拠があまり説明になっていなかったんですけれども、こういう配分を考えたという、優先順位の枠を設けるということは、高齢者住宅というのはすごくニーズがある中で、間違えれば八潮と密集の限られた人たちの利益誘導みたいに誤解をされかねないということを考えると、その辺のしっかりと説明できる根拠と。","respondent":"柏原住宅担当課長","answer":"申しわけございませんでした。端的に申しますと、アンケートの結果で高齢者住宅を各地区でお望みの方が十数戸ずつあったというところから、２０戸と。要は１０戸１０戸ということで、合わせて２０戸ということでさせていただいたところです。","voiceIndex":74,"id":"exchange-024"},{"speaker":"井上委員","kind":"質問","question":"そうすると、あと７０戸の枠の中で、単身と世帯数というのはどういう枠組みになっているのかというのが１つと、６５歳以上の高齢者というのは、世帯の場合にはどういうふうに、どちらか一方が６５歳以上であれば世帯としていくのかどうかということと、あと、ここに今、障害者の方の障害者住宅を新たにつくるときには、そういったニーズも十分にあるというふうに思うんですが、そういったことはここの中に。","respondent":"柏原住宅担当課長","answer":"７０戸の内訳ですが、これは全部単身です。それから世帯の住宅につきましては、これは住み替え住宅のみでございまして、住み替え住宅のほうで、年齢のほうです。","voiceIndex":76,"id":"exchange-025"},{"speaker":"井上委員","kind":"質問","question":"住み替えのほうだけ６５歳以上の方と、今そんな感じで答えていただいたかなと思うんですが、単身のほうは年齢ないということですか。","respondent":"柏原住宅担当課長","answer":"申しわけございません。基本的にこちらの高齢者住宅は、６５歳以上の方の入居です。世帯の住宅につきましては、住み替え用で用意しておるんですけれども、こちらの住宅につきましては６５歳以上の方。同居する方は６０歳以上の方という要件です。","voiceIndex":78,"id":"exchange-026"}]},{"id":"topic-04","title":"東急大井町線戸越公園駅ホーム延伸工事","agenda":"東急大井町線戸越公園駅ホーム延伸工事","exchanges":[{"speaker":"井上委員","kind":"確認","question":"道路の付替後の、黄色いここの図の部分なんですけれども、踏切はそのまま残るのかどうかという、その確認を。区道の設置と、なくす条例をここでやっていくという話になるのかというふうに思うんですけれども、区道の付替の従前の道路、こういうのはどういうふうにするんですか。","respondent":"山崎マスタープラン担当課長、井浦土木管理課長","answer":"踏切ですけれども、踏切もピンク色の線形で赤の矢印が下におりていますけれども、ここの位置に踏切のほうはずれます。それから区道につきましては、付替を行うですので、条例その他は変更ございません。道路法上の道路の区域の変更になりますので、道路管理者として区域変更の決定を行っていくというふうに考えています。","voiceIndex":84,"id":"exchange-027"},{"speaker":"井上委員","kind":"質問","question":"そうすると、今までの縦のＶ－４０号線という、こちらの踏切、戸越公園と書いてある逆の道路というのはそのままあるけれども、踏切のところで行きどまりという形状のまま放置、放置と言うのはおかしいですけれども、そういうふうになるということですか。","respondent":"山崎マスタープラン担当課長","answer":"委員のおっしゃったとおり、踏切としてということよりも、ホームとして延伸しますので、道路の現道の突き当たりがホームというような形になるものです。","voiceIndex":87,"id":"exchange-028"},{"speaker":"松澤委員","kind":"質問","question":"今の話の続きになりますけれども、ここは一般的に考えたら、今まで踏切に電車がとまって、何でここをこんなに遮断しているのかという話が囲い込まれてしまったのかなというふうに思うんですけれども、これは振りかえたという考え方なんですか。この土地そのものは東急の所有になるんですか。その辺をちょっと１点。","respondent":"松代都市計画課長","answer":"もう少し丁寧に説明しますが、ピンクの土地は今回、東急が土地を買いまして、道路として整備をします。","voiceIndex":90,"id":"exchange-029"},{"speaker":"松澤委員","kind":"質問","question":"何か喜んでいるような声も聞きましたけれども、私からすると、逆に道路が増えて、ここで事故が起こったりしたら、すべて道路管理者が品川区ですから、品川区の責任になるんですね。喜ぶべき状態ではないと思うんです。それなら、全部東急が管理して、道路まで東急が管理しろと、穴があいたら全部東急が処理するんだと、事故が起きても全部東急の責任だというのは、これが当たり前ではないですか。","respondent":"岩田都市環境事業部長","answer":"先ほどの、維持管理費が余分にかかるという考え方もありますけれども、鉄道も重要な公共インフラですので、相互扶助の精神で、お互いにこういう決着を図らざるを得なかったです。","voiceIndex":92,"id":"exchange-030"},{"speaker":"松澤委員","kind":"質問","question":"ここは今のまちづくりの中で、高架化をしようという話がありますよね。もう東急としては道路を付替えたから、国交省から文句を言われないから、このままでいいんだろうというようにされては困るという声があるんですけれども、高架化に対する東急の態度といいますか、これの高架化については協力しましょうとか、やりますよという、そういう担保はしっかりとっているんでしょうか。その辺をお聞きしたい。","respondent":"山崎マスタープラン担当課長","answer":"それで、そうした動きがつけかえ道路の車両の開閉問題とは別にしまして、連立化の検討については引き続き、さまざまな問題がありますけれども、そうした協議は進めてまいるというふうに考えてあります。あるいは東急のほうから聞いてあります。","voiceIndex":94,"id":"exchange-031"},{"speaker":"松澤委員","kind":"質問・要望","question":"そんな意味では、このことによって高架化がおくれるのではなくて、こうすることによって、これは東急が一方的に利益を得ているわけですから、私はこのことによって、一方的に利益を得ている東急に対して、高架化したときにはより広く、高架化の下を品川区に使用させるべきだ、ここを防災倉庫にという構想を持っているんですけれども、高架化というものをしっかり、マスタープラン担当課長。","respondent":"片田防災まちづくり事業部長","answer":"ただ、区のほうとしても、きちっと東急電鉄と、仮にホームを延伸してこのような対応をするにしたとしても、引き続きまちづくりの中で、高架化を含めて十分検討・研究して、ぜひそれを進めていくというような方向で議論をしたいと考えていますので。","voiceIndex":96,"id":"exchange-032"},{"speaker":"中塚副委員長","kind":"確認","question":"少しだけ。この工事費の負担はだれが持つのか、全額東急なのか。確認だけさせてください。駐輪場が現状ありますよね。ホームが延びると駐輪場というのはどうなるのか。東急につくらせるのか、そこの考えも教えてください。新たにつけかえられる道路ですけれども、もう東急は買ったのか、これから買う交渉になるのか、よくわからないので、その経過も教えてください。","respondent":"山崎マスタープラン担当課長、稲川委員長、武藤都市整備下水道課長","answer":"それから駐輪場につきましては、戸越公園は２カ所駐輪場がございまして、駐輪場が新たに設置されるとか、そうした変わるというか変化は、駐輪場に関しては。ほかにご発言ありますか。ないようですので、本件を終了いたします。具体的には「２．実施内容」をご覧ください。大きく３点の内容を実施しております。","voiceIndex":98,"id":"exchange-033"}]},{"id":"topic-05","title":"雨水流出抑制推進事業の実施","agenda":"雨水流出抑制推進事業の実施","exchanges":[{"speaker":"武内委員","kind":"質問","question":"雨水浸透施設の新設だけではなくて、例えば既にあるものを、古くなってまた壊れたりして、また新たな改修をするときに、それも対象と考えていいのでしょうか。","respondent":"武藤都市整備下水道課長","answer":"今回の制度の改正は、新設のみではなく、既設のものを新たに取りかえるものについても助成をすることになっております。","voiceIndex":104,"id":"exchange-034"},{"speaker":"井上委員","kind":"質問","question":"今回の要綱を改正してやっているものは、環境的な配慮と、やはり合流式下水道のデメリット、それで河川を浄化する施策に通じるということで、２点において評価をしているんですけれども、今回この事業の目的として力を入れたいと区が思っている重点と考えているところがどこなのかということと、これについては区内全域で同じ条件で行うのかということと。","respondent":"武藤都市整備下水道課長","answer":"１点目。今回の事業を進めるに当たっての重点は何かというご質問ですけれども、冒頭ご説明いたしましたけれども、今回の雨水、宅地内の雨水浸透施設につきましては、区民の直接的なメリットがございません。","voiceIndex":107,"id":"exchange-035"},{"speaker":"井上委員","kind":"質問・要望","question":"平等に助成しますよではなくて、目的達成のためにそういうエリア、指定とまではやらなくても、こういうところがということで、自分たちはそういうところに住んでいるんだという、そういう住民の意識向上も必要かというふうに思うので、その辺をもう少し力を入れる何か考え方がないのかということと、あと助成に対する申請なんですけれども、そういうことが煩雑であると。","respondent":"武藤都市整備下水道課長","answer":"はＰＲを重点的に進めたいと思いますけれども、窓口で区民の方々と相談する中で、何か制度等に改善すべき点があれば、検討はしていきたいと考えております。","voiceIndex":109,"id":"exchange-036"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひ建て主だけではなくて、工務店とか事業者の方がその情報を一番詳しく知っているので、そちらに積極的に情報提供をすることと、やはり目的をとにかく達成することは、区民にとっても行政としても先のことを考えるとすごくメリットがある施策なので、ぜひそういうところに力を入れていただきたいと要望をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-037"},{"speaker":"松澤委員","kind":"質問・要望","question":"ただ、この財源そのものが品川区独自の財源なのかどうかということ。なぜかというと、雨水利用タンク助成なども、これはすごくいいと思っているんですけれども、あまり利用されていないですよね。そんな面からすると、やはり我々が見て、これは各戸建てでやってくれれば浸水対策にもいいなと感じますけれども、本当に区民にとってのやるだけのメリットがあるかどうか、意識は薄いと思います。","respondent":"武藤都市整備下水道課長","answer":"今回の宅地内雨水浸透施設の財源ですけれども、まず宅地内雨水浸透施設設置事業は、都での補助事業となっておりまして、区の負担分に対しまして２７.５％が東京都から補助されます。残る７２.５％につきましても、特別区財政調整交付金等の申請を行う予定を考えております。","voiceIndex":113,"id":"exchange-038"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"冒頭の説明で、一定規模の開発は除外というご説明でしたけれども、どういうことなのか、除外する理由は何か、ご説明いただきたいと思います。それと、いわゆる区有施設ですね。区の施設というのはそもそもこういうことをしようとみずからはやっているのか、これからはどうなのか。これまでのご説明ですと、積極的に進めていきたいということですけれども、まずは区有施設はどうなのか、ご説明ください。","respondent":"武藤都市整備下水道課長","answer":"区有施設に対する地下浸透施設等の設置につきましてですけれども、これにつきましては昭和６１年のころから、いわゆる総合治水対策というものが、雨に対する対策として、東京都・区が一緒になってこういったものを進めていこうということをその当時から進めておりまして。","voiceIndex":116,"id":"exchange-039"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"対象地域は区内全域ということですけれども、品川区内もがけだったり、坂が多いですから、そういうところで何か雨が降ったときに地盤が緩むということというのは、詳しくはわからないけれども心配だなと思うんですけれども、そういうところというのはどういう対策、対応になってくるのか、ご説明いただきたい。","respondent":"武藤都市整備下水道課長","answer":"そこで東京都におきまして、浸透適地マップというものを作成しておりまして、そういったものを見ながら浸透の施設の設置場所だとかそういうものを、申請者等と事前にやりとりする中で検討しています。","voiceIndex":118,"id":"exchange-040"}]},{"id":"topic-06","title":"では、２の行政視察についてでございますが、本件は関係理事者のみお残りいただく予定でございますので、順番を入れかえまして","agenda":"では、２の行政視察についてでございますが、本件は関係理事者のみお残りいただく予定でございますので、順番を入れかえまして","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"災害時の要支援の考え方として、伊藤議員のときでも要支援の名簿の個人情報に関連しての提供のあり方という答弁がありまして、その中でまた鈴木ひろ子議員からは、要援護者支援計画というものを立てた上で、この中に要援護者の人たちを定めて、こういう対策をとっているというふうにいただいているんですが、その答弁に対して、個人情報に優先して災害時の情報提供というのはされるというようなことが。","respondent":"中山防災課長","answer":"要援護者の関係です。お手元にお配りしております何枚かの資料がありますけれども、もともとの流れをちょっとご説明申し上げたいと思います。","voiceIndex":134,"id":"exchange-041"},{"speaker":"井上委員","kind":"意見","question":"そうすると、災害時要援護者という方たちと、一般的に災害時に１人では避難が難しくて支援が必要だというふうな人たちと、この場合には同じ人を指すのかという疑問があるんですけれども、それが区の見解としては同じと考えるのか、全然、防災の災害時要援護者というのとは別のものですよという見解なのか。","respondent":"中山防災課長","answer":"この方については、高齢者見守り名簿ということで民生委員が調査して、３年ごとに１回伺って、いるかいないかどうかを見ていくですので、この対象者は今のところ、私どもの名簿には入ってございません。","voiceIndex":136,"id":"exchange-042"},{"speaker":"井上委員","kind":"確認","question":"普通に見守りが必要な人が、防災時にも当然見守りが必要な人だと考えると、今行っている災害時要援護者と、地域にいる要援護者が別のものというふうであれば、ふだんの中において必要なことが緊急に災害時においてもつながっているということを、庁内で統一見解として持たなければ、今おっしゃったように名簿が幾つもあるという状況は、やはり普通に地域の人が支援をしましょうということは。","respondent":"中山防災課長","answer":"緊急かつやむをえない場合というのは、第２５条の第２項にありますように、人の生命、身体または財産を保護するため、緊急かつやむをえないと認められるときとありますので、これを緊急のとき。","voiceIndex":138,"id":"exchange-043"},{"speaker":"井上委員","kind":"質問","question":"だとすると、手持ちが不足しているという状況になって、でもそれは防災課が持つのではなくて、区としての情報提供であるということであれば、地域全体で健康福祉事業部と名簿を一本化するような仕組みをつくっていくことが望ましいというふうに思うんですが、それについてはいかがでしょうか。","respondent":"片田防災まちづくり事業部長","answer":"防災のほうの共助の立場から、きちっとその辺の体制づくりを行っていくということの中での、今回の名簿作成と共有をして対応していくというようなところで、今進めてありますので、個別な部分での普通の見守りということとなると。","voiceIndex":140,"id":"exchange-044"},{"speaker":"井上委員","kind":"質問","question":"第３条の第２項のところで、名簿受領者の必要な措置を講ずるというところが、町会長のさっきの資料の名簿受領書というものなんだろうというふうに思うんですけれども、これがサインをされる方というのは、すごくハードルが高いのではないかという心労もあるのではないかという、防災区民組織本部長に当たる方、そういうところで、それをもってしないで何らかの災害時とか。","respondent":"中山防災課長、片田防災まちづくり事業部長","answer":"例えば、しかしながら民生委員の守秘義務だとか、行政資料などとは一緒にはできないというような理屈を言っているわけで、そういうふうにはなかなか一緒にならないので。それぞれ先ほどの繰り返しになるかもしれませんが、一応防災のほうでできることと、地域の防災区民組織の中で、いろいろこういう内容とか、介護、要援護者に対してどういうような対応ができるのか。","voiceIndex":142,"id":"exchange-045"},{"speaker":"井上委員","kind":"質問","question":"それなのに、外部提供の協議書を出しながら、情報提供を得なければいけないという仕組みが理解できないのですが、その辺は変わることができないものなのか、そこのところはどうなんでしょうか。","respondent":"岩田都市環境事業部長","answer":"ちょっと話を整理しますと、先ほど防災の担当課長がお答えしたのは、あくまで防災課という小さな課の立場でしか今お答えできなかったので、申しわけないんですけれども、防災行政というのは区全体で動くのが防災体制ですから。","voiceIndex":145,"id":"exchange-046"},{"speaker":"中塚副委員長","kind":"質問","question":"災害時要援護者の対象について伺いたいと思います。端的に伺いますと、なぜこの要綱に、一人暮らし高齢者、認知症高齢者、寝たきり等高齢者、あと言語障害者、難病患者、知的障害者、精神障害者、妊産婦、乳幼児が災害時要援護者の対象とされていないのか、ご説明ください。","respondent":"中山防災課長、片田防災まちづくり事業部長","answer":"私ども把握できているといいますか、情報をいただいているのはこれだけなんですね。そういう中で、それぞれの避難所についても、それぞれの設備の差があるといったような状況を認識しています。そういう中での必要な検討を行っていくという区の考え方に変わりありません。","voiceIndex":148,"id":"exchange-047"},{"speaker":"中塚副委員長","kind":"確認","question":"研究したいというお話ですけれども、私は直ちに対象とすべきだと思うんですね。もう１つ、現在、手上げ方式ですけれども、なぜこれを同意方式にしないのかということも伺いたいんですね。国のマニュアルでも、手上げ方式ではなかなか１割程度にとどまっているから、同意方式による本人からの確認を進めることが望ましいとされているんですね。急いでやるべきだと思うんですけれども、いかがでしょうか。","respondent":"片田防災まちづくり事業部長","answer":"そういう意味でも、やはり地域での見守りとか、それぞれの実態をつかんでいる所管、そこと十分連携をし合って進めていくということが必要だと考えておりますので、そういうふうに状況については認識しておりますし、検討課題として私どものほうも考えているところです。","voiceIndex":151,"id":"exchange-048"},{"speaker":"中塚副委員長","kind":"質問","question":"本会議の答弁をもう少し詳しく聞きたいなということです。昨日も言いましたので簡単にしか言いませんけれども、３０年間行われたまちづくりの課題の総括ということですけれども、どういうふうに進めていくのか、どういうメンバーなのか、その方法と、あと今後、マスタープランの中で再構築ということですけれども、再構築の方向、考え方、その中身を教えてください。","respondent":"三宅都市開発課長、山崎マスタープラン担当課長","answer":"１点目の、大崎駅周辺地域のこれまでのまちづくりの検証ですけれども、大崎駅周辺地域まちづくり連絡会とも調整しながら、区として行う予定です。こうした新たなまちづくりの動向を踏まえ、まちづくりマスタープランへの反映などを今後検討してまいりたいと考えているものです。","voiceIndex":154,"id":"exchange-049"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"再開発の総括のほうに限って伺いたいんですけれども、今まで立てた計画と、実際立て終わった計画が、どう反映しているかと、そういうご説明だったのかなというふうに思うんですけれども、どのような効果が上がっているかというツールというか、どこを見るのか、少し具体的にご説明いただきたいと思います。ぜひ公表というか、明らかにしていただきたいと思うんですけれども、いかがでしょうか。","respondent":"三宅都市開発課長","answer":"最後に、報告書という体裁かどうかですが、こういう検証したことにつきましては十分、内容につきましては報告書という形にまとめた上で、ご報告をしたいと考えております。","voiceIndex":159,"id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4018#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":50173,"voices":172}}]);
